export enum Language {
  FRENCH = 'French',
  ENGLISH = 'English'
}

export type VoiceName = 'Kore' | 'Puck' | 'Charon' | 'Fenrir' | 'Zephyr';

export interface TTSConfig {
  text: string;
  language: Language;
  voice: VoiceName;
}

export interface AudioResult {
  blob: Blob;
  url: string;
}

/**
 * Decodes a base64 string to a Uint8Array
 */
export function decodeBase64(base64: string): Uint8Array {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Encapsulates raw PCM data into a WAV container
 * Gemini TTS returns 24kHz mono PCM 16-bit
 */
export function createWavBlob(pcmData: Uint8Array, sampleRate: number = 24000): Blob {
  const header = new ArrayBuffer(44);
  const view = new DataView(header);

  // RIFF chunk descriptor
  view.setUint32(0, 0x52494646, false); // "RIFF"
  view.setUint32(4, 36 + pcmData.length, true); // chunk size
  view.setUint32(8, 0x57415645, false); // "WAVE"

  // fmt sub-chunk
  view.setUint32(12, 0x666d7420, false); // "fmt "
  view.setUint32(16, 16, true); // subchunk1size (16 for PCM)
  view.setUint16(20, 1, true); // audio format (1 for PCM)
  view.setUint16(22, 1, true); // num channels (1 for mono)
  view.setUint32(24, sampleRate, true); // sample rate
  view.setUint32(28, sampleRate * 2, true); // byte rate (sampleRate * numChannels * bitsPerSample/8)
  view.setUint16(32, 2, true); // block align (numChannels * bitsPerSample/8)
  view.setUint16(34, 16, true); // bits per sample

  // data sub-chunk
  view.setUint32(36, 0x64617461, false); // "data"
  view.setUint32(40, pcmData.length, true); // subchunk2size

  return new Blob([header, pcmData], { type: 'audio/wav' });
}

import { GoogleGenAI, Modality } from "@google/genai";
import { TTSConfig, AudioResult } from "../types";
import { decodeBase64, createWavBlob } from "../utils/audioConverter";

export async function generateSpeech(config: TTSConfig): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Prompting with style/tone instructions based on language
  const prompt = config.language === 'French' 
    ? `Dis de manière naturelle et posée : ${config.text}`
    : `Speak clearly and naturally: ${config.text}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: config.voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data received from Gemini API.");
    }

    const pcmBytes = decodeBase64(base64Audio);
    const wavBlob = createWavBlob(pcmBytes, 24000);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      blob: wavBlob,
      url: audioUrl
    };
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    throw error;
  }
}

import React, { useState, useCallback } from 'react';
import { generateSpeech } from './services/geminiService';
import { Language, VoiceName, TTSConfig, AudioResult } from './types';

// Simple Lucide-like icons for visual appeal
const AudioIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>
);

const DownloadIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
);

const LoadingSpinner = () => (
  <svg className="animate-spin h-5 w-5 mr-3 text-white" viewBox="0 0 24 24">
    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
  </svg>
);

const VOICES: { name: VoiceName; desc: string }[] = [
  { name: 'Kore', desc: 'Sérieux & Professionnel' },
  { name: 'Puck', desc: 'Enjoué & Dynamique' },
  { name: 'Charon', desc: 'Profond & Calme' },
  { name: 'Fenrir', desc: 'Chaleureux & Accueillant' },
  { name: 'Zephyr', desc: 'Clair & Doux' }
];

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!text.trim()) {
      setError("Veuillez saisir du texte avant de continuer.");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setAudioResult(null);

    try {
      const result = await generateSpeech({ text, language, voice });
      setAudioResult(result);
    } catch (err: any) {
      setError("Une erreur est survenue lors de la génération de l'audio. Veuillez réessayer.");
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadAudio = () => {
    if (!audioResult) return;
    const link = document.createElement('a');
    link.href = audioResult.url;
    link.download = `voxgen-audio-${Date.now()}.wav`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4 sm:px-6 lg:px-8">
