                Texte à convertir
              </label>
              <textarea
                id="text-input"
                rows={6}
                className="block w-full rounded-xl border-slate-200 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-4 bg-slate-50 resize-none transition-all outline-none border focus:bg-white"
                placeholder={language === Language.FRENCH ? "Collez votre texte ici..." : "Paste your text here..."}
                value={text}
                onChange={(e) => setText(e.target.value)}
              />
            </div>

            {/* Controls */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Langue</label>
                <div className="flex gap-2">
                  <button
                    onClick={() => setLanguage(Language.FRENCH)}
                    className={`flex-1 py-2.5 px-4 rounded-lg text-sm font-medium transition-all ${
                      language === Language.FRENCH
                        ? 'bg-indigo-600 text-white shadow-md'
                        : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                    }`}
                  >
                    Français
                  </button>
                  <button
                    onClick={() => setLanguage(Language.ENGLISH)}
                    className={`flex-1 py-2.5 px-4 rounded-lg text-sm font-medium transition-all ${
                      language === Language.ENGLISH
                        ? 'bg-indigo-600 text-white shadow-md'
                        : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                    }`}
                  >
                    English
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Voix</label>
                <select
                  value={voice}
                  onChange={(e) => setVoice(e.target.value as VoiceName)}
                  className="block w-full py-2.5 px-3 rounded-lg border-slate-200 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm bg-slate-100 outline-none border"
                >
                  {VOICES.map((v) => (
                    <option key={v.name} value={v.name}>
                      {v.name} ({v.desc})
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Error Message */}
            {error && (
              <div className="mb-6 p-4 bg-red-50 border-l-4 border-red-500 text-red-700 text-sm">
                {error}
              </div>
            )}

            {/* Actions */}
            <div className="flex flex-col gap-4">
              <button
                onClick={handleGenerate}
                disabled={isGenerating}
                className={`w-full flex items-center justify-center px-6 py-4 border border-transparent text-base font-bold rounded-xl shadow-lg transition-all ${
                  isGenerating 
                  ? 'bg-slate-400 cursor-not-allowed' 
                  : 'bg-indigo-600 hover:bg-indigo-700 text-white transform hover:-translate-y-0.5'
                }`}
              >
