  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!text.trim()) {
      setError("Veuillez saisir du texte avant de continuer.");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setAudioResult(null);

    try {
      const result = await generateSpeech({ text, language, voice });
      setAudioResult(result);
    } catch (err: any) {
      setError("Une erreur est survenue lors de la génération de l'audio. Veuillez réessayer.");
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, voiceToPreview: VoiceName) => {
    e.stopPropagation();
    if (previewingVoice) return;

    setPreviewingVoice(voiceToPreview);
    const previewText = language === Language.FRENCH 
      ? `Bonjour, je suis la voix ${voiceToPreview}.` 
      : `Hello, I am the ${voiceToPreview} voice.`;

    try {
      const result = await generateSpeech({ text: previewText, language, voice: voiceToPreview });
      const audio = new Audio(result.url);
      audio.onended = () => setPreviewingVoice(null);
      await audio.play();
    } catch (err) {
      console.error("Preview failed", err);
      setPreviewingVoice(null);
    }
  };

  const downloadAudio = () => {
    if (!audioResult) return;
    const link = document.createElement('a');
    link.href = audioResult.url;
    link.download = `voxgen-audio-${Date.now()}.wav`;
    document.body.appendChild(link);
