                className="block w-full rounded-xl border-slate-200 shadow-sm focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 sm:text-base p-5 bg-slate-50 resize-none transition-all outline-none border focus:bg-white"
                placeholder={language === Language.FRENCH ? "Collez votre texte ici..." : "Paste your text here..."}
                value={text}
                onChange={(e) => setText(e.target.value)}
              />
