                  </button>
                ))}
              </div>
            </div>

            {/* Voice Selection Grid */}
            <div className="mb-10">
              <label className="block text-sm font-bold text-slate-700 mb-3 uppercase tracking-wider">Choisir une voix</label>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {VOICES.map((v) => (
                  <div
                    key={v.name}
                    onClick={() => setVoice(v.name)}
                    className={`relative p-4 rounded-xl border-2 cursor-pointer transition-all group ${
                      voice === v.name
                        ? 'bg-indigo-50 border-indigo-600 ring-2 ring-indigo-600/10'
                        : 'bg-white border-slate-100 hover:border-slate-200'
                    }`}
                  >
                    <div className="flex justify-between items-start mb-1">
                      <span className={`font-bold text-base ${voice === v.name ? 'text-indigo-700' : 'text-slate-900'}`}>
                        {v.name}
                      </span>
                      <button
                        onClick={(e) => handlePreview(e, v.name)}
                        disabled={previewingVoice !== null}
                        className={`p-1.5 rounded-full transition-all ${
                          previewingVoice === v.name
                            ? 'bg-indigo-600 text-white'
                            : 'bg-slate-100 text-slate-400 group-hover:bg-indigo-100 group-hover:text-indigo-600'
                        }`}
                        title="Écouter un aperçu"
                      >
                        {previewingVoice === v.name ? (
                          <LoadingSpinner className="h-4 w-4 text-white" />
                        ) : (
                          <PlayIcon />
                        )}
                      </button>
                    </div>
                    <p className={`text-xs leading-tight ${voice === v.name ? 'text-indigo-600/80' : 'text-slate-500'}`}>
                      {v.desc}
