            <div className="space-y-6">
              <button
                onClick={handleGenerate}
                disabled={isGenerating}
                className={`w-full flex items-center justify-center px-6 py-5 border border-transparent text-lg font-bold rounded-2xl shadow-xl transition-all ${
                  isGenerating 
                  ? 'bg-slate-300 cursor-not-allowed text-slate-500' 
                  : 'bg-indigo-600 hover:bg-indigo-700 text-white transform hover:-translate-y-1 hover:shadow-indigo-200'
                }`}
              >
                {isGenerating ? (
                  <>
                    <LoadingSpinner className="mr-3 h-6 w-6" />
                    Conversion en cours...
                  </>
                ) : (
                  'Convertir en Audio'
                )}
              </button>

              {/* Audio Result */}
              {audioResult && (
                <div className="p-8 bg-indigo-50/50 rounded-2xl border-2 border-indigo-100 animate-fadeIn shadow-inner">
                  <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-indigo-600 rounded-lg text-white">
                      <AudioIcon />
                    </div>
                    <h3 className="text-lg font-bold text-slate-900">Audio Généré</h3>
                  </div>
                  <div className="flex flex-col gap-6">
                    <audio controls src={audioResult.url} className="w-full h-14" />
                    <button
                      onClick={downloadAudio}
                      className="flex items-center justify-center gap-3 px-6 py-4 bg-white border-2 border-slate-200 rounded-xl text-slate-700 font-bold hover:bg-slate-50 hover:border-indigo-200 transition-all shadow-sm"
                    >
                      <DownloadIcon /> Télécharger le fichier (.wav)
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Footer info */}
        <p className="text-center mt-10 text-slate-400 text-sm font-medium">
          Propulsé par Gemini 2.5 Flash TTS &bull; Qualité Studio 24kHz
        </p>
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

