export enum Language {
  FRENCH = 'French',
  ENGLISH = 'English',
  SPANISH = 'Spanish',
  GERMAN = 'German',
  ITALIAN = 'Italian'
}

export type VoiceName = 'Kore' | 'Puck' | 'Charon' | 'Fenrir' | 'Zephyr';

export interface TTSConfig {
  text: string;
  language: Language;
  voice: VoiceName;
}

export interface AudioResult {
  blob: Blob;
  url: string;
  pcmData: Uint8Array;
}

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { TTSConfig, AudioResult, Language } from "../types";
import { decodeBase64, createWavBlob } from "../utils/audioConverter";

export async function detectLanguage(text: string): Promise<Language> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Identify the language of the following text and return ONLY one of these values: French, English, Spanish, German, Italian. If unsure, default to English. Text: "${text.substring(0, 500)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { 
              type: Type.STRING,
              description: "The detected language name."
            }
          },
          required: ["language"]
        }
      }
    });

    const json = JSON.parse(response.text);
    const detected = json.language as Language;

    // Validate if it's one of our supported languages
    if (Object.values(Language).includes(detected)) {
      return detected;
    }
    return Language.ENGLISH;
  } catch (error) {
    console.error("Language detection error:", error);
    return Language.ENGLISH;
  }
}

export async function generateSpeech(config: TTSConfig): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const languageInstructions: Record<Language, string> = {
    [Language.FRENCH]: "Dis de manière naturelle et posée :",
    [Language.ENGLISH]: "Speak clearly and naturally:",
    [Language.SPANISH]: "Habla de forma clara y natural:",
    [Language.GERMAN]: "Sprich klar und natürlich:",
    [Language.ITALIAN]: "Parla in modo chiaro e naturale:"
  };

  const prompt = `${languageInstructions[config.language]} ${config.text}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: config.voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data received from Gemini API.");
    }

    const pcmBytes = decodeBase64(base64Audio);
    const wavBlob = createWavBlob(pcmBytes, 24000);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      blob: wavBlob,
      url: audioUrl,
      pcmData: pcmBytes
    };
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    throw error;
  }
}

