                      key={lang.id}
                      onClick={() => setLanguage(lang.id)}
                      className={`py-3 px-3 rounded-xl text-sm font-bold transition-all border-2 flex items-center justify-center gap-2 ${
                        language === lang.id
                          ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100'
                          : 'bg-white border-slate-100 text-slate-600 hover:border-slate-300'
                      }`}
                    >
                      <span>{lang.flag}</span> {lang.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Voice Section */}
              <div>
                <label className="block text-sm font-bold text-slate-400 uppercase tracking-[0.2em] mb-4">Voix & Ton</label>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {VOICES.map((v) => (
                    <div
                      key={v.name}
                      onClick={() => setVoice(v.name)}
                      className={`relative p-3 rounded-xl border-2 cursor-pointer transition-all group ${
                        voice === v.name
                          ? 'bg-indigo-50 border-indigo-600'
                          : 'bg-white border-slate-100 hover:border-slate-200'
                      }`}
                    >
                      <div className="flex justify-between items-center mb-0.5">
                        <span className={`font-bold text-sm ${voice === v.name ? 'text-indigo-700' : 'text-slate-800'}`}>{v.name}</span>
                        <button
                          onClick={(e) => handlePreview(e, v.name)}
                          disabled={previewingVoice !== null}
                          className={`p-1 rounded-full transition-all ${
                            previewingVoice === v.name ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'
                          }`}
                        >
                          {previewingVoice === v.name ? <LoadingSpinner className="h-3.5 w-3.5 text-white" /> : <PlayIcon className="w-3.5 h-3.5" />}
                        </button>
                      </div>
                      <p className="text-[10px] text-slate-500 leading-none">{v.desc}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Error Message */}
            {error && (
              <div className="mb-8 p-5 bg-red-50 border-l-4 border-red-500 text-red-700 text-sm rounded-r-2xl animate-shake">
                <span className="font-bold">Attention :</span> {error}
              </div>
            )}

            {/* Action Area */}
            <div className="space-y-8">
              <button
                onClick={handleGenerate}
                disabled={isGenerating || !text.trim()}
                className={`w-full flex items-center justify-center px-6 py-6 border border-transparent text-xl font-black rounded-3xl shadow-[0_20px_40px_-10px_rgba(79,70,229,0.3)] transition-all ${
                  isGenerating || !text.trim()
                  ? 'bg-slate-200 cursor-not-allowed text-slate-400' 
                  : 'bg-indigo-600 hover:bg-indigo-700 text-white transform hover:-translate-y-1.5'
                }`}
              >
                {isGenerating ? (
                  <>
                    <LoadingSpinner className="mr-4 h-7 w-7 text-white" />
                    Synthèse vocale en cours...
                  </>
                ) : (
                  'Générer la voix'
                )}
              </button>

              {/* Audio Result Card */}
              {audioResult && (
                <div className="p-10 bg-gradient-to-br from-indigo-50 to-white rounded-[2.5rem] border-2 border-indigo-100 animate-fadeInUp shadow-xl relative">
                  <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                      <div className="p-3 bg-indigo-600 rounded-2xl text-white shadow-lg">
                        <AudioIcon />
                      </div>
                      <div>
                        <h3 className="text-xl font-black text-slate-900">Audio Prêt</h3>
                        <p className="text-sm text-slate-500 font-medium">Format haute-définition stéréo</p>
                      </div>
                    </div>
                    <button 
                      onClick={clearAudioResult}
                      className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-400 hover:text-red-500 bg-white border border-slate-100 rounded-xl transition-all hover:border-red-100 shadow-sm"
                    >
                      <TrashIcon size={14} /> Effacer le résultat
                    </button>
                  </div>
                  <div className="flex flex-col md:flex-row items-center gap-6">
                    <audio controls src={audioResult.url} className="w-full h-16 rounded-xl" />
                    <button
                      onClick={downloadAudio}
                      disabled={isDownloading}
                      className={`flex items-center justify-center gap-3 px-8 py-5 rounded-2xl font-black text-sm uppercase tracking-wider transition-all shadow-md min-w-[240px] border-2 ${
                        isDownloading
                        ? 'bg-slate-100 border-slate-200 text-slate-400'
                        : 'bg-white border-slate-100 text-slate-900 hover:border-indigo-600 hover:text-indigo-600'
                      }`}
                    >
                      {isDownloading ? (
                        <>
                          <LoadingSpinner className="h-5 w-5 text-indigo-600" />
                          Conversion MP3...
                        </>
                      ) : (
                        <>
                          <DownloadIcon /> Télécharger MP3
                        </>
                      )}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Brand Footer */}
        <div className="mt-16 text-center space-y-4">
          <p className="text-slate-400 text-sm font-bold uppercase tracking-[0.3em]">
            VoxGen Enterprise &bull; Technologie Gemini 2.5
          </p>
          <div className="flex justify-center gap-8 opacity-30 grayscale hover:grayscale-0 transition-all duration-500">
            <span className="font-black text-slate-900">STUDIO QUALITY</span>
            <span className="font-black text-slate-900">AI POWERED</span>
            <span className="font-black text-slate-900">NO LIMITS</span>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes fadeInDown {
          from { opacity: 0; transform: translateY(-20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        .animate-fadeInUp { animation: fadeInUp 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
        .animate-fadeInDown { animation: fadeInDown 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
        .animate-shake { animation: shake 0.3s ease-in-out; }

        audio::-webkit-media-controls-panel {
          background-color: transparent;
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { generateSpeech, detectLanguage } from './services/geminiService';
import { Language, VoiceName, AudioResult } from './types';
import { convertPcmToMp3 } from './utils/mp3Converter';
import mammoth from 'mammoth';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js Worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.0.379/build/pdf.worker.mjs`;

// Icons
const AudioIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>
);

const DownloadIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
);

const UploadIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
);

const DriveIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M7.74 2L2 12L5.43 18L11.17 8L7.74 2Z" fill="#0066DA"/>
    <path d="M16.26 2L11.17 11L14.6 17H22L18.83 11.5L16.26 2Z" fill="#00AC47"/>
    <path d="M11.17 11L5.43 21H18.83L22 15.5L16.26 5.5L11.17 11Z" fill="#FFBA00"/>
    <path d="M11.17 11L5.43 21H18.83L11.17 11Z" fill="#EA4335"/>
  </svg>
);

const TrashIcon = ({ size = 16 }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
);

const MagicIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2v2"/><path d="M12 20v2"/><path d="m4.93 4.93 1.41 1.41"/><path d="m17.66 17.66 1.41 1.41"/><path d="M2 12h2"/><path d="M20 12h2"/><path d="m6.34 17.66-1.41 1.41"/><path d="m19.07 4.93-1.41 1.41"/></svg>
);

const PlayIcon = ({ className = "w-4 h-4" }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
);

const LoadingSpinner = ({ className = "h-5 w-5 text-white" }) => (
  <svg className={`animate-spin ${className}`} viewBox="0 0 24 24">
    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
  </svg>
);

const VOICES: { name: VoiceName; desc: string }[] = [
  { name: 'Kore', desc: 'Sérieux & Professionnel' },
  { name: 'Puck', desc: 'Enjoué & Dynamique' },
  { name: 'Charon', desc: 'Profond & Calme' },
  { name: 'Fenrir', desc: 'Chaleureux & Accueillant' },
  { name: 'Zephyr', desc: 'Clair & Doux' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDetecting, setIsDetecting] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Drive API State
  const [tokenResponse, setTokenResponse] = useState<any>(null);

  useEffect(() => {
    // Load GAPI and GIS
    const initGapi = () => {
      (window as any).gapi.load('client:picker', () => {
        (window as any).gapi.client.load('drive', 'v3');
      });
    };
    if ((window as any).gapi) initGapi();
  }, []);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined;
    if ('target' in e) {
      file = e.target.files?.[0];
    } else {
      file = e.file;
    }

    if (!file) return;

    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        const content = await file.text();
        setText(content);
      } else if (fileName.endsWith(".docx") || file.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document") {
        const arrayBuffer = await file.arrayBuffer();
        const result = await mammoth.extractRawText({ arrayBuffer });
        setText(result.value);
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      } else {
        setError("Format non supporté. Utilisez .txt, .docx ou .pdf");
      }
    } catch (err) {
      console.error("File read error:", err);
      setError("Erreur lors de la lecture du fichier.");
    }
  };

  const handleDriveImport = () => {
    const clientID = 'YOUR_CLIENT_ID_IF_AVAILABLE'; // Placeholder if needed, but we'll try to trigger the flow

    const tokenClient = (window as any).google.accounts.oauth2.initTokenClient({
      client_id: '', // Injected if needed, else we rely on environment setup
      scope: 'https://www.googleapis.com/auth/drive.readonly',
      callback: (response: any) => {
        if (response.error !== undefined) {
          setError("Erreur d'authentification Google Drive.");
          return;
        }
        setTokenResponse(response);
        createPicker(response.access_token);
      },
    });

    if (tokenResponse === null) {
      tokenClient.requestAccessToken({ prompt: 'consent' });
    } else {
      tokenClient.requestAccessToken({ prompt: '' });
    }
  };

  const createPicker = (accessToken: string) => {
    const view = new (window as any).google.picker.DocsView((window as any).google.picker.ViewId.DOCS)
      .setMimeTypes('text/plain,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document');

    const picker = new (window as any).google.picker.PickerBuilder()
      .enableFeature((window as any).google.picker.Feature.NAV_HIDDEN)
      .enableFeature((window as any).google.picker.Feature.MULTISELECT_ENABLED)
      .setAppId('VoxGenAI')
      .setOAuthToken(accessToken)
      .addView(view)
      .setCallback(async (data: any) => {
        if (data.action === (window as any).google.picker.Action.PICKED) {
          const file = data.docs[0];
          const fileId = file.id;
          const fileName = file.name;

          setIsDriveLoading(true);
          try {
            const response = await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?alt=media`, {
              headers: { Authorization: `Bearer ${accessToken}` }
            });
            const blob = await response.blob();
            const virtualFile = new File([blob], fileName, { type: blob.type });
            await handleFileUpload({ file: virtualFile });
          } catch (err) {
            setError("Impossible de récupérer le fichier depuis Drive.");
          } finally {
            setIsDriveLoading(false);
          }
        }
      })
      .build();
    picker.setVisible(true);
  };

  const handleDetectLanguage = async () => {
    if (!text.trim()) return;
    setIsDetecting(true);
    try {
      const detected = await detectLanguage(text);
      setLanguage(detected);
    } catch (err) {
      console.error(err);
    } finally {
      setIsDetecting(false);
    }
  };

  const handleGenerate = async () => {
    if (!text.trim()) {
      setError("Veuillez saisir du texte avant de continuer.");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setAudioResult(null);

    try {
      const result = await generateSpeech({ text, language, voice });
      setAudioResult(result);
    } catch (err: any) {
      setError("Une erreur est survenue lors de la génération. Réessayez plus tard.");
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, voiceToPreview: VoiceName) => {
    e.stopPropagation();
    if (previewingVoice) return;

    setPreviewingVoice(voiceToPreview);
    const previews: Record<Language, string> = {
      [Language.FRENCH]: `Ceci est un aperçu de la voix ${voiceToPreview}.`,
      [Language.ENGLISH]: `This is a preview of the ${voiceToPreview} voice.`,
      [Language.SPANISH]: `Esta es una vista previa de la voz ${voiceToPreview}.`,
      [Language.GERMAN]: `Dies ist eine Vorschau der Stimme ${voiceToPreview}.`,
      [Language.ITALIAN]: `Questa è un'anteprima della voce ${voiceToPreview}.`,
    };

    try {
      const result = await generateSpeech({ text: previews[language], language, voice: voiceToPreview });
      const audio = new Audio(result.url);
      audio.onended = () => setPreviewingVoice(null);
      await audio.play();
    } catch (err) {
      console.error(err);
      setPreviewingVoice(null);
    }
  };

  const downloadAudio = async () => {
    if (!audioResult) return;
    setIsDownloading(true);
    await new Promise(r => setTimeout(r, 50));

    try {
      const mp3Blob = convertPcmToMp3(audioResult.pcmData, 24000);
      const mp3Url = URL.createObjectURL(mp3Blob);
      const link = document.createElement('a');
      link.href = mp3Url;
      link.download = `voxgen-${Date.now()}.mp3`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      setTimeout(() => URL.revokeObjectURL(mp3Url), 100);
    } catch (err) {
      setError("Échec de l'encodage MP3.");
    } finally {
      setIsDownloading(false);
    }
  };

  const clearAudioResult = () => {
    setAudioResult(null);
    setError(null);
  };

  const wordCount = text.trim().split(/\s+/).filter(Boolean).length;

  return (
    <div className="min-h-screen bg-[#FDFDFF] py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="text-center mb-12 animate-fadeInDown">
          <div className="inline-flex items-center justify-center p-4 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-100 mb-6 text-white transform hover:rotate-3 transition-transform">
            <AudioIcon />
          </div>
          <h1 className="text-5xl font-black text-slate-900 tracking-tight mb-3">VoxGen <span className="text-indigo-600 underline decoration-indigo-200">AI</span></h1>
          <p className="text-xl text-slate-500 font-medium">L'outil de synthèse vocale ultime pour professionnels.</p>
        </div>

        {/* Main Interface */}
        <div className="bg-white rounded-[2rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.08)] border border-slate-100 overflow-hidden">
          <div className="p-8 md:p-12">
            {/* Input Toolbar */}
            <div className="flex flex-wrap items-center justify-between gap-4 mb-4">
              <label className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em]">Éditeur de texte</label>
              <div className="flex items-center gap-2">
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".txt,.docx,.pdf" className="hidden" />
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100 transition-colors"
                >
                  <UploadIcon /> Importer (Fichier)
                </button>
                <button 
                  onClick={handleDriveImport}
                  disabled={isDriveLoading}
                  className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold text-slate-700 bg-slate-50 border border-slate-100 rounded-lg hover:bg-slate-100 transition-colors"
                >
                  {isDriveLoading ? <LoadingSpinner className="h-4 w-4 text-indigo-600" /> : <DriveIcon />} Google Drive
                </button>
                <button 
                  onClick={() => setText('')}
                  className="p-1.5 text-slate-400 hover:text-red-500 transition-colors"
                  title="Effacer tout"
                >
                  <TrashIcon />
                </button>
              </div>
            </div>

            {/* Main Textarea */}
            <div className="relative mb-8">
              {isDriveLoading && (
                <div className="absolute inset-0 z-10 bg-white/60 backdrop-blur-sm rounded-2xl flex flex-col items-center justify-center animate-pulse">
                  <LoadingSpinner className="h-10 w-10 text-indigo-600 mb-2" />
                  <span className="text-sm font-bold text-slate-600">Synchronisation Drive...</span>
                </div>
              )}
              <textarea
                rows={8}
                className="block w-full rounded-2xl border-slate-100 shadow-sm focus:border-indigo-500 focus:ring-[6px] focus:ring-indigo-100 text-lg p-8 bg-slate-50/50 resize-none transition-all outline-none border font-medium text-slate-800 placeholder:text-slate-300"
                placeholder="Écrivez ou collez votre texte ici pour lui donner vie..."
                value={text}
                onChange={(e) => setText(e.target.value)}
              />
              <div className="absolute bottom-4 right-6 text-xs font-bold text-slate-400 bg-white/80 px-2 py-1 rounded-md backdrop-blur-sm">
                {wordCount} MOTS &bull; {text.length} CARACTÈRES
              </div>
            </div>

            {/* Settings Sections */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 mb-10">
              {/* Language Section */}
              <div>
                <div className="flex items-center justify-between mb-4">
                  <label className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em]">Langue</label>
                  <button 
                    onClick={handleDetectLanguage}
                    disabled={isDetecting || !text.trim()}
                    className={`flex items-center gap-1.5 text-xs font-bold px-2 py-1 rounded-md transition-all ${
                      isDetecting ? 'text-indigo-400' : 'text-indigo-600 hover:bg-indigo-50'
                    }`}
                  >
                    {isDetecting ? <LoadingSpinner className="h-3 w-3 text-indigo-500" /> : <MagicIcon />}
                    Auto-détection
                  </button>
                </div>
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                  {LANGS.map((lang) => (
                    <button
                      key={lang.id}
                      onClick={() => setLanguage(lang.id)}
                      className={`py-3 px-3 rounded-xl text-sm font-bold transition-all border-2 flex items-center justify-center gap-2 ${
                        language === lang.id
                          ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100'
                          : 'bg-white border-slate-100 text-slate-600 hover:border-slate-300'
                      }`}
                    >
                      <span>{lang.flag}</span> {lang.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Voice Section */}
              <div>
                <label className="block text-sm font-bold text-slate-400 uppercase tracking-[0.2em] mb-4">Voix & Ton</label>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {VOICES.map((v) => (
                    <div
                      key={v.name}
                      onClick={() => setVoice(v.name)}
                      className={`relative p-3 rounded-xl border-2 cursor-pointer transition-all group ${
                        voice === v.name
                          ? 'bg-indigo-50 border-indigo-600'
                          : 'bg-white border-slate-100 hover:border-slate-200'
                      }`}
                    >
                      <div className="flex justify-between items-center mb-0.5">
                        <span className={`font-bold text-sm ${voice === v.name ? 'text-indigo-700' : 'text-slate-800'}`}>{v.name}</span>
                        <button
                          onClick={(e) => handlePreview(e, v.name)}
                          disabled={previewingVoice !== null}
                          className={`p-1 rounded-full transition-all ${
                            previewingVoice === v.name ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'
                          }`}
                        >
                          {previewingVoice === v.name ? <LoadingSpinner className="h-3.5 w-3.5 text-white" /> : <PlayIcon className="w-3.5 h-3.5" />}
                        </button>
                      </div>
                      <p className="text-[10px] text-slate-500 leading-none">{v.desc}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Error Message */}
            {error && (
              <div className="mb-8 p-5 bg-red-50 border-l-4 border-red-500 text-red-700 text-sm rounded-r-2xl animate-shake">
                <span className="font-bold">Attention :</span> {error}
              </div>
            )}

            {/* Action Area */}
            <div className="space-y-8">
              <button
                onClick={handleGenerate}
                disabled={isGenerating || !text.trim()}
                className={`w-full flex items-center justify-center px-6 py-6 border border-transparent text-xl font-black rounded-3xl shadow-[0_20px_40px_-10px_rgba(79,70,229,0.3)] transition-all ${
                  isGenerating || !text.trim()
                  ? 'bg-slate-200 cursor-not-allowed text-slate-400' 
                  : 'bg-indigo-600 hover:bg-indigo-700 text-white transform hover:-translate-y-1.5'
                }`}
              >
                {isGenerating ? (
                  <>
                    <LoadingSpinner className="mr-4 h-7 w-7 text-white" />
                    Synthèse vocale en cours...
                  </>
                ) : (
                  'Générer la voix'
                )}
              </button>

              {/* Audio Result Card */}
              {audioResult && (
                <div className="p-10 bg-gradient-to-br from-indigo-50 to-white rounded-[2.5rem] border-2 border-indigo-100 animate-fadeInUp shadow-xl relative">
                  <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                      <div className="p-3 bg-indigo-600 rounded-2xl text-white shadow-lg">
                        <AudioIcon />
                      </div>
                      <div>
                        <h3 className="text-xl font-black text-slate-900">Audio Prêt</h3>
                        <p className="text-sm text-slate-500 font-medium">Format haute-définition stéréo</p>
                      </div>
                    </div>
                    <button 
                      onClick={clearAudioResult}
                      className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-400 hover:text-red-500 bg-white border border-slate-100 rounded-xl transition-all hover:border-red-100 shadow-sm"
                    >
                      <TrashIcon size={14} /> Effacer le résultat
                    </button>
                  </div>
                  <div className="flex flex-col md:flex-row items-center gap-6">
                    <audio controls src={audioResult.url} className="w-full h-16 rounded-xl" />
                    <button
                      onClick={downloadAudio}
                      disabled={isDownloading}
                      className={`flex items-center justify-center gap-3 px-8 py-5 rounded-2xl font-black text-sm uppercase tracking-wider transition-all shadow-md min-w-[240px] border-2 ${
                        isDownloading
                        ? 'bg-slate-100 border-slate-200 text-slate-400'
                        : 'bg-white border-slate-100 text-slate-900 hover:border-indigo-600 hover:text-indigo-600'
                      }`}
                    >
                      {isDownloading ? (
                        <>
                          <LoadingSpinner className="h-5 w-5 text-indigo-600" />
                          Conversion MP3...
                        </>
                      ) : (
                        <>
                          <DownloadIcon /> Télécharger MP3
                        </>
                      )}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Brand Footer */}
        <div className="mt-16 text-center space-y-4">
          <p className="text-slate-400 text-sm font-bold uppercase tracking-[0.3em]">
            VoxGen Enterprise &bull; Technologie Gemini 2.5
          </p>
          <div className="flex justify-center gap-8 opacity-30 grayscale hover:grayscale-0 transition-all duration-500">
            <span className="font-black text-slate-900">STUDIO QUALITY</span>
            <span className="font-black text-slate-900">AI POWERED</span>
            <span className="font-black text-slate-900">NO LIMITS</span>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes fadeInDown {
          from { opacity: 0; transform: translateY(-20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        .animate-fadeInUp { animation: fadeInUp 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
        .animate-fadeInDown { animation: fadeInDown 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
        .animate-shake { animation: shake 0.3s ease-in-out; }

        audio::-webkit-media-controls-panel {
          background-color: transparent;
        }
      `}</style>
    </div>
  );
};

export default App;

