export enum Language {
  FRENCH = 'French',
  ENGLISH = 'English',
  SPANISH = 'Spanish',
  GERMAN = 'German',
  ITALIAN = 'Italian'
}

export type VoiceName = 'Kore' | 'Puck' | 'Charon' | 'Fenrir' | 'Zephyr';

export interface TTSConfig {
  text: string;
  language: Language;
  voice: VoiceName;
  speed: number;
  pitch: number;
}

export interface AudioResult {
  blob: Blob;
  url: string;
  pcmData: Uint8Array;
}

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { TTSConfig, AudioResult, Language } from "../types";
import { decodeBase64, createWavBlob } from "../utils/audioConverter";

export async function detectLanguage(text: string): Promise<Language> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Identify the language of the following text and return ONLY one of these values: French, English, Spanish, German, Italian. If unsure, default to English. Text: "${text.substring(0, 500)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { 
              type: Type.STRING,
              description: "The detected language name."
            }
          },
          required: ["language"]
        }
      }
    });

    const json = JSON.parse(response.text);
    const detected = json.language as Language;

    if (Object.values(Language).includes(detected)) {
      return detected;
    }
    return Language.ENGLISH;
  } catch (error) {
    console.error("Language detection error:", error);
    return Language.ENGLISH;
  }
}

export async function generateSpeech(config: TTSConfig): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Mapping speed to descriptive terms
  let speedDesc = "à une vitesse normale";
  if (config.speed < 0.8) speedDesc = "très lentement";
  else if (config.speed < 1.0) speedDesc = "lentement";
  else if (config.speed > 1.5) speedDesc = "très rapidement";
  else if (config.speed > 1.0) speedDesc = "rapidement";

  // Mapping pitch to descriptive terms
  let pitchDesc = "avec une tonalité naturelle";
  if (config.pitch < 0.8) pitchDesc = "avec une voix très grave et profonde";
  else if (config.pitch < 1.0) pitchDesc = "avec une voix légèrement plus grave";
  else if (config.pitch > 1.5) pitchDesc = "avec une voix très aiguë et enfantine";
  else if (config.pitch > 1.0) pitchDesc = "avec une voix légèrement plus aiguë";

  const languageInstructions: Record<Language, string> = {
    [Language.FRENCH]: `Dis ceci de manière naturelle, ${speedDesc} et ${pitchDesc}. Respecte les pauses indiquées par des points de suspension ou la ponctuation :`,
    [Language.ENGLISH]: `Speak naturally, ${speedDesc.replace('lentement', 'slowly').replace('rapidement', 'fast')} and ${pitchDesc.replace('grave', 'deep').replace('aiguë', 'high-pitched')}. Respect pauses marked by ellipses or punctuation:`,
    [Language.SPANISH]: `Habla de forma natural, ${speedDesc} y ${pitchDesc}:`,
    [Language.GERMAN]: `Sprich natürlich, ${speedDesc} und ${pitchDesc}:`,
    [Language.ITALIAN]: `Parla in modo naturale, ${speedDesc} e ${pitchDesc}:`
  };

  const prompt = `${languageInstructions[config.language]} ${config.text}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: config.voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data received from Gemini API.");
    }

    const pcmBytes = decodeBase64(base64Audio);
    const wavBlob = createWavBlob(pcmBytes, 24000);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      blob: wavBlob,
      url: audioUrl,
      pcmData: pcmBytes
    };
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    throw error;
  }
}

