const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [speed, setSpeed] = useState<number>(1.0);
  const [pitch, setPitch] = useState<number>(1.0);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDetecting, setIsDetecting] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showDriveConfig, setShowDriveConfig] = useState<boolean>(false);
  const [googleClientId, setGoogleClientId] = useState<string>(localStorage.getItem('voxgen_google_client_id') || '');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [tokenResponse, setTokenResponse] = useState<any>(null);

  useEffect(() => {
    const gapi = (window as any).gapi;
    if (gapi) {
      gapi.load('client:picker', () => {
        gapi.client.load('drive', 'v3');
      });
    }
  }, []);

  const saveClientId = (id: string) => {
    setGoogleClientId(id);
    localStorage.setItem('voxgen_google_client_id', id);
    setShowDriveConfig(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined = ('target' in e) ? e.target.files?.[0] : (e as any).file;
    if (!file) return;

    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        setText(await file.text());
      } else if (fileName.endsWith(".docx") || file.type.includes("word")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      } else {
        setError("Format non supporté.");
      }
    } catch (err) {
      setError("Erreur de lecture.");
    }
  };

  const handleDriveImport = () => {
    if (!googleClientId) {
      setError("Configurez votre Client ID (icône ⚙️).");
      setShowDriveConfig(true);
      return;
    }
    const google = (window as any).google;
    const tokenClient = google.accounts.oauth2.initTokenClient({
      client_id: googleClientId,
      scope: 'https://www.googleapis.com/auth/drive.readonly',
      callback: (response: any) => {
        if (response.error) { setError(`Erreur: ${response.error}`); return; }
        setTokenResponse(response);
        createPicker(response.access_token);
      },
    });
    tokenClient.requestAccessToken({ prompt: tokenResponse ? '' : 'consent' });
  };

  const createPicker = (accessToken: string) => {
    const google = (window as any).google;
    const view = new google.picker.DocsView(google.picker.ViewId.DOCS)
      .setMimeTypes('text/plain,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document');
    new google.picker.PickerBuilder()
      .setAppId('VoxGenAI').setOAuthToken(accessToken).addView(view)
      .setCallback(async (data: any) => {
        if (data.action === google.picker.Action.PICKED) {
          const file = data.docs[0];
          setIsDriveLoading(true);
          try {
            const resp = await fetch(`https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`, {
              headers: { Authorization: `Bearer ${accessToken}` }
            });
            handleFileUpload({ file: new File([await resp.blob()], file.name, { type: file.mimeType }) });
          } catch { setError("Erreur Drive."); } finally { setIsDriveLoading(false); }
        }
      }).build().setVisible(true);
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      setAudioResult(await generateSpeech({ text, language, voice, speed, pitch }));
    } catch (err) {
      setError("Erreur de génération.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, vName: VoiceName) => {
    e.stopPropagation();
    if (previewingVoice) return;
    setPreviewingVoice(vName);
    try {
      const res = await generateSpeech({ text: "Aperçu VoxGen AI", language, voice: vName, speed: 1, pitch: 1 });
      const audio = new Audio(res.url);
      audio.onended = () => setPreviewingVoice(null);
      await audio.play();
    } catch { setPreviewingVoice(null); }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-12 animate-fadeInDown">
          <div className="inline-flex items-center justify-center p-4 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-100 mb-6 text-white transform hover:rotate-3 transition-transform">
            <AudioIcon />
          </div>
          <h1 className="text-5xl font-black text-slate-900 tracking-tight mb-3">VoxGen <span className="text-indigo-600 underline decoration-indigo-200">AI</span></h1>
          <p className="text-xl text-slate-500 font-medium">Studio de synthèse vocale professionnel.</p>
        </div>

        <div className="bg-white rounded-[2rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.08)] border border-slate-100 overflow-hidden">
          <div className="p-8 md:p-12">
            <div className="flex flex-wrap items-center justify-between gap-4 mb-4">
              <label className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em]">Éditeur</label>
              <div className="flex items-center gap-2">
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".txt,.docx,.pdf" className="hidden" />
                <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100 transition-colors">
                  <UploadIcon /> Importer
                </button>
                <div className="flex items-center bg-slate-50 border border-slate-100 rounded-lg overflow-hidden">
                  <button onClick={handleDriveImport} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold text-slate-700 hover:bg-slate-100 transition-colors">
                    <DriveIcon /> Drive
                  </button>
                  <button onClick={() => setShowDriveConfig(!showDriveConfig)} className={`p-1.5 text-slate-400 hover:text-indigo-600 border-l border-slate-100 ${showDriveConfig ? 'bg-indigo-50 text-indigo-600' : ''}`}><SettingsIcon /></button>
                </div>
                <button onClick={() => setText('')} className="p-1.5 text-slate-400 hover:text-red-500"><TrashIcon /></button>
              </div>
            </div>

            {showDriveConfig && (
              <div className="mb-6 p-6 bg-slate-50 rounded-2xl border border-slate-100 animate-fadeInDown">
                <h4 className="text-sm font-black text-slate-700 mb-3 uppercase">Config Google Drive</h4>
                <div className="flex gap-2">
                  <input type="text" placeholder="Client ID..." value={googleClientId} onChange={(e) => setGoogleClientId(e.target.value)} className="flex-1 px-4 py-2 text-sm rounded-xl border outline-none" />
                  <button onClick={() => saveClientId(googleClientId)} className="px-6 py-2 bg-indigo-600 text-white text-sm font-bold rounded-xl">Sauver</button>
                </div>
              </div>
            )}

            <div className="relative mb-8">
              {isDriveLoading && <div className="absolute inset-0 z-10 bg-white/60 backdrop-blur-sm rounded-2xl flex flex-col items-center justify-center"><LoadingSpinner className="h-10 w-10 text-indigo-600 mb-2" /></div>}
              <textarea rows={6} className="block w-full rounded-2xl border-slate-100 shadow-sm focus:border-indigo-500 focus:ring-[6px] focus:ring-indigo-100 text-lg p-8 bg-slate-50/50 resize-none transition-all outline-none border font-medium text-slate-800" placeholder="Insérez votre texte... Astuce: Utilisez '...' pour une courte pause." value={text} onChange={(e) => setText(e.target.value)} />
