            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 mb-10">
              {/* Voices & Langs */}
              <div className="space-y-6">
                <div>
                  <label className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em] mb-4 block">Langue</label>
                  <div className="grid grid-cols-3 gap-2">
                    {LANGS.map((lang) => (
                      <button key={lang.id} onClick={() => setLanguage(lang.id)} className={`py-2 px-2 rounded-xl text-xs font-bold border-2 flex items-center justify-center gap-1.5 ${language === lang.id ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-600'}`}>{lang.flag} {lang.label}</button>
                    ))}
