                        <div className="flex justify-between items-center mb-1">
                          <span className={`font-bold text-xs ${voice === v.name ? 'text-indigo-700' : 'text-slate-800'}`}>{v.name}</span>
                          <button onClick={(e) => handlePreview(e, v.name)} disabled={previewingVoice !== null} className={`p-1 rounded-full ${previewingVoice === v.name ? 'bg-indigo-600' : 'bg-slate-100'}`}>
                            {previewingVoice === v.name ? <LoadingSpinner className="h-3 w-3" /> : <PlayIcon className="w-3 h-3" />}
                          </button>
                        </div>
                        <p className="text-[10px] text-slate-500 leading-none">{v.desc}</p>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Advanced Customization */}
              <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 space-y-8">
                <label className="text-sm font-bold text-slate-700 uppercase tracking-[0.2em] block">Personnalisation</label>

                <div className="space-y-4">
                  <div className="flex justify-between items-center text-xs font-bold text-slate-500">
                    <span>VITESSE</span>
                    <span className="text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full">{speed.toFixed(1)}x</span>
                  </div>
                  <input type="range" min="0.5" max="2.0" step="0.1" value={speed} onChange={(e) => setSpeed(parseFloat(e.target.value))} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                  <div className="flex justify-between text-[10px] text-slate-400 font-bold uppercase"><span>Lent</span><span>Rapide</span></div>
                </div>

                <div className="space-y-4">
                  <div className="flex justify-between items-center text-xs font-bold text-slate-500">
                    <span>TONALITÉ</span>
                    <span className="text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full">{pitch < 1.0 ? 'Grave' : pitch > 1.0 ? 'Aiguë' : 'Normale'}</span>
                  </div>
                  <input type="range" min="0.5" max="2.0" step="0.1" value={pitch} onChange={(e) => setPitch(parseFloat(e.target.value))} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                  <div className="flex justify-between text-[10px] text-slate-400 font-bold uppercase"><span>Grave</span><span>Aiguë</span></div>
                </div>

                <div className="p-4 bg-white rounded-2xl border border-slate-100 shadow-sm">
                  <div className="flex gap-2 items-start">
                    <div className="p-1.5 bg-yellow-100 text-yellow-600 rounded-lg mt-0.5"><MagicIcon /></div>
                    <p className="text-[10px] text-slate-500 font-medium leading-relaxed">
                      <strong>Astuce Pro :</strong> Utilisez des signes de ponctuation ou des points de suspension (...) pour créer des silences naturels dans votre texte.
                    </p>
                  </div>
                </div>
              </div>
            </div>

            {error && <div className="mb-8 p-4 bg-red-50 border-l-4 border-red-500 text-red-700 text-sm font-medium rounded-r-xl">{error}</div>}

            <div className="space-y-8">
              <button onClick={handleGenerate} disabled={isGenerating || !text.trim()} className={`w-full flex items-center justify-center px-6 py-5 text-lg font-black rounded-3xl transition-all ${isGenerating || !text.trim() ? 'bg-slate-200 text-slate-400' : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-xl hover:-translate-y-1'}`}>
                {isGenerating ? <><LoadingSpinner className="mr-3 h-6 w-6" /> Synthèse...</> : 'Générer l\'audio'}
              </button>

              {audioResult && (
                <div className="p-8 bg-gradient-to-br from-indigo-50 to-white rounded-[2rem] border-2 border-indigo-100 animate-fadeInUp">
                  <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-indigo-600 rounded-xl text-white"><AudioIcon /></div>
                      <h3 className="font-black text-slate-900">Audio Généré</h3>
                    </div>
                    <button onClick={() => setAudioResult(null)} className="text-slate-400 hover:text-red-500 transition-colors"><TrashIcon size={20} /></button>
                  </div>
                  <div className="flex flex-col md:flex-row items-center gap-4">
                    <audio controls src={audioResult.url} className="w-full h-12" />
                    <button onClick={async () => {
                      setIsDownloading(true);
                      try {
                        const blob = convertPcmToMp3(audioResult.pcmData, 24000);
                        const a = document.createElement('a');
                        a.href = URL.createObjectURL(blob);
                        a.download = `voxgen-${Date.now()}.mp3`;
                        a.click();
                      } finally { setIsDownloading(false); }
                    }} disabled={isDownloading} className="flex items-center justify-center gap-2 px-6 py-3 bg-white border border-slate-200 rounded-xl font-bold text-sm hover:border-indigo-600 transition-all min-w-[180px]">
                      {isDownloading ? <LoadingSpinner className="h-4 w-4 text-indigo-600" /> : <><DownloadIcon /> MP3</>}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeInDown { from { opacity: 0; transform: translateY(-20px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fadeInUp { animation: fadeInUp 0.4s ease-out forwards; }
        .animate-fadeInDown { animation: fadeInDown 0.4s ease-out forwards; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { generateSpeech } from './services/geminiService';
import { Language, VoiceName, AudioResult } from './types';
import { convertPcmToMp3 } from './utils/mp3Converter';
import mammoth from 'mammoth';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js Worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.0.379/build/pdf.worker.mjs`;

