const VOICES: { name: VoiceName; desc: string; type: 'M' | 'F' }[] = [
  { name: 'Kore', desc: 'Sérieux & Corporatif', type: 'M' },
  { name: 'Puck', desc: 'Énergique & Jeune', type: 'F' },
  { name: 'Charon', desc: 'Profond & Calme', type: 'M' },
  { name: 'Fenrir', desc: 'Avenant & Rassurant', type: 'M' },
  { name: 'Zephyr', desc: 'Limpide & Doux', type: 'F' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [speed, setSpeed] = useState<number>(1.0);
  const [pitch, setPitch] = useState<number>(1.0);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showUrlInput, setShowUrlInput] = useState<boolean>(false);
  const [remoteUrl, setRemoteUrl] = useState<string>('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined = ('target' in e) ? e.target.files?.[0] : (e as any).file;
    if (!file) return;

    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        setText(await file.text());
      } else if (fileName.endsWith(".docx") || file.type.includes("word")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      } else {
        setError("Format non supporté.");
      }
    } catch (err) {
      setError("Erreur de lecture du document.");
    }
  };

  const handleDriveUrlImport = async () => {
    if (!remoteUrl.trim()) return;

    setIsDriveLoading(true);
    setError(null);

    try {
      // Regex pour extraire l'ID du fichier depuis l'URL Drive
      const docIdMatch = remoteUrl.match(/\/document\/d\/([a-zA-Z0-9-_]+)/);
      const fileIdMatch = remoteUrl.match(/id=([a-zA-Z0-9-_]+)/) || remoteUrl.match(/\/file\/d\/([a-zA-Z0-9-_]+)/);

      const fileId = docIdMatch ? docIdMatch[1] : (fileIdMatch ? fileIdMatch[1] : null);

      if (!fileId) {
        throw new Error("L'URL ne semble pas être un lien Google Drive valide.");
      }

      // Pour les Google Docs, on demande un export TXT
      // Pour les autres fichiers (PDF/DOCX), on tente un téléchargement direct
      const exportUrl = docIdMatch 
        ? `https://docs.google.com/document/d/${fileId}/export?format=txt`
        : `https://drive.google.com/uc?export=download&id=${fileId}`;

      // Utilisation d'un proxy CORS public pour éviter les erreurs de sécurité navigateur
      const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(exportUrl)}`;

      const response = await fetch(proxyUrl);
      if (!response.ok) throw new Error("Impossible d'accéder au document. Vérifiez qu'il est partagé avec 'Tous les utilisateurs disposant du lien'.");

      if (docIdMatch) {
        const content = await response.text();
        setText(content);
        setShowUrlInput(false);
      } else {
        // Pour les fichiers binaires (PDF/DOCX)
        const blob = await response.blob();
        const fileName = "drive_import_" + Date.now();
        const virtualFile = new File([blob], fileName, { type: blob.type });
        await handleFileUpload({ file: virtualFile });
        setShowUrlInput(false);
      }
    } catch (err: any) {
      setError(err.message || "Erreur lors de l'importation Drive.");
    } finally {
      setIsDriveLoading(false);
    }
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      setAudioResult(await generateSpeech({ text, language, voice, speed, pitch }));
    } catch (err) {
      setError("Erreur de génération audio.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, vName: VoiceName) => {
    e.stopPropagation();
    if (previewingVoice) return;
    setPreviewingVoice(vName);
    try {
      const res = await generateSpeech({ text: "Test de voix VoxGen", language, voice: vName, speed: 1, pitch: 1 });
      const audio = new Audio(res.url);
      audio.onended = () => setPreviewingVoice(null);
      await audio.play();
    } catch { setPreviewingVoice(null); }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-12 animate-fadeInDown">
          <div className="inline-flex items-center justify-center p-4 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-100 mb-6 text-white transform hover:rotate-3 transition-transform">
            <AudioIcon />
          </div>
          <h1 className="text-5xl font-black text-slate-900 tracking-tight mb-3">VoxGen <span className="text-indigo-600 underline decoration-indigo-200">AI</span></h1>
          <p className="text-xl text-slate-500 font-medium">L'IA qui transforme vos écrits en narration d'exception.</p>
        </div>

        <div className="bg-white rounded-[2rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.08)] border border-slate-100 overflow-hidden">
          <div className="p-8 md:p-12">
            <div className="flex flex-wrap items-center justify-between gap-4 mb-4">
              <label className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em]">Éditeur de contenu</label>
              <div className="flex items-center gap-2">
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".txt,.docx,.pdf" className="hidden" />
                <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100 transition-colors">
                  <UploadIcon /> Importer
                </button>
                <button 
                  onClick={() => setShowUrlInput(!showUrlInput)} 
                  className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold border rounded-lg transition-all ${showUrlInput ? 'bg-indigo-600 border-indigo-600 text-white' : 'text-slate-700 bg-slate-50 border-slate-100 hover:bg-slate-100'}`}
                >
                  <DriveIcon /> Lien Drive
                </button>
                <button onClick={() => setText('')} className="p-1.5 text-slate-400 hover:text-red-500 transition-colors"><TrashIcon /></button>
              </div>
            </div>

            {/* Champ d'URL Magique */}
            {showUrlInput && (
              <div className="mb-6 p-6 bg-indigo-50/50 rounded-2xl border border-indigo-100 animate-fadeInDown">
                <h4 className="text-sm font-black text-indigo-900 mb-2 uppercase tracking-wider flex items-center gap-2">
                  <MagicIcon /> Importer via URL Google Drive
                </h4>
                <p className="text-[11px] text-indigo-600 mb-4 font-medium">Assurez-vous que le document est partagé en mode "Tous les utilisateurs disposant du lien".</p>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    placeholder="Collez l'URL du document ici..." 
                    value={remoteUrl} 
                    onChange={(e) => setRemoteUrl(e.target.value)} 
                    className="flex-1 px-4 py-3 text-sm rounded-xl border-2 border-white focus:border-indigo-400 outline-none shadow-sm" 
                  />
                  <button 
                    onClick={handleDriveUrlImport} 
                    disabled={isDriveLoading || !remoteUrl.trim()}
                    className="px-6 py-2 bg-indigo-600 text-white text-sm font-bold rounded-xl hover:bg-indigo-700 transition-all shadow-md disabled:bg-slate-300 flex items-center gap-2"
                  >
                    {isDriveLoading ? <LoadingSpinner className="h-4 w-4" /> : 'Analyser'}
                  </button>
                </div>
              </div>
            )}

            <div className="relative mb-8">
              {isDriveLoading && <div className="absolute inset-0 z-10 bg-white/60 backdrop-blur-sm rounded-2xl flex flex-col items-center justify-center"><LoadingSpinner className="h-10 w-10 text-indigo-600 mb-2" /><span className="text-xs font-bold text-indigo-600">Extraction en cours...</span></div>}
              <textarea rows={6} className="block w-full rounded-2xl border-slate-100 shadow-sm focus:border-indigo-500 focus:ring-[6px] focus:ring-indigo-100 text-lg p-8 bg-slate-50/50 resize-none transition-all outline-none border font-medium text-slate-800" placeholder="Tapez votre texte ou collez un lien Drive ci-dessus..." value={text} onChange={(e) => setText(e.target.value)} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 mb-10">
              <div className="space-y-6">
                <div>
                  <label className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em] mb-4 block">Langue</label>
                  <div className="grid grid-cols-3 gap-2">
                    {LANGS.map((lang) => (
                      <button key={lang.id} onClick={() => setLanguage(lang.id)} className={`py-2 px-2 rounded-xl text-xs font-bold border-2 flex items-center justify-center gap-1.5 transition-all ${language === lang.id ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-600'}`}>{lang.flag} {lang.label}</button>
                    ))}
                  </div>
                </div>
                <div>
                  <label className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em] mb-4 block">Profil Vocal</label>
                  <div className="grid grid-cols-2 gap-2">
                    {VOICES.map((v) => (
                      <div key={v.name} onClick={() => setVoice(v.name)} className={`p-3 rounded-xl border-2 cursor-pointer transition-all ${voice === v.name ? 'bg-indigo-50 border-indigo-600' : 'bg-white border-slate-100'}`}>
                        <div className="flex justify-between items-center mb-1">
                          <span className={`font-bold text-xs ${voice === v.name ? 'text-indigo-700' : 'text-slate-800'}`}>{v.name}</span>
                          <button onClick={(e) => handlePreview(e, v.name)} disabled={previewingVoice !== null} className={`p-1 rounded-full transition-all ${previewingVoice === v.name ? 'bg-indigo-600' : 'bg-slate-100'}`}>
                            {previewingVoice === v.name ? <LoadingSpinner className="h-3 w-3" /> : <PlayIcon className="w-3 h-3" />}
                          </button>
                        </div>
                        <p className="text-[10px] text-slate-500 leading-none">{v.desc}</p>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 space-y-8">
                <label className="text-sm font-bold text-slate-700 uppercase tracking-[0.2em] block">Diction & Ton</label>

                <div className="space-y-4">
                  <div className="flex justify-between items-center text-xs font-bold text-slate-500">
                    <span>VITESSE DE LECTURE</span>
                    <span className="text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full">{speed.toFixed(1)}x</span>
                  </div>
                  <input type="range" min="0.5" max="2.0" step="0.1" value={speed} onChange={(e) => setSpeed(parseFloat(e.target.value))} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                </div>

                <div className="space-y-4">
                  <div className="flex justify-between items-center text-xs font-bold text-slate-500">
                    <span>TONALITÉ (PITCH)</span>
                    <span className="text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full">{pitch < 1.0 ? 'Grave' : pitch > 1.0 ? 'Aiguë' : 'Médium'}</span>
                  </div>
                  <input type="range" min="0.5" max="2.0" step="0.1" value={pitch} onChange={(e) => setPitch(parseFloat(e.target.value))} className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                </div>

                <div className="p-4 bg-white/80 rounded-2xl border border-slate-100 flex gap-3 items-center">
                   <div className="text-yellow-500"><MagicIcon /></div>
                   <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Pause naturelle : Utilisez '...' ou [pause]</p>
                </div>
              </div>
            </div>

            {error && <div className="mb-8 p-4 bg-red-50 border-l-4 border-red-500 text-red-700 text-sm font-bold rounded-r-xl animate-shake">{error}</div>}

            <div className="space-y-8">
              <button onClick={handleGenerate} disabled={isGenerating || !text.trim()} className={`w-full flex items-center justify-center px-6 py-5 text-xl font-black rounded-3xl transition-all ${isGenerating || !text.trim() ? 'bg-slate-200 text-slate-400' : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-2xl hover:-translate-y-1'}`}>
                {isGenerating ? <><LoadingSpinner className="mr-3 h-7 w-7" /> Création de l'audio...</> : 'Générer la narration'}
              </button>

              {audioResult && (
                <div className="p-8 bg-gradient-to-br from-indigo-50 to-white rounded-[2rem] border-2 border-indigo-100 animate-fadeInUp shadow-inner">
                  <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-indigo-600 rounded-xl text-white shadow-md"><AudioIcon /></div>
                      <div>
                        <h3 className="font-black text-slate-900 leading-none">Studio Mastering</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">24kHz • Mono • 16-bit</p>
                      </div>
                    </div>
                    <button onClick={() => setAudioResult(null)} className="p-2 text-slate-300 hover:text-red-500 transition-all"><TrashIcon size={22} /></button>
                  </div>
                  <div className="flex flex-col md:flex-row items-center gap-4">
                    <audio controls src={audioResult.url} className="w-full h-12 rounded-full" />
                    <button 
                      onClick={async () => {
                        setIsDownloading(true);
                        try {
                          const blob = convertPcmToMp3(audioResult.pcmData, 24000);
                          const a = document.createElement('a');
                          a.href = URL.createObjectURL(blob);
                          a.download = `narration-voxgen-${Date.now()}.mp3`;
                          a.click();
                        } finally { setIsDownloading(false); }
                      }} 
                      disabled={isDownloading} 
                      className="flex items-center justify-center gap-3 px-8 py-3 bg-white border-2 border-slate-100 rounded-2xl font-black text-xs uppercase tracking-widest text-indigo-600 hover:border-indigo-600 transition-all shadow-sm min-w-[200px]"
                    >
                      {isDownloading ? <LoadingSpinner className="h-4 w-4 text-indigo-600" /> : <><DownloadIcon /> Exporter MP3</>}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeInDown { from { opacity: 0; transform: translateY(-20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
        .animate-fadeInUp { animation: fadeInUp 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
        .animate-fadeInDown { animation: fadeInDown 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
        .animate-shake { animation: shake 0.3s ease-in-out; }
      `}</style>
    </div>
  );
};

export default App;

export enum Language {
  FRENCH = 'French',
  ENGLISH = 'English',
  SPANISH = 'Spanish',
  GERMAN = 'German',
  ITALIAN = 'Italian'
}

export type VoiceName = 'Kore' | 'Puck' | 'Charon' | 'Fenrir' | 'Zephyr';

export interface PronunciationRule {
  id: string;
  original: string;
  phonetic: string;
}

export interface TTSConfig {
  text: string;
  language: Language;
  voice: VoiceName;
  speed: number;
  pitch: number;
  pronunciationRules?: PronunciationRule[];
}

export interface HistoryItem {
  id: string;
  timestamp: number;
  text: string;
  language: Language;
  voice: VoiceName;
  audioUrl: string;
  pcmData: Uint8Array;
}

export interface AudioResult {
  blob: Blob;
  url: string;
  pcmData: Uint8Array;
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { generateSpeech } from './services/geminiService';
import { Language, VoiceName, AudioResult, HistoryItem, PronunciationRule } from './types';
import { convertPcmToMp3 } from './utils/mp3Converter';
import mammoth from 'mammoth';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js Worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.0.379/build/pdf.worker.mjs`;

// Icons
const AudioIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>;
const UploadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>;
const DriveIcon = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M7.74 2L2 12L5.43 18L11.17 8L7.74 2Z" fill="#0066DA"/><path d="M16.26 2L11.17 11L14.6 17H22L18.83 11.5L16.26 2Z" fill="#00AC47"/><path d="M11.17 11L5.43 21H18.83L22 15.5L16.26 5.5L11.17 11Z" fill="#FFBA00"/><path d="M11.17 11L5.43 21H18.83L11.17 11Z" fill="#EA4335"/></svg>;
const TrashIcon = ({ size = 16 }) => <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>;
const MagicIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2v2"/><path d="M12 20v2"/><path d="m4.93 4.93 1.41 1.41"/><path d="m17.66 17.66 1.41 1.41"/><path d="M2 12h2"/><path d="M20 12h2"/><path d="m6.34 17.66-1.41 1.41"/><path d="m19.07 4.93-1.41 1.41"/></svg>;
const PlayIcon = ({ className = "w-4 h-4" }) => <svg className={className} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>;
const LoadingSpinner = ({ className = "h-5 w-5 text-white" }) => <svg className={`animate-spin ${className}`} viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>;

const VOICES: { name: VoiceName; desc: string; type: 'M' | 'F' }[] = [
  { name: 'Kore', desc: 'Sérieux & Corporatif', type: 'M' },
  { name: 'Puck', desc: 'Énergique & Jeune', type: 'F' },
  { name: 'Charon', desc: 'Profond & Calme', type: 'M' },
  { name: 'Fenrir', desc: 'Avenant & Rassurant', type: 'M' },
  { name: 'Zephyr', desc: 'Limpide & Doux', type: 'F' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [speed, setSpeed] = useState<number>(1.0);
  const [pitch, setPitch] = useState<number>(1.0);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showUrlInput, setShowUrlInput] = useState<boolean>(false);
  const [remoteUrl, setRemoteUrl] = useState<string>('');

  // Pro Features State
  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>(() => {
    const saved = localStorage.getItem('voxgen_rules');
    return saved ? JSON.parse(saved) : [];
  });
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    const saved = localStorage.getItem('voxgen_history');
    return saved ? JSON.parse(saved) : [];
  });
  const [activePlaybackId, setActivePlaybackId] = useState<string | null>(null);
  const [currentCharIndex, setCurrentCharIndex] = useState<number>(-1);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    localStorage.setItem('voxgen_rules', JSON.stringify(pronunciationRules));
  }, [pronunciationRules]);

  useEffect(() => {
    // We only save metadata in localStorage to avoid size limits
    const metadataOnly = history.map(({ pcmData, ...rest }) => rest);
    localStorage.setItem('voxgen_history', JSON.stringify(metadataOnly));
  }, [history]);

  const words = useMemo(() => text.split(/(\s+)/), [text]);

  const handleTimeUpdate = () => {
    if (!audioRef.current || !audioResult) return;
    const duration = audioRef.current.duration;
    const currentTime = audioRef.current.currentTime;
    if (duration > 0) {
      const progress = currentTime / duration;
      const targetIndex = Math.floor(progress * text.length);
      setCurrentCharIndex(targetIndex);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined = ('target' in e) ? e.target.files?.[0] : (e as any).file;
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        setText(await file.text());
      } else if (fileName.endsWith(".docx") || file.type.includes("word")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture."); }
  };

  const handleDriveUrlImport = async () => {
    if (!remoteUrl.trim()) return;
    setIsDriveLoading(true); setError(null);
    try {
      const docIdMatch = remoteUrl.match(/\/document\/d\/([a-zA-Z0-9-_]+)/);
      const fileIdMatch = remoteUrl.match(/id=([a-zA-Z0-9-_]+)/) || remoteUrl.match(/\/file\/d\/([a-zA-Z0-9-_]+)/);
      const fileId = docIdMatch ? docIdMatch[1] : (fileIdMatch ? fileIdMatch[1] : null);
      if (!fileId) throw new Error("URL invalide.");
      const exportUrl = docIdMatch ? `https://docs.google.com/document/d/${fileId}/export?format=txt` : `https://drive.google.com/uc?export=download&id=${fileId}`;
      const response = await fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(exportUrl)}`);
      if (docIdMatch) setText(await response.text());
      else handleFileUpload({ file: new File([await response.blob()], "drive_file", { type: "application/octet-stream" }) });
      setShowUrlInput(false);
    } catch (err: any) { setError(err.message); } finally { setIsDriveLoading(false); }
  };

  const applyPronunciation = (input: string) => {
    let result = input;
    pronunciationRules.forEach(rule => {
      const regex = new RegExp(`\\b${rule.original}\\b`, 'gi');
      result = result.replace(regex, rule.phonetic);
    });
    return result;
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsGenerating(true); setError(null);
    try {
      const processedText = applyPronunciation(text);
      const result = await generateSpeech({ text: processedText, language, voice, speed, pitch });
      setAudioResult(result);
      const newHistoryItem: HistoryItem = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        text,
        language,
        voice,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistoryItem, ...prev.slice(0, 19)]); // Keep last 20
    } catch (err) { setError("Erreur de génération."); } finally { setIsGenerating(false); }
  };

  const addPronunciationRule = () => {
    setPronunciationRules([...pronunciationRules, { id: Date.now().toString(), original: '', phonetic: '' }]);
  };

  const updateRule = (id: string, field: 'original' | 'phonetic', value: string) => {
    setPronunciationRules(pronunciationRules.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const removeRule = (id: string) => {
    setPronunciationRules(pronunciationRules.filter(r => r.id !== id));
  };

  const restoreFromHistory = (item: HistoryItem) => {
    setText(item.text);
    setLanguage(item.language);
    setVoice(item.voice);
    setAudioResult({ url: item.audioUrl, pcmData: item.pcmData, blob: new Blob([]) });
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto flex flex-col lg:flex-row gap-8">

        {/* Main Content Area */}
        <div className="flex-1">
          <div className="text-center mb-10 animate-fadeInDown">
            <h1 className="text-4xl font-black text-slate-900 tracking-tight mb-2">VoxGen <span className="text-indigo-600 underline decoration-indigo-200">AI PRO</span></h1>
            <p className="text-slate-500 font-medium italic">Transformez vos écrits en narration mastered studio.</p>
          </div>

          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden mb-8">
            <div className="p-8 md:p-10">
              <div className="flex justify-between items-center mb-4">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Éditeur Dynamic-Highlight</label>
                <div className="flex gap-2">
                  <button onClick={() => fileInputRef.current?.click()} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400 transition-colors"><UploadIcon /></button>
                  <button onClick={() => setShowUrlInput(!showUrlInput)} className={`p-2 rounded-lg transition-colors ${showUrlInput ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}><DriveIcon /></button>
                  <button onClick={() => setText('')} className="p-2 hover:text-red-500 rounded-lg text-slate-400 transition-colors"><TrashIcon /></button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                </div>
              </div>

              {showUrlInput && (
                <div className="mb-6 p-4 bg-indigo-50 rounded-xl border border-indigo-100 flex gap-2 animate-fadeInDown">
                  <input type="text" placeholder="Lien Google Drive (Doc/PDF)..." value={remoteUrl} onChange={(e) => setRemoteUrl(e.target.value)} className="flex-1 px-4 py-2 rounded-lg border-none outline-none text-sm" />
                  <button onClick={handleDriveUrlImport} disabled={isDriveLoading} className="bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold text-sm">Analyser</button>
                </div>
              )}

              <div className="relative group">
                <textarea 
                  rows={8} 
                  className={`block w-full rounded-2xl border-slate-100 shadow-inner focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 text-lg p-8 bg-slate-50/30 resize-none transition-all outline-none border font-medium text-slate-800 ${audioResult ? 'opacity-0 absolute inset-0 z-0 pointer-events-none' : 'opacity-100'}`} 
                  placeholder="Collez votre texte ici..." 
                  value={text} 
                  onChange={(e) => setText(e.target.value)} 
                />

                {audioResult && (
                  <div className="w-full min-h-[224px] rounded-2xl border border-slate-100 p-8 bg-white overflow-y-auto leading-relaxed text-lg font-medium text-slate-400 cursor-text whitespace-pre-wrap" onClick={() => setAudioResult(null)}>
                    {text.split('').map((char, i) => (
                      <span key={i} className={`${i <= currentCharIndex ? 'text-indigo-600 bg-indigo-50' : ''} transition-colors duration-100`}>
                        {char}
                      </span>
                    ))}
                  </div>
                )}
                {audioResult && <div className="absolute top-2 right-4 text-[10px] font-bold text-indigo-400 animate-pulse">MODE LECTURE ACTIVÉ</div>}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-10">
                <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3">Langue</label>
                    <div className="grid grid-cols-3 gap-2">
                      {LANGS.map(l => (
                        <button key={l.id} onClick={() => setLanguage(l.id)} className={`py-2 px-1 rounded-xl text-[11px] font-bold border-2 transition-all ${language === l.id ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-600'}`}>{l.flag} {l.label}</button>
                      ))}
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3">Voix Neural</label>
                    <div className="grid grid-cols-2 gap-2">
                      {VOICES.map(v => (
                        <div key={v.name} onClick={() => setVoice(v.name)} className={`p-3 rounded-xl border-2 cursor-pointer transition-all ${voice === v.name ? 'bg-indigo-50 border-indigo-600' : 'bg-white border-slate-100'}`}>
                          <div className="flex justify-between items-center"><span className="font-bold text-xs">{v.name}</span><PlayIcon className="text-slate-300 w-3 h-3" /></div>
                          <p className="text-[9px] text-slate-400 mt-1 uppercase font-bold">{v.desc}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 space-y-6">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block">Contrôles Prosodiques</label>
                  <div className="space-y-4">
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>VITESSE</span><span className="text-indigo-600">{speed.toFixed(1)}x</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={speed} onChange={(e) => setSpeed(parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>PITCH</span><span className="text-indigo-600">{pitch.toFixed(1)}</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={pitch} onChange={(e) => setPitch(parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                  </div>
                </div>
              </div>

              {error && <div className="mt-6 p-4 bg-red-50 text-red-600 rounded-xl text-xs font-bold border-l-4 border-red-500">{error}</div>}

              <div className="mt-10 space-y-6">
                <button onClick={handleGenerate} disabled={isGenerating || !text.trim()} className={`w-full py-5 text-lg font-black rounded-2xl shadow-xl transition-all ${isGenerating || !text.trim() ? 'bg-slate-200 text-slate-400' : 'bg-indigo-600 hover:bg-indigo-700 text-white transform hover:-translate-y-1'}`}>
                  {isGenerating ? <><LoadingSpinner className="inline mr-2" /> Synthèse...</> : 'LANCER LA GÉNÉRATION'}
                </button>

                {audioResult && (
                  <div className="p-6 bg-gradient-to-r from-indigo-50 to-white rounded-2xl border border-indigo-100 animate-fadeInUp">
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex gap-2 items-center"><AudioIcon /><span className="text-sm font-black text-slate-900">MASTERING TERMINÉ</span></div>
                      <button 
                        onClick={async () => {
                          setIsDownloading(true);
                          try {
                            const blob = convertPcmToMp3(audioResult.pcmData, 24000);
                            const a = document.createElement('a');
                            a.href = URL.createObjectURL(blob);
                            a.download = `voxgen-pro-${Date.now()}.mp3`;
                            a.click();
                          } finally { setIsDownloading(false); }
                        }}
                        className="text-indigo-600 text-xs font-bold flex items-center gap-1 hover:underline"
                      >
                        {isDownloading ? <LoadingSpinner className="w-3 h-3 text-indigo-600" /> : <><DownloadIcon /> EXPORTER MP3</>}
                      </button>
                    </div>
                    <audio 
                      ref={audioRef} 
                      controls 
                      src={audioResult.url} 
                      className="w-full h-10" 
                      autoPlay
                      onTimeUpdate={handleTimeUpdate}
                      onEnded={() => setCurrentCharIndex(-1)}
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Pro Panel (Side) */}
        <div className="w-full lg:w-80 space-y-6">
          {/* Pronunciation Panel */}
          <div className="bg-white rounded-3xl border border-slate-100 p-6 shadow-lg">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-xs font-black text-slate-800 tracking-widest uppercase">Éditeur Phonétique</h3>
              <button onClick={addPronunciationRule} className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100 transition-all"><PlusIcon /></button>
            </div>
            <div className="space-y-3 max-h-60 overflow-y-auto pr-1">
              {pronunciationRules.length === 0 && <p className="text-[10px] text-slate-400 font-medium text-center py-4">Aucune règle définie.<br/>Ex: "VoxGen" -> "VoxGène"</p>}
              {pronunciationRules.map(rule => (
                <div key={rule.id} className="p-3 bg-slate-50 rounded-xl border border-slate-100 space-y-2 relative group">
                  <input placeholder="Mot original" value={rule.original} onChange={(e) => updateRule(rule.id, 'original', e.target.value)} className="w-full bg-transparent text-[11px] font-bold outline-none border-b border-slate-200 focus:border-indigo-400" />
                  <input placeholder="Prononciation" value={rule.phonetic} onChange={(e) => updateRule(rule.id, 'phonetic', e.target.value)} className="w-full bg-transparent text-[11px] outline-none italic text-indigo-600" />
                  <button onClick={() => removeRule(rule.id)} className="absolute top-1 right-2 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><TrashIcon size={12} /></button>
                </div>
              ))}
            </div>
          </div>

          {/* History Panel */}
          <div className="bg-white rounded-3xl border border-slate-100 p-6 shadow-lg">
            <h3 className="text-xs font-black text-slate-800 tracking-widest uppercase mb-4">Historique de Session</h3>
            <div className="space-y-3 max-h-[400px] overflow-y-auto pr-1">
              {history.length === 0 && <p className="text-[10px] text-slate-400 text-center py-8">Vos dernières générations s'afficheront ici.</p>}
              {history.map(item => (
                <div key={item.id} className="p-3 hover:bg-slate-50 rounded-xl border border-slate-100 transition-all cursor-pointer group" onClick={() => restoreFromHistory(item)}>
                  <div className="flex justify-between items-start mb-1">
                    <span className="text-[9px] font-black text-slate-300">{new Date(item.timestamp).toLocaleTimeString()}</span>
                    <span className="text-[9px] px-1.5 py-0.5 bg-indigo-50 text-indigo-600 rounded font-bold">{item.voice}</span>
                  </div>
                  <p className="text-[11px] text-slate-600 font-medium line-clamp-2">{item.text}</p>
                  <div className="mt-2 opacity-0 group-hover:opacity-100 flex gap-2 transition-all">
                    <button className="text-[9px] font-bold text-indigo-600 uppercase tracking-tighter hover:underline">Restaurer</button>
                  </div>
                </div>
              ))}
            </div>
            {history.length > 0 && (
              <button onClick={() => setHistory([])} className="w-full mt-4 text-[10px] font-bold text-slate-300 hover:text-red-500 transition-colors uppercase">Vider l'historique</button>
            )}
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeInDown { from { opacity: 0; transform: translateY(-20px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fadeInUp { animation: fadeInUp 0.5s ease-out forwards; }
        .animate-fadeInDown { animation: fadeInDown 0.5s ease-out forwards; }
        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        ::-webkit-scrollbar-thumb:hover { background: #cbd5e1; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { generateSpeech } from './services/geminiService';
import { Language, VoiceName, AudioResult, HistoryItem, PronunciationRule } from './types';
import { convertPcmToMp3 } from './utils/mp3Converter';
import mammoth from 'mammoth';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js Worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.0.379/build/pdf.worker.mjs`;

// Icons
const AudioIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>;
const UploadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>;
const DriveIcon = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M7.74 2L2 12L5.43 18L11.17 8L7.74 2Z" fill="#0066DA"/><path d="M16.26 2L11.17 11L14.6 17H22L18.83 11.5L16.26 2Z" fill="#00AC47"/><path d="M11.17 11L5.43 21H18.83L22 15.5L16.26 5.5L11.17 11Z" fill="#FFBA00"/><path d="M11.17 11L5.43 21H18.83L11.17 11Z" fill="#EA4335"/></svg>;
const TrashIcon = ({ size = 16 }) => <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>;
const MagicIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2v2"/><path d="M12 20v2"/><path d="m4.93 4.93 1.41 1.41"/><path d="m17.66 17.66 1.41 1.41"/><path d="M2 12h2"/><path d="M20 12h2"/><path d="m6.34 17.66-1.41 1.41"/><path d="m19.07 4.93-1.41 1.41"/></svg>;
const PlayIcon = ({ className = "w-4 h-4" }) => <svg className={className} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>;
const LoadingSpinner = ({ className = "h-5 w-5 text-white" }) => <svg className={`animate-spin ${className}`} viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>;

const VOICES: { name: VoiceName; desc: string; type: 'M' | 'F' }[] = [
  { name: 'Kore', desc: 'Sérieux & Corporatif', type: 'M' },
  { name: 'Puck', desc: 'Énergique & Jeune', type: 'F' },
  { name: 'Charon', desc: 'Profond & Calme', type: 'M' },
  { name: 'Fenrir', desc: 'Avenant & Rassurant', type: 'M' },
  { name: 'Zephyr', desc: 'Limpide & Doux', type: 'F' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [speed, setSpeed] = useState<number>(1.0);
  const [pitch, setPitch] = useState<number>(1.0);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showUrlInput, setShowUrlInput] = useState<boolean>(false);
  const [remoteUrl, setRemoteUrl] = useState<string>('');

  // Pro Features State
  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>(() => {
    const saved = localStorage.getItem('voxgen_rules');
    return saved ? JSON.parse(saved) : [];
  });
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    const saved = localStorage.getItem('voxgen_history');
    return saved ? JSON.parse(saved) : [];
  });
  const [currentCharIndex, setCurrentCharIndex] = useState<number>(-1);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    localStorage.setItem('voxgen_rules', JSON.stringify(pronunciationRules));
  }, [pronunciationRules]);

  useEffect(() => {
    const metadataOnly = history.map(({ pcmData, ...rest }) => rest);
    localStorage.setItem('voxgen_history', JSON.stringify(metadataOnly));
  }, [history]);

  const handleTimeUpdate = () => {
    if (!audioRef.current || !audioResult) return;
    const duration = audioRef.current.duration;
    const currentTime = audioRef.current.currentTime;
    if (duration > 0) {
      const progress = currentTime / duration;
      const targetIndex = Math.floor(progress * text.length);
      setCurrentCharIndex(targetIndex);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined = ('target' in e) ? e.target.files?.[0] : (e as any).file;
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        setText(await file.text());
      } else if (fileName.endsWith(".docx") || file.type.includes("word")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture."); }
  };

  const handleDriveUrlImport = async () => {
    if (!remoteUrl.trim()) return;
    setIsDriveLoading(true); setError(null);
    try {
      const docIdMatch = remoteUrl.match(/\/document\/d\/([a-zA-Z0-9-_]+)/);
      const fileIdMatch = remoteUrl.match(/id=([a-zA-Z0-9-_]+)/) || remoteUrl.match(/\/file\/d\/([a-zA-Z0-9-_]+)/);
      const fileId = docIdMatch ? docIdMatch[1] : (fileIdMatch ? fileIdMatch[1] : null);
      if (!fileId) throw new Error("URL invalide.");
      const exportUrl = docIdMatch ? `https://docs.google.com/document/d/${fileId}/export?format=txt` : `https://drive.google.com/uc?export=download&id=${fileId}`;
      const response = await fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(exportUrl)}`);
      if (docIdMatch) setText(await response.text());
      else handleFileUpload({ file: new File([await response.blob()], "drive_file", { type: "application/octet-stream" }) });
      setShowUrlInput(false);
    } catch (err: any) { setError(err.message); } finally { setIsDriveLoading(false); }
  };

  const applyPronunciation = (input: string) => {
    let result = input;
    pronunciationRules.forEach(rule => {
      const regex = new RegExp(`\\b${rule.original}\\b`, 'gi');
      result = result.replace(regex, rule.phonetic);
    });
    return result;
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsGenerating(true); setError(null);
    try {
      const processedText = applyPronunciation(text);
      const result = await generateSpeech({ text: processedText, language, voice, speed, pitch });
      setAudioResult(result);
      const newHistoryItem: HistoryItem = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        text,
        language,
        voice,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistoryItem, ...prev.slice(0, 19)]);
    } catch (err) { setError("Erreur de génération."); } finally { setIsGenerating(false); }
  };

  const handlePreview = async (e: React.MouseEvent, vName: VoiceName) => {
    e.stopPropagation();
    if (previewingVoice) return;
    setPreviewingVoice(vName);
    try {
      const res = await generateSpeech({ text: "Test de narration VoxGen.", language, voice: vName, speed: 1, pitch: 1 });
      const audio = new Audio(res.url);
      audio.onended = () => setPreviewingVoice(null);
      await audio.play();
    } catch { setPreviewingVoice(null); }
  };

  const addPronunciationRule = () => {
    setPronunciationRules([...pronunciationRules, { id: Date.now().toString(), original: '', phonetic: '' }]);
  };

  const updateRule = (id: string, field: 'original' | 'phonetic', value: string) => {
    setPronunciationRules(pronunciationRules.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const removeRule = (id: string) => {
    setPronunciationRules(pronunciationRules.filter(r => r.id !== id));
  };

  const restoreFromHistory = (item: HistoryItem) => {
    setText(item.text);
    setLanguage(item.language);
    setVoice(item.voice);
    setAudioResult({ url: item.audioUrl, pcmData: item.pcmData, blob: new Blob([]) });
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto flex flex-col lg:flex-row gap-8">

        <div className="flex-1">
          <div className="text-center mb-10 animate-fadeInDown">
            <h1 className="text-4xl font-black text-slate-900 tracking-tight mb-2">VoxGen <span className="text-indigo-600 underline decoration-indigo-200">AI PRO</span></h1>
            <p className="text-slate-500 font-medium italic">Transformez vos écrits en narration mastered studio.</p>
          </div>

          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden mb-8">
            <div className="p-8 md:p-10">
              <div className="flex justify-between items-center mb-4">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Éditeur Dynamic-Highlight</label>
                <div className="flex gap-2">
                  <button onClick={() => fileInputRef.current?.click()} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400 transition-colors"><UploadIcon /></button>
                  <button onClick={() => setShowUrlInput(!showUrlInput)} className={`p-2 rounded-lg transition-colors ${showUrlInput ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}><DriveIcon /></button>
                  <button onClick={() => setText('')} className="p-2 hover:text-red-500 rounded-lg text-slate-400 transition-colors"><TrashIcon /></button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                </div>
              </div>

              {showUrlInput && (
                <div className="mb-6 p-4 bg-indigo-50 rounded-xl border border-indigo-100 flex gap-2 animate-fadeInDown">
                  <input type="text" placeholder="Lien Google Drive (Doc/PDF)..." value={remoteUrl} onChange={(e) => setRemoteUrl(e.target.value)} className="flex-1 px-4 py-2 rounded-lg border-none outline-none text-sm" />
                  <button onClick={handleDriveUrlImport} disabled={isDriveLoading} className="bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold text-sm">Analyser</button>
                </div>
              )}

              <div className="relative group">
                <textarea 
                  rows={8} 
                  className={`block w-full rounded-2xl border-slate-100 shadow-inner focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 text-lg p-8 bg-slate-50/30 resize-none transition-all outline-none border font-medium text-slate-800 ${audioResult ? 'opacity-0 absolute inset-0 z-0 pointer-events-none' : 'opacity-100'}`} 
                  placeholder="Collez votre texte ici..." 
                  value={text} 
                  onChange={(e) => setText(e.target.value)} 
                />

                {audioResult && (
                  <div className="w-full min-h-[224px] rounded-2xl border border-slate-100 p-8 bg-white overflow-y-auto leading-relaxed text-lg font-medium text-slate-400 cursor-text whitespace-pre-wrap" onClick={() => setAudioResult(null)}>
                    {text.split('').map((char, i) => (
                      <span key={i} className={`${i <= currentCharIndex ? 'text-indigo-600 bg-indigo-50 font-bold' : ''} transition-colors duration-100`}>
                        {char}
                      </span>
                    ))}
                  </div>
                )}
                {audioResult && <div className="absolute top-2 right-4 text-[10px] font-bold text-indigo-400 animate-pulse">MODE LECTURE ACTIVÉ</div>}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-10">
                <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3">Langue</label>
                    <div className="grid grid-cols-3 gap-2">
                      {LANGS.map(l => (
                        <button key={l.id} onClick={() => setLanguage(l.id)} className={`py-2 px-1 rounded-xl text-[11px] font-bold border-2 transition-all ${language === l.id ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-600'}`}>{l.flag} {l.label}</button>
                      ))}
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3">Profils Vocaux</label>
                    <div className="grid grid-cols-2 gap-2">
                      {VOICES.map(v => (
                        <div 
                          key={v.name} 
                          onClick={() => setVoice(v.name)} 
                          className={`p-3 rounded-xl border-2 cursor-pointer transition-all group/voice ${voice === v.name ? 'bg-indigo-50 border-indigo-600' : 'bg-white border-slate-100 hover:border-indigo-200'}`}
                        >
                          <div className="flex justify-between items-center mb-1">
                            <span className={`font-bold text-xs ${voice === v.name ? 'text-indigo-700' : 'text-slate-800'}`}>{v.name}</span>
                            <button 
                              onClick={(e) => handlePreview(e, v.name)}
                              disabled={previewingVoice !== null}
                              className={`p-1.5 rounded-full transition-all ${previewingVoice === v.name ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 hover:bg-indigo-600 hover:text-white group-hover/voice:scale-110'}`}
                              title="Écouter un échantillon"
                            >
                              {previewingVoice === v.name ? <LoadingSpinner className="w-3 h-3" /> : <PlayIcon className="w-3 h-3" />}
                            </button>
                          </div>
                          <p className="text-[9px] text-slate-400 uppercase font-bold tracking-tighter leading-none">{v.desc}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 space-y-6">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block">Contrôles Prosodiques</label>
                  <div className="space-y-4">
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>VITESSE</span><span className="text-indigo-600 font-black">{speed.toFixed(1)}x</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={speed} onChange={(e) => setSpeed(parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>TONALITÉ</span><span className="text-indigo-600 font-black">{pitch.toFixed(1)}</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={pitch} onChange={(e) => setPitch(parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                  </div>
                </div>
              </div>

              {error && <div className="mt-6 p-4 bg-red-50 text-red-600 rounded-xl text-xs font-bold border-l-4 border-red-500">{error}</div>}

              <div className="mt-10 space-y-6">
                <button onClick={handleGenerate} disabled={isGenerating || !text.trim()} className={`w-full py-5 text-lg font-black rounded-2xl shadow-xl transition-all ${isGenerating || !text.trim() ? 'bg-slate-200 text-slate-400' : 'bg-indigo-600 hover:bg-indigo-700 text-white transform hover:-translate-y-1'}`}>
                  {isGenerating ? <><LoadingSpinner className="inline mr-2" /> Synthèse...</> : 'LANCER LA GÉNÉRATION'}
                </button>

                {audioResult && (
                  <div className="p-6 bg-gradient-to-r from-indigo-50 to-white rounded-2xl border border-indigo-100 animate-fadeInUp">
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex gap-2 items-center"><AudioIcon /><span className="text-sm font-black text-slate-900">MASTERING TERMINÉ</span></div>
                      <button 
                        onClick={async () => {
                          setIsDownloading(true);
                          try {
                            const blob = convertPcmToMp3(audioResult.pcmData, 24000);
                            const a = document.createElement('a');
                            a.href = URL.createObjectURL(blob);
                            a.download = `voxgen-pro-${Date.now()}.mp3`;
                            a.click();
                          } finally { setIsDownloading(false); }
                        }}
                        className="text-indigo-600 text-xs font-bold flex items-center gap-1 hover:underline"
                      >
                        {isDownloading ? <LoadingSpinner className="w-3 h-3 text-indigo-600" /> : <><DownloadIcon /> EXPORTER MP3</>}
                      </button>
                    </div>
                    <audio 
                      ref={audioRef} 
                      controls 
                      src={audioResult.url} 
                      className="w-full h-10" 
                      autoPlay
                      onTimeUpdate={handleTimeUpdate}
                      onEnded={() => setCurrentCharIndex(-1)}
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="w-full lg:w-80 space-y-6">
          <div className="bg-white rounded-3xl border border-slate-100 p-6 shadow-lg">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-xs font-black text-slate-800 tracking-widest uppercase">Dictionnaire Perso</h3>
              <button onClick={addPronunciationRule} className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100 transition-all"><PlusIcon /></button>
            </div>
            <div className="space-y-3 max-h-60 overflow-y-auto pr-1">
              {pronunciationRules.length === 0 && <p className="text-[10px] text-slate-400 font-medium text-center py-4">Aucune règle définie.<br/>Ex: "VoxGen" -> "VoxGène"</p>}
              {pronunciationRules.map(rule => (
                <div key={rule.id} className="p-3 bg-slate-50 rounded-xl border border-slate-100 space-y-2 relative group">
                  <input placeholder="Mot original" value={rule.original} onChange={(e) => updateRule(rule.id, 'original', e.target.value)} className="w-full bg-transparent text-[11px] font-bold outline-none border-b border-slate-200 focus:border-indigo-400" />
                  <input placeholder="Prononciation" value={rule.phonetic} onChange={(e) => updateRule(rule.id, 'phonetic', e.target.value)} className="w-full bg-transparent text-[11px] outline-none italic text-indigo-600" />
                  <button onClick={() => removeRule(rule.id)} className="absolute top-1 right-2 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><TrashIcon size={12} /></button>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-3xl border border-slate-100 p-6 shadow-lg">
            <h3 className="text-xs font-black text-slate-800 tracking-widest uppercase mb-4">Derniers Masters</h3>
            <div className="space-y-3 max-h-[400px] overflow-y-auto pr-1">
              {history.length === 0 && <p className="text-[10px] text-slate-400 text-center py-8">Vos dernières narrations apparaîtront ici.</p>}
              {history.map(item => (
                <div key={item.id} className="p-3 hover:bg-slate-50 rounded-xl border border-slate-100 transition-all cursor-pointer group" onClick={() => restoreFromHistory(item)}>
                  <div className="flex justify-between items-start mb-1">
                    <span className="text-[9px] font-black text-slate-300">{new Date(item.timestamp).toLocaleTimeString()}</span>
                    <span className="text-[9px] px-1.5 py-0.5 bg-indigo-50 text-indigo-600 rounded font-bold uppercase tracking-tighter">{item.voice}</span>
                  </div>
                  <p className="text-[11px] text-slate-600 font-medium line-clamp-2 leading-snug">{item.text}</p>
                </div>
              ))}
            </div>
            {history.length > 0 && (
              <button onClick={() => setHistory([])} className="w-full mt-4 text-[10px] font-bold text-slate-300 hover:text-red-500 transition-colors uppercase">Effacer</button>
            )}
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeInDown { from { opacity: 0; transform: translateY(-20px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fadeInUp { animation: fadeInUp 0.5s ease-out forwards; }
        .animate-fadeInDown { animation: fadeInDown 0.5s ease-out forwards; }
        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        ::-webkit-scrollbar-thumb:hover { background: #cbd5e1; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { generateSpeech } from './services/geminiService';
import { Language, VoiceName, AudioResult, HistoryItem, PronunciationRule } from './types';
import { convertPcmToMp3 } from './utils/mp3Converter';
import mammoth from 'mammoth';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js Worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.0.379/build/pdf.worker.mjs`;

// Icons
const AudioIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>;
const UploadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>;
const DriveIcon = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M7.74 2L2 12L5.43 18L11.17 8L7.74 2Z" fill="#0066DA"/><path d="M16.26 2L11.17 11L14.6 17H22L18.83 11.5L16.26 2Z" fill="#00AC47"/><path d="M11.17 11L5.43 21H18.83L22 15.5L16.26 5.5L11.17 11Z" fill="#FFBA00"/><path d="M11.17 11L5.43 21H18.83L11.17 11Z" fill="#EA4335"/></svg>;
const TrashIcon = ({ size = 16 }) => <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>;
const MagicIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2v2"/><path d="M12 20v2"/><path d="m4.93 4.93 1.41 1.41"/><path d="m17.66 17.66 1.41 1.41"/><path d="M2 12h2"/><path d="M20 12h2"/><path d="m6.34 17.66-1.41 1.41"/><path d="m19.07 4.93-1.41 1.41"/></svg>;
const PlayIcon = ({ className = "w-4 h-4" }) => <svg className={className} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>;
const LoadingSpinner = ({ className = "h-5 w-5 text-white" }) => <svg className={`animate-spin ${className}`} viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>;
const ExportIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>;

const VOICES: { name: VoiceName; desc: string; type: 'M' | 'F' }[] = [
  { name: 'Kore', desc: 'Sérieux & Corporatif', type: 'M' },
  { name: 'Puck', desc: 'Énergique & Jeune', type: 'F' },
  { name: 'Charon', desc: 'Profond & Calme', type: 'M' },
  { name: 'Fenrir', desc: 'Avenant & Rassurant', type: 'M' },
  { name: 'Zephyr', desc: 'Limpide & Doux', type: 'F' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [speed, setSpeed] = useState<number>(1.0);
  const [pitch, setPitch] = useState<number>(1.0);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [testingRuleId, setTestingRuleId] = useState<string | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showUrlInput, setShowUrlInput] = useState<boolean>(false);
  const [remoteUrl, setRemoteUrl] = useState<string>('');

  // Pro Features State
  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>(() => {
    const saved = localStorage.getItem('voxgen_rules');
    return saved ? JSON.parse(saved) : [];
  });
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    const saved = localStorage.getItem('voxgen_history');
    return saved ? JSON.parse(saved) : [];
  });
  const [currentCharIndex, setCurrentCharIndex] = useState<number>(-1);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dictImportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    localStorage.setItem('voxgen_rules', JSON.stringify(pronunciationRules));
  }, [pronunciationRules]);

  useEffect(() => {
    const metadataOnly = history.map(({ pcmData, ...rest }) => rest);
    localStorage.setItem('voxgen_history', JSON.stringify(metadataOnly));
  }, [history]);

  const handleTimeUpdate = () => {
    if (!audioRef.current || !audioResult) return;
    const duration = audioRef.current.duration;
    const currentTime = audioRef.current.currentTime;
    if (duration > 0) {
      const progress = currentTime / duration;
      const targetIndex = Math.floor(progress * text.length);
      setCurrentCharIndex(targetIndex);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined = ('target' in e) ? e.target.files?.[0] : (e as any).file;
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        setText(await file.text());
      } else if (fileName.endsWith(".docx") || file.type.includes("word")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture."); }
  };

  const handleDriveUrlImport = async () => {
    if (!remoteUrl.trim()) return;
    setIsDriveLoading(true); setError(null);
    try {
      const docIdMatch = remoteUrl.match(/\/document\/d\/([a-zA-Z0-9-_]+)/);
      const fileIdMatch = remoteUrl.match(/id=([a-zA-Z0-9-_]+)/) || remoteUrl.match(/\/file\/d\/([a-zA-Z0-9-_]+)/);
      const fileId = docIdMatch ? docIdMatch[1] : (fileIdMatch ? fileIdMatch[1] : null);
      if (!fileId) throw new Error("URL invalide.");
      const exportUrl = docIdMatch ? `https://docs.google.com/document/d/${fileId}/export?format=txt` : `https://drive.google.com/uc?export=download&id=${fileId}`;
      const response = await fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(exportUrl)}`);
      if (docIdMatch) setText(await response.text());
      else handleFileUpload({ file: new File([await response.blob()], "drive_file", { type: "application/octet-stream" }) });
      setShowUrlInput(false);
    } catch (err: any) { setError(err.message); } finally { setIsDriveLoading(false); }
  };

  const applyPronunciation = (input: string) => {
    let result = input;
    // Sort rules by length descending to avoid partial matches on shorter words first
    const sortedRules = [...pronunciationRules].sort((a, b) => b.original.length - a.original.length);

    sortedRules.forEach(rule => {
      if (!rule.original.trim() || !rule.phonetic.trim()) return;
      // Using word boundaries and global case-insensitive flag
      const regex = new RegExp(`\\b${rule.original.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
      result = result.replace(regex, rule.phonetic);
    });
    return result;
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsGenerating(true); setError(null);
    try {
      const processedText = applyPronunciation(text);
      const result = await generateSpeech({ text: processedText, language, voice, speed, pitch });
      setAudioResult(result);
      const newHistoryItem: HistoryItem = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        text,
        language,
        voice,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistoryItem, ...prev.slice(0, 19)]);
    } catch (err) { setError("Erreur de génération."); } finally { setIsGenerating(false); }
  };

  const handlePreview = async (e: React.MouseEvent, vName: VoiceName) => {
    e.stopPropagation();
    if (previewingVoice) return;
    setPreviewingVoice(vName);
    try {
      const res = await generateSpeech({ text: "Test de narration VoxGen.", language, voice: vName, speed: 1, pitch: 1 });
      const audio = new Audio(res.url);
      audio.onended = () => setPreviewingVoice(null);
      await audio.play();
    } catch { setPreviewingVoice(null); }
  };

  const handleTestRule = async (rule: PronunciationRule) => {
    if (testingRuleId || !rule.phonetic.trim()) return;
    setTestingRuleId(rule.id);
    try {
      const res = await generateSpeech({ text: rule.phonetic, language, voice, speed: 1, pitch: 1 });
      const audio = new Audio(res.url);
      audio.onended = () => setTestingRuleId(null);
      await audio.play();
    } catch { setTestingRuleId(null); }
  };

  const addPronunciationRule = () => {
    setPronunciationRules([{ id: Date.now().toString(), original: '', phonetic: '' }, ...pronunciationRules]);
  };

  const updateRule = (id: string, field: 'original' | 'phonetic', value: string) => {
    setPronunciationRules(pronunciationRules.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const removeRule = (id: string) => {
    setPronunciationRules(pronunciationRules.filter(r => r.id !== id));
  };

  const exportDictionary = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(pronunciationRules));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "voxgen_dictionary.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const importDictionary = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const content = await file.text();
      const rules = JSON.parse(content);
      if (Array.isArray(rules)) {
        setPronunciationRules([...rules, ...pronunciationRules]);
      }
    } catch (err) {
      setError("Erreur lors de l'importation du dictionnaire.");
    }
  };

  const restoreFromHistory = (item: HistoryItem) => {
    setText(item.text);
    setLanguage(item.language);
    setVoice(item.voice);
    setAudioResult({ url: item.audioUrl, pcmData: item.pcmData, blob: new Blob([]) });
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto flex flex-col lg:flex-row gap-8">

        <div className="flex-1">
          <div className="text-center mb-10 animate-fadeInDown">
            <h1 className="text-4xl font-black text-slate-900 tracking-tight mb-2">VoxGen <span className="text-indigo-600 underline decoration-indigo-200">AI PRO</span></h1>
            <p className="text-slate-500 font-medium italic">Studio de narration IA haute fidélité.</p>
          </div>

          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden mb-8">
            <div className="p-8 md:p-10">
              <div className="flex justify-between items-center mb-4">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Éditeur de Script</label>
                <div className="flex gap-2">
                  <button onClick={() => fileInputRef.current?.click()} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400 transition-colors" title="Importer un fichier"><UploadIcon /></button>
                  <button onClick={() => setShowUrlInput(!showUrlInput)} className={`p-2 rounded-lg transition-colors ${showUrlInput ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`} title="Lien Google Drive"><DriveIcon /></button>
                  <button onClick={() => setText('')} className="p-2 hover:text-red-500 rounded-lg text-slate-400 transition-colors" title="Effacer"><TrashIcon /></button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                </div>
              </div>

              {showUrlInput && (
                <div className="mb-6 p-4 bg-indigo-50 rounded-xl border border-indigo-100 flex gap-2 animate-fadeInDown">
                  <input type="text" placeholder="URL Google Drive (Doc/PDF)..." value={remoteUrl} onChange={(e) => setRemoteUrl(e.target.value)} className="flex-1 px-4 py-2 rounded-lg border-none outline-none text-sm" />
                  <button onClick={handleDriveUrlImport} disabled={isDriveLoading} className="bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold text-sm">Analyser</button>
                </div>
              )}

              <div className="relative group">
                <textarea 
                  rows={8} 
                  className={`block w-full rounded-2xl border-slate-100 shadow-inner focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 text-lg p-8 bg-slate-50/30 resize-none transition-all outline-none border font-medium text-slate-800 ${audioResult ? 'opacity-0 absolute inset-0 z-0 pointer-events-none' : 'opacity-100'}`} 
                  placeholder="Écrivez ou importez votre texte..." 
                  value={text} 
                  onChange={(e) => setText(e.target.value)} 
                />

                {audioResult && (
                  <div className="w-full min-h-[224px] rounded-2xl border border-slate-100 p-8 bg-white overflow-y-auto leading-relaxed text-lg font-medium text-slate-400 cursor-text whitespace-pre-wrap" onClick={() => setAudioResult(null)}>
                    {text.split('').map((char, i) => (
                      <span key={i} className={`${i <= currentCharIndex ? 'text-indigo-600 bg-indigo-50 font-bold' : ''} transition-colors duration-100`}>
                        {char}
                      </span>
                    ))}
                  </div>
                )}
                {audioResult && <div className="absolute top-2 right-4 text-[10px] font-bold text-indigo-400 animate-pulse">LECTURE EN COURS</div>}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-10">
                <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3">Langue du Moteur</label>
                    <div className="grid grid-cols-3 gap-2">
                      {LANGS.map(l => (
                        <button key={l.id} onClick={() => setLanguage(l.id)} className={`py-2 px-1 rounded-xl text-[11px] font-bold border-2 transition-all ${language === l.id ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-600'}`}>{l.flag} {l.label}</button>
                      ))}
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3">Sélecteur de Voix Neural</label>
                    <div className="grid grid-cols-2 gap-2">
                      {VOICES.map(v => (
                        <div 
                          key={v.name} 
                          onClick={() => setVoice(v.name)} 
                          className={`p-3 rounded-xl border-2 cursor-pointer transition-all group/voice ${voice === v.name ? 'bg-indigo-50 border-indigo-600' : 'bg-white border-slate-100 hover:border-indigo-200'}`}
                        >
                          <div className="flex justify-between items-center mb-1">
                            <span className={`font-bold text-xs ${voice === v.name ? 'text-indigo-700' : 'text-slate-800'}`}>{v.name}</span>
                            <button 
                              onClick={(e) => handlePreview(e, v.name)}
                              disabled={previewingVoice !== null}
                              className={`p-1.5 rounded-full transition-all ${previewingVoice === v.name ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 hover:bg-indigo-600 hover:text-white group-hover/voice:scale-110'}`}
                              title="Aperçu rapide"
                            >
                              {previewingVoice === v.name ? <LoadingSpinner className="w-3 h-3" /> : <PlayIcon className="w-3 h-3" />}
                            </button>
                          </div>
                          <p className="text-[9px] text-slate-400 uppercase font-bold tracking-tighter leading-none">{v.desc}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 space-y-6">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block">Paramètres de Modulation</label>
                  <div className="space-y-4">
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>DÉBIT (SPEED)</span><span className="text-indigo-600 font-black">{speed.toFixed(1)}x</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={speed} onChange={(e) => setSpeed(parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>TONALITÉ (PITCH)</span><span className="text-indigo-600 font-black">{pitch.toFixed(1)}</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={pitch} onChange={(e) => setPitch(parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                  </div>
                  <div className="pt-4 border-t border-slate-200/60">
                    <div className="flex items-center gap-2 text-slate-400 italic">
                      <MagicIcon />
                      <span className="text-[9px] font-bold uppercase">Le moteur pro optimise automatiquement l'intonation</span>
                    </div>
                  </div>
                </div>
              </div>

              {error && <div className="mt-6 p-4 bg-red-50 text-red-600 rounded-xl text-xs font-bold border-l-4 border-red-500">{error}</div>}

              <div className="mt-10 space-y-6">
                <button onClick={handleGenerate} disabled={isGenerating || !text.trim()} className={`w-full py-6 text-xl font-black rounded-3xl shadow-xl transition-all ${isGenerating || !text.trim() ? 'bg-slate-200 text-slate-400' : 'bg-indigo-600 hover:bg-indigo-700 text-white transform hover:-translate-y-1'}`}>
                  {isGenerating ? <><LoadingSpinner className="inline mr-2 h-6 w-6" /> GÉNÉRATION STUDIO...</> : 'RENDER LA NARRATION'}
                </button>

                {audioResult && (
                  <div className="p-8 bg-gradient-to-r from-indigo-50 to-white rounded-[2rem] border-2 border-indigo-100 animate-fadeInUp shadow-inner">
                    <div className="flex items-center justify-between mb-6">
                      <div className="flex gap-3 items-center">
                        <div className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg"><AudioIcon /></div>
                        <div>
                          <span className="text-sm font-black text-slate-900 block">MASTER RENDU</span>
                          <span className="text-[9px] font-black text-slate-400 tracking-widest uppercase">Hi-Res • 24kHz • Mono</span>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <button 
                          onClick={async () => {
                            setIsDownloading(true);
                            try {
                              const blob = convertPcmToMp3(audioResult.pcmData, 24000);
                              const a = document.createElement('a');
                              a.href = URL.createObjectURL(blob);
                              a.download = `narration-${Date.now()}.mp3`;
                              a.click();
                            } finally { setIsDownloading(false); }
                          }}
                          disabled={isDownloading}
                          className="flex items-center gap-2 px-6 py-2 bg-indigo-600 text-white text-[11px] font-black rounded-xl hover:bg-indigo-700 transition-all shadow-md"
                        >
                          {isDownloading ? <LoadingSpinner className="w-3 h-3" /> : <><DownloadIcon /> EXPORTER MP3</>}
                        </button>
                        <button onClick={() => setAudioResult(null)} className="p-2 text-slate-300 hover:text-red-500 transition-all"><TrashIcon size={20} /></button>
                      </div>
                    </div>
                    <audio 
                      ref={audioRef} 
                      controls 
                      src={audioResult.url} 
                      className="w-full h-12 rounded-full" 
                      autoPlay
                      onTimeUpdate={handleTimeUpdate}
                      onEnded={() => setCurrentCharIndex(-1)}
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="w-full lg:w-96 space-y-6">
          {/* Advanced Pronunciation Editor */}
          <div className="bg-white rounded-[2rem] border border-slate-100 p-8 shadow-xl">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-xs font-black text-slate-900 tracking-widest uppercase">Prononciation Pro</h3>
                <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase">Dictionnaire de remplacement</p>
              </div>
              <div className="flex gap-1">
                <button onClick={() => dictImportRef.current?.click()} className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:text-indigo-600 transition-all" title="Importer JSON"><UploadIcon /></button>
                <button onClick={exportDictionary} className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:text-indigo-600 transition-all" title="Exporter JSON"><ExportIcon /></button>
                <button onClick={addPronunciationRule} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-all shadow-md"><PlusIcon /></button>
              </div>
              <input type="file" ref={dictImportRef} onChange={importDictionary} accept=".json" className="hidden" />
            </div>

            <div className="space-y-4 max-h-[420px] overflow-y-auto pr-2 custom-scrollbar">
              {pronunciationRules.length === 0 && (
                <div className="text-center py-10 px-4 bg-slate-50/50 rounded-2xl border-2 border-dashed border-slate-100">
                  <p className="text-[11px] text-slate-400 font-medium italic">
                    Aucune règle personnalisée.<br/>
                    Utilisez le bouton + pour corriger des noms propres ou termes techniques.
                  </p>
                </div>
              )}
              {pronunciationRules.map(rule => (
                <div key={rule.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-3 relative group hover:border-indigo-200 transition-colors">
                  <div className="flex gap-2">
                    <div className="flex-1">
                      <label className="text-[8px] font-black text-slate-400 uppercase tracking-tighter mb-1 block">Texte original</label>
                      <input 
                        placeholder="Ex: Gemini" 
                        value={rule.original} 
                        onChange={(e) => updateRule(rule.id, 'original', e.target.value)} 
                        className="w-full bg-white px-2 py-1.5 text-[11px] font-bold rounded-lg border border-slate-200 outline-none focus:border-indigo-400 transition-all" 
                      />
                    </div>
                    <div className="flex-1">
                      <label className="text-[8px] font-black text-slate-400 uppercase tracking-tighter mb-1 block">Prononciation IA</label>
                      <input 
                        placeholder="Ex: Jèminaye" 
                        value={rule.phonetic} 
                        onChange={(e) => updateRule(rule.id, 'phonetic', e.target.value)} 
                        className="w-full bg-white px-2 py-1.5 text-[11px] font-bold text-indigo-600 rounded-lg border border-slate-200 outline-none focus:border-indigo-400 transition-all" 
                      />
                    </div>
                  </div>
                  <div className="flex justify-between items-center pt-2 border-t border-slate-200/40">
                    <button 
                      onClick={() => handleTestRule(rule)} 
                      disabled={!rule.phonetic.trim() || testingRuleId !== null}
                      className={`text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 ${testingRuleId === rule.id ? 'text-indigo-400' : 'text-indigo-600 hover:text-indigo-800 transition-colors'}`}
                    >
                      {testingRuleId === rule.id ? <LoadingSpinner className="w-2.5 h-2.5" /> : <PlayIcon className="w-2.5 h-2.5" />}
                      Tester le rendu
                    </button>
                    <button onClick={() => removeRule(rule.id)} className="text-slate-300 hover:text-red-500 transition-colors"><TrashIcon size={14} /></button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-[2rem] border border-slate-100 p-8 shadow-xl">
            <h3 className="text-xs font-black text-slate-900 tracking-widest uppercase mb-6">Master History</h3>
            <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
              {history.length === 0 && <p className="text-[10px] text-slate-400 text-center py-10 italic">Aucun enregistrement récent.</p>}
              {history.map(item => (
                <div key={item.id} className="p-4 hover:bg-indigo-50/50 rounded-2xl border border-slate-100 transition-all cursor-pointer group flex flex-col gap-2" onClick={() => restoreFromHistory(item)}>
                  <div className="flex justify-between items-center">
                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-tighter">{new Date(item.timestamp).toLocaleTimeString()}</span>
                    <span className="text-[8px] px-2 py-0.5 bg-indigo-600 text-white rounded-full font-bold uppercase">{item.voice}</span>
                  </div>
                  <p className="text-[11px] text-slate-600 font-medium line-clamp-2 leading-relaxed">{item.text}</p>
                </div>
              ))}
            </div>
            {history.length > 0 && (
              <button onClick={() => setHistory([])} className="w-full mt-6 py-2 text-[10px] font-black text-slate-300 hover:text-red-500 transition-colors uppercase tracking-widest">Vider la session</button>
            )}
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeInDown { from { opacity: 0; transform: translateY(-20px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fadeInUp { animation: fadeInUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .animate-fadeInDown { animation: fadeInDown 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #eef2f6; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #e0e7ff; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { generateSpeech } from './services/geminiService';
import { Language, VoiceName, AudioResult, HistoryItem, PronunciationRule } from './types';
import { convertPcmToMp3 } from './utils/mp3Converter';
import mammoth from 'mammoth';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js Worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.0.379/build/pdf.worker.mjs`;

// Icons
const AudioIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>;
const UploadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>;
const DriveIcon = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M7.74 2L2 12L5.43 18L11.17 8L7.74 2Z" fill="#0066DA"/><path d="M16.26 2L11.17 11L14.6 17H22L18.83 11.5L16.26 2Z" fill="#00AC47"/><path d="M11.17 11L5.43 21H18.83L22 15.5L16.26 5.5L11.17 11Z" fill="#FFBA00"/><path d="M11.17 11L5.43 21H18.83L11.17 11Z" fill="#EA4335"/></svg>;
const TrashIcon = ({ size = 16 }) => <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>;
const MagicIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2v2"/><path d="M12 20v2"/><path d="m4.93 4.93 1.41 1.41"/><path d="m17.66 17.66 1.41 1.41"/><path d="M2 12h2"/><path d="M20 12h2"/><path d="m6.34 17.66-1.41 1.41"/><path d="m19.07 4.93-1.41 1.41"/></svg>;
const PlayIcon = ({ className = "w-4 h-4" }) => <svg className={className} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>;
const LoadingSpinner = ({ className = "h-5 w-5 text-white" }) => <svg className={`animate-spin ${className}`} viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>;
const ExportIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>;

const VOICES: { name: VoiceName; desc: string; type: 'M' | 'F' }[] = [
  { name: 'Kore', desc: 'Sérieux & Corporatif', type: 'M' },
  { name: 'Puck', desc: 'Énergique & Jeune', type: 'F' },
  { name: 'Charon', desc: 'Profond & Calme', type: 'M' },
  { name: 'Fenrir', desc: 'Avenant & Rassurant', type: 'M' },
  { name: 'Zephyr', desc: 'Limpide & Doux', type: 'F' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [speed, setSpeed] = useState<number>(1.0);
  const [pitch, setPitch] = useState<number>(1.0);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [genStage, setGenStage] = useState<string>('');
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [testingRuleId, setTestingRuleId] = useState<string | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showUrlInput, setShowUrlInput] = useState<boolean>(false);
  const [remoteUrl, setRemoteUrl] = useState<string>('');

  // Pro Features State
  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>(() => {
    const saved = localStorage.getItem('voxgen_rules');
    return saved ? JSON.parse(saved) : [];
  });
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    const saved = localStorage.getItem('voxgen_history');
    return saved ? JSON.parse(saved) : [];
  });
  const [currentCharIndex, setCurrentCharIndex] = useState<number>(-1);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dictImportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    localStorage.setItem('voxgen_rules', JSON.stringify(pronunciationRules));
  }, [pronunciationRules]);

  useEffect(() => {
    const metadataOnly = history.map(({ pcmData, ...rest }) => rest);
    localStorage.setItem('voxgen_history', JSON.stringify(metadataOnly));
  }, [history]);

  const handleTimeUpdate = () => {
    if (!audioRef.current || !audioResult) return;
    const duration = audioRef.current.duration;
    const currentTime = audioRef.current.currentTime;
    if (duration > 0) {
      const progress = currentTime / duration;
      const targetIndex = Math.floor(progress * text.length);
      setCurrentCharIndex(targetIndex);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined = ('target' in e) ? e.target.files?.[0] : (e as any).file;
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        setText(await file.text());
      } else if (fileName.endsWith(".docx") || file.type.includes("word")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture."); }
  };

  const handleDriveUrlImport = async () => {
    if (!remoteUrl.trim()) return;
    setIsDriveLoading(true); setError(null);
    try {
      const docIdMatch = remoteUrl.match(/\/document\/d\/([a-zA-Z0-9-_]+)/);
      const fileIdMatch = remoteUrl.match(/id=([a-zA-Z0-9-_]+)/) || remoteUrl.match(/\/file\/d\/([a-zA-Z0-9-_]+)/);
      const fileId = docIdMatch ? docIdMatch[1] : (fileIdMatch ? fileIdMatch[1] : null);
      if (!fileId) throw new Error("URL invalide.");
      const exportUrl = docIdMatch ? `https://docs.google.com/document/d/${fileId}/export?format=txt` : `https://drive.google.com/uc?export=download&id=${fileId}`;
      const response = await fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(exportUrl)}`);
      if (docIdMatch) setText(await response.text());
      else handleFileUpload({ file: new File([await response.blob()], "drive_file", { type: "application/octet-stream" }) });
      setShowUrlInput(false);
    } catch (err: any) { setError(err.message); } finally { setIsDriveLoading(false); }
  };

  const applyPronunciation = (input: string) => {
    let result = input;
    const sortedRules = [...pronunciationRules].sort((a, b) => b.original.length - a.original.length);
    sortedRules.forEach(rule => {
      if (!rule.original.trim() || !rule.phonetic.trim()) return;
      const regex = new RegExp(`\\b${rule.original.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
      result = result.replace(regex, rule.phonetic);
    });
    return result;
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsGenerating(true);
    setError(null);

    // Simulating logical stages for better UI feedback
    setGenStage('Analyse du script...');
    await new Promise(r => setTimeout(r, 600));

    try {
      setGenStage('Synthèse de la voix neurale...');
      const processedText = applyPronunciation(text);
      const result = await generateSpeech(processedText, language, voice, speed, pitch);

      setGenStage('Optimisation acoustique (Mastering)...');
      await new Promise(r => setTimeout(r, 400));

      setAudioResult(result);
      const newHistoryItem: HistoryItem = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        text,
        language,
        voice,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistoryItem, ...prev.slice(0, 19)]);
    } catch (err) {
      setError("Désolé, une erreur est survenue lors du rendu.");
    } finally {
      setIsGenerating(false);
      setGenStage('');
    }
  };

  const handlePreview = async (e: React.MouseEvent, vName: VoiceName) => {
    e.stopPropagation();
    if (previewingVoice) return;
    setPreviewingVoice(vName);
    try {
      const res = await generateSpeech("Bonjour, je suis votre voix VoxGen.", language, vName, 1, 1);
      const audio = new Audio(res.url);
      audio.onended = () => setPreviewingVoice(null);
      await audio.play();
    } catch { setPreviewingVoice(null); }
  };

  const handleTestRule = async (rule: PronunciationRule) => {
    if (testingRuleId || !rule.phonetic.trim()) return;
    setTestingRuleId(rule.id);
    try {
      const res = await generateSpeech(rule.phonetic, language, voice, 1, 1);
      const audio = new Audio(res.url);
      audio.onended = () => setTestingRuleId(null);
      await audio.play();
    } catch { setTestingRuleId(null); }
  };

  const addPronunciationRule = () => {
    setPronunciationRules([{ id: Date.now().toString(), original: '', phonetic: '' }, ...pronunciationRules]);
  };

  const updateRule = (id: string, field: 'original' | 'phonetic', value: string) => {
    setPronunciationRules(pronunciationRules.map(r => r.id === id ? { ...r, [field]: value } : r));
