import { GoogleGenAI, Modality, Type } from "@google/genai";
import { TTSConfig, AudioResult, Language, VoiceName } from "../types";
import { decodeBase64, createWavBlob } from "../utils/audioConverter";

export async function detectLanguage(text: string): Promise<Language> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Identify the language of the following text and return ONLY one of these values: French, English, Spanish, German, Italian. If unsure, default to English. Text: "${text.substring(0, 500)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { 
              type: Type.STRING,
              description: "The detected language name."
            }
          },
          required: ["language"]
        }
      }
    });

    const json = JSON.parse(response.text);
    const detected = json.language as Language;

    if (Object.values(Language).includes(detected)) {
      return detected;
    }
    return Language.ENGLISH;
  } catch (error) {
    console.error("Language detection error:", error);
    return Language.ENGLISH;
  }
}

export async function generateSpeech(
  text: string, 
  language: Language, 
  voice: VoiceName, 
  speed: number, 
  pitch: number
): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let speedDesc = "à une vitesse normale";
  if (speed < 0.8) speedDesc = "très lentement";
  else if (speed < 1.0) speedDesc = "lentement";
  else if (speed > 1.5) speedDesc = "très rapidement";
  else if (speed > 1.0) speedDesc = "rapidement";

  let pitchDesc = "avec une tonalité naturelle";
  if (pitch < 0.8) pitchDesc = "avec une voix très grave et profonde";
  else if (pitch < 1.0) pitchDesc = "avec une voix légèrement plus grave";
  else if (pitch > 1.5) pitchDesc = "avec une voix très aiguë et enfantine";
  else if (pitch > 1.0) pitchDesc = "avec une voix légèrement plus aiguë";

  const languageInstructions: Record<Language, string> = {
    [Language.FRENCH]: `Dis ceci de manière naturelle, ${speedDesc} et ${pitchDesc}. Respecte les pauses indiquées par des points de suspension ou la ponctuation :`,
    [Language.ENGLISH]: `Speak naturally, ${speedDesc.replace('lentement', 'slowly').replace('rapidement', 'fast')} and ${pitchDesc.replace('grave', 'deep').replace('aiguë', 'high-pitched')}. Respect pauses marked by ellipses or punctuation:`,
    [Language.SPANISH]: `Habla de forma natural, ${speedDesc} y ${pitchDesc}:`,
    [Language.GERMAN]: `Sprich natürlich, ${speedDesc} und ${pitchDesc}:`,
    [Language.ITALIAN]: `Parla in modo naturale, ${speedDesc} e ${pitchDesc}:`
  };

  const prompt = `${languageInstructions[language]} ${text}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data received from Gemini API.");
    }

    const pcmBytes = decodeBase64(base64Audio);
    const wavBlob = createWavBlob(pcmBytes, 24000);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      blob: wavBlob,
      url: audioUrl,
      pcmData: pcmBytes
    };
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    throw error;
  }
}

/**
 * Converts raw PCM 16-bit (little-endian) to MP3.
 * Gemini TTS provides 24000Hz mono.
 */
export function convertPcmToMp3(pcmData: Uint8Array, sampleRate: number = 24000): Blob {
  // Accès à lamejs via le scope global (window) car l'import ESM est instable pour cette lib
  const lame = (window as any).lamejs;
  if (!lame) {
    throw new Error("La bibliothèque LAME n'est pas chargée. Vérifiez votre connexion internet.");
  }

  // Convert Uint8Array buffer to Int16Array (16-bit PCM)
  const pcm16 = new Int16Array(pcmData.buffer);

  // Mp3Encoder(channels, samplerate, kbps)
  const mp3encoder = new lame.Mp3Encoder(1, sampleRate, 128);
  const mp3Data: Uint8Array[] = [];

  const sampleBlockSize = 576; // multiple of 576 is standard for LAME

  for (let i = 0; i < pcm16.length; i += sampleBlockSize) {
    const sampleChunk = pcm16.subarray(i, i + sampleBlockSize);
    const mp3buf = mp3encoder.encodeBuffer(sampleChunk);
    if (mp3buf.length > 0) {
      mp3Data.push(new Uint8Array(mp3buf));
    }
  }

  const endBuf = mp3encoder.flush();
  if (endBuf.length > 0) {
    mp3Data.push(new Uint8Array(endBuf));
  }

  return new Blob(mp3Data, { type: 'audio/mp3' });
}

