export async function analyzeContent(text: string): Promise<{ language: Language; recommendedVoice: VoiceName; style: string }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyse ce texte pour la synthèse vocale. 
      1. Identifie la langue (French, English, Spanish, German, Italian).
      2. Détermine le style (Documentaire, Corporatif, Énergique, Conte, Poétique).
      3. Recommande la meilleure voix parmi : 
         - 'Charon' (Sérieux, posé, idéal pour documentaire/tech)
         - 'Kore' (Pro, direct, idéal pour business/news)
         - 'Puck' (Dynamique, jeune, idéal pour pub/sport)
         - 'Fenrir' (Chaleureux, rassurant, idéal pour histoires/casual)
         - 'Zephyr' (Doux, clair, idéal pour poésie/méditation)

      Texte: "${text.substring(0, 1000)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { type: Type.STRING },
            recommendedVoice: { type: Type.STRING },
            style: { type: Type.STRING }
          },
          required: ["language", "recommendedVoice", "style"]
        }
      }
    });

    const json = JSON.parse(response.text);
    return {
      language: (Object.values(Language).includes(json.language as Language) ? json.language : Language.ENGLISH) as Language,
      recommendedVoice: json.recommendedVoice as VoiceName,
      style: json.style
    };
  } catch (error) {
    console.error("Content analysis error:", error);
    return { language: Language.FRENCH, recommendedVoice: 'Fenrir', style: 'Standard' };
  }
}

export async function generateSpeech(
  text: string, 
  language: Language, 
  voice: VoiceName, 
  speed: number, 
  pitch: number
): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Instructions spécifiques pour le style narrateur documentaire si Charon est choisi
  const isDocumentary = voice === 'Charon';

  let speedDesc = "à une vitesse normale";
  if (speed < 0.8) speedDesc = "très lentement";
  else if (speed < 1.0) speedDesc = "lentement";
  else if (speed > 1.5) speedDesc = "très rapidement";
  else if (speed > 1.0) speedDesc = "rapidement";

  let pitchDesc = "avec une tonalité naturelle";
  if (pitch < 0.8) pitchDesc = "avec une voix très grave et profonde";
  else if (pitch < 1.0) pitchDesc = "avec une voix légèrement plus grave";
  else if (pitch > 1.5) pitchDesc = "avec une voix très aiguë et enfantine";
  else if (pitch > 1.0) pitchDesc = "avec une voix légèrement plus aiguë";

  const styleContext = isDocumentary 
    ? "Adopte un ton de narrateur de documentaire technologique : profond, posé, pédagogique et inspirant. Marque des pauses naturelles pour laisser respirer les concepts."
    : "Dis ceci de manière naturelle et fluide.";

  const languageInstructions: Record<Language, string> = {
    [Language.FRENCH]: `${styleContext} Vitesse : ${speedDesc}, Tonalité : ${pitchDesc}. Texte :`,
    [Language.ENGLISH]: `${styleContext.replace('narrateur de documentaire', 'documentary narrator')} Speed: ${speedDesc.replace('lentement', 'slowly')}, Pitch: ${pitchDesc.replace('grave', 'deep')}. Text:`,
    [Language.SPANISH]: `Habla de forma natural, ${speedDesc} y ${pitchDesc}:`,
    [Language.GERMAN]: `Sprich natürlich, ${speedDesc} und ${pitchDesc}:`,
    [Language.ITALIAN]: `Parla in modo naturale, ${speedDesc} e ${pitchDesc}:`
  };

  const prompt = `${languageInstructions[language]} ${text}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) throw new Error("No audio data received.");

    const pcmBytes = decodeBase64(base64Audio);
    const wavBlob = createWavBlob(pcmBytes, 24000);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      blob: wavBlob,
      url: audioUrl,
      pcmData: pcmBytes
    };
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    throw error;
  }
}

