const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [speed, setSpeed] = useState<number>(1.0);
  const [pitch, setPitch] = useState<number>(1.0);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [genStage, setGenStage] = useState<string>('');
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [testingRuleId, setTestingRuleId] = useState<string | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showUrlInput, setShowUrlInput] = useState<boolean>(false);
  const [remoteUrl, setRemoteUrl] = useState<string>('');
  const [isAutoVoice, setIsAutoVoice] = useState<boolean>(true);
  const [detectedStyle, setDetectedStyle] = useState<string>('');

  // Pro Features State
  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>(() => {
    const saved = localStorage.getItem('voxgen_rules');
    return saved ? JSON.parse(saved) : [];
  });
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    const saved = localStorage.getItem('voxgen_history');
    return saved ? JSON.parse(saved) : [];
  });
  const [currentCharIndex, setCurrentCharIndex] = useState<number>(-1);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dictImportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    localStorage.setItem('voxgen_rules', JSON.stringify(pronunciationRules));
  }, [pronunciationRules]);

  useEffect(() => {
    const metadataOnly = history.map(({ pcmData, ...rest }) => rest);
    localStorage.setItem('voxgen_history', JSON.stringify(metadataOnly));
  }, [history]);

  const handleTimeUpdate = () => {
    if (!audioRef.current || !audioResult) return;
    const duration = audioRef.current.duration;
    const currentTime = audioRef.current.currentTime;
    if (duration > 0) {
      const progress = currentTime / duration;
      const targetIndex = Math.floor(progress * text.length);
      setCurrentCharIndex(targetIndex);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined = ('target' in e) ? e.target.files?.[0] : (e as any).file;
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        setText(await file.text());
      } else if (fileName.endsWith(".docx") || file.type.includes("word")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture."); }
  };

  const handleDriveUrlImport = async () => {
    if (!remoteUrl.trim()) return;
    setIsDriveLoading(true); setError(null);
    try {
      const docIdMatch = remoteUrl.match(/\/document\/d\/([a-zA-Z0-9-_]+)/);
      const fileIdMatch = remoteUrl.match(/id=([a-zA-Z0-9-_]+)/) || remoteUrl.match(/\/file\/d\/([a-zA-Z0-9-_]+)/);
      const fileId = docIdMatch ? docIdMatch[1] : (fileIdMatch ? fileIdMatch[1] : null);
      if (!fileId) throw new Error("URL invalide.");
      const exportUrl = docIdMatch ? `https://docs.google.com/document/d/${fileId}/export?format=txt` : `https://drive.google.com/uc?export=download&id=${fileId}`;
      const response = await fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(exportUrl)}`);
      if (docIdMatch) setText(await response.text());
      else handleFileUpload({ file: new File([await response.blob()], "drive_file", { type: "application/octet-stream" }) });
      setShowUrlInput(false);
    } catch (err: any) { setError(err.message); } finally { setIsDriveLoading(false); }
  };

  const applyPronunciation = (input: string) => {
    let result = input;
    const sortedRules = [...pronunciationRules].sort((a, b) => b.original.length - a.original.length);
    sortedRules.forEach(rule => {
      if (!rule.original.trim() || !rule.phonetic.trim()) return;
      const regex = new RegExp(`\\b${rule.original.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
      result = result.replace(regex, rule.phonetic);
    });
    return result;
  };

