              <BrainIcon />
              <span className="ml-2 text-[10px] font-black text-indigo-600 uppercase tracking-widest">Powered by Gemini AI</span>
            </div>
            <h1 className="text-4xl font-black text-slate-900 tracking-tight mb-2">VoxGen <span className="text-indigo-600 underline decoration-indigo-200">AI PRO</span></h1>
            <p className="text-slate-500 font-medium italic">Le studio de narration futuriste à portée de main.</p>
          </div>

          <div className={`bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden mb-8 transition-all duration-700 ${isGenerating ? 'ring-4 ring-indigo-200 ring-opacity-50 scale-[0.99] grayscale-[0.2]' : ''}`}>
            <div className="p-8 md:p-10 relative">

              {/* Generation Overlay */}
              {isGenerating && (
                <div className="absolute inset-0 z-50 bg-white/60 backdrop-blur-md flex flex-col items-center justify-center animate-fadeInUp">
                  <div className="relative mb-8">
