                      className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[9px] font-black uppercase transition-all ${isAutoVoice ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}
                    >
                      <BrainIcon /> Selection IA {isAutoVoice ? 'ON' : 'OFF'}
                    </button>
                  </div>

                  <div className={isAutoVoice ? 'opacity-50 pointer-events-none' : ''}>
                    <div className="grid grid-cols-3 gap-2 mb-4">
                      {LANGS.map(l => (
                        <button key={l.id} onClick={() => setLanguage(l.id)} className={`py-2 px-1 rounded-xl text-[11px] font-bold border-2 transition-all ${language === l.id ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-600'}`}>{l.flag} {l.label}</button>
                      ))}
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      {VOICES.map(v => (
                        <div 
                          key={v.name} 
                          onClick={() => setVoice(v.name)} 
                          className={`p-3 rounded-xl border-2 cursor-pointer transition-all group/voice ${voice === v.name ? 'bg-indigo-50 border-indigo-600' : 'bg-white border-slate-100 hover:border-indigo-200'}`}
                        >
                          <div className="flex justify-between items-center mb-1">
                            <span className={`font-bold text-xs ${voice === v.name ? 'text-indigo-700' : 'text-slate-800'}`}>{v.name}</span>
                            <button 
                              onClick={(e) => handlePreview(e, v.name)}
                              disabled={previewingVoice !== null}
                              className={`p-1.5 rounded-full transition-all ${previewingVoice === v.name ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 hover:bg-indigo-600 hover:text-white group-hover/voice:scale-110'}`}
                            >
                              {previewingVoice === v.name ? <LoadingSpinner className="w-3 h-3" /> : <PlayIcon className="w-3 h-3" />}
                            </button>
                          </div>
                          <p className="text-[9px] text-slate-400 uppercase font-bold tracking-tighter leading-none">{v.desc}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 space-y-6">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block">Paramètres de Rendu</label>
                  <div className="space-y-4">
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>VITESSE D'ÉLOCUTION</span><span className="text-indigo-600 font-black">{speed.toFixed(1)}x</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={speed} onChange={(e) => setSpeed(parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>TONALITÉ (PITCH)</span><span className="text-indigo-600 font-black">{pitch.toFixed(1)}</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={pitch} onChange={(e) => setPitch(parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
                  </div>
                  <div className="pt-4 mt-4 border-t border-slate-200/50">
                    <p className="text-[9px] text-slate-400 font-medium italic">Astuce : Utilisez une tonalité basse (0.8) avec Charon pour un effet narrateur tech encore plus profond.</p>
                  </div>
                </div>
              </div>

              {error && <div className="mt-6 p-4 bg-red-50 text-red-600 rounded-xl text-xs font-bold border-l-4 border-red-500">{error}</div>}

              <div className="mt-10 space-y-6">
                <button 
                  onClick={handleGenerate} 
                  disabled={isGenerating || !text.trim()} 
                  className={`relative w-full py-6 text-xl font-black rounded-3xl shadow-xl transition-all overflow-hidden group ${isGenerating || !text.trim() ? 'bg-slate-200 text-slate-400' : 'bg-indigo-600 hover:bg-indigo-700 text-white transform hover:-translate-y-1'}`}
                >
                  <span className={`relative z-10 flex items-center justify-center gap-3`}>
                    {isGenerating ? 'ANALYSES & SYNTHÈSE...' : 'RENDER LA NARRATION'}
                  </span>
                  {!isGenerating && text.trim() && (
                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
                  )}
                </button>

                {audioResult && (
                  <div className="p-8 bg-gradient-to-r from-indigo-50 to-white rounded-[2rem] border-2 border-indigo-100 animate-fadeInUp shadow-inner">
                    <div className="flex items-center justify-between mb-6">
                      <div className="flex gap-3 items-center">
                        <div className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg"><AudioIcon /></div>
                        <div>
                          <span className="text-sm font-black text-slate-900 block">MASTER RENDU</span>
                          <span className="text-[9px] font-black text-slate-400 tracking-widest uppercase">{voice} • Hi-Res • {detectedStyle || 'Manual'}</span>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <button 
                          onClick={async () => {
                            setIsDownloading(true);
                            try {
                              const blob = convertPcmToMp3(audioResult.pcmData, 24000);
                              const a = document.createElement('a');
                              a.href = URL.createObjectURL(blob);
                              a.download = `narration-${Date.now()}.mp3`;
                              a.click();
                            } finally { setIsDownloading(false); }
                          }}
                          className="flex items-center gap-2 px-6 py-2 bg-indigo-600 text-white text-[11px] font-black rounded-xl hover:bg-indigo-700 transition-all shadow-md"
                        >
                          {isDownloading ? <LoadingSpinner className="w-3 h-3" /> : <><DownloadIcon /> EXPORTER MP3</>}
                        </button>
                        <button onClick={() => setAudioResult(null)} className="p-2 text-slate-300 hover:text-red-500 transition-all"><TrashIcon size={20} /></button>
                      </div>
                    </div>
                    <audio 
                      ref={audioRef} 
                      controls 
                      src={audioResult.url} 
                      className="w-full h-12 rounded-full" 
                      autoPlay
                      onTimeUpdate={handleTimeUpdate}
                      onEnded={() => setCurrentCharIndex(-1)}
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="w-full lg:w-96 space-y-6">
          <div className="bg-white rounded-[2rem] border border-slate-100 p-8 shadow-xl">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-xs font-black text-slate-900 tracking-widest uppercase">Dictionnaire Pro</h3>
                <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase">Prononciation Custom</p>
              </div>
              <div className="flex gap-1">
                <button onClick={() => dictImportRef.current?.click()} className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:text-indigo-600 transition-all"><UploadIcon /></button>
                <button onClick={exportDictionary} className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:text-indigo-600 transition-all"><ExportIcon /></button>
                <button onClick={addPronunciationRule} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-all shadow-md"><PlusIcon /></button>
              </div>
              <input type="file" ref={dictImportRef} onChange={importDictionary} accept=".json" className="hidden" />
            </div>

            <div className="space-y-4 max-h-[420px] overflow-y-auto pr-2 custom-scrollbar">
              {pronunciationRules.length === 0 && (
                <div className="text-center py-10 px-4 bg-slate-50/50 rounded-2xl border-2 border-dashed border-slate-100">
                  <p className="text-[11px] text-slate-400 font-medium italic">Réglez les noms complexes ici.</p>
                </div>
              )}
              {pronunciationRules.map(rule => (
                <div key={rule.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-3 relative group hover:border-indigo-200 transition-colors">
                  <div className="flex gap-2">
                    <input value={rule.original} onChange={(e) => updateRule(rule.id, 'original', e.target.value)} className="w-1/2 bg-white px-2 py-1.5 text-[11px] font-bold rounded-lg border border-slate-200 outline-none" placeholder="Texte" />
                    <input value={rule.phonetic} onChange={(e) => updateRule(rule.id, 'phonetic', e.target.value)} className="w-1/2 bg-white px-2 py-1.5 text-[11px] font-bold text-indigo-600 rounded-lg border border-slate-200 outline-none" placeholder="Phonétique" />
                  </div>
                  <div className="flex justify-between items-center pt-2 border-t border-slate-200/40">
                    <button onClick={() => handleTestRule(rule)} className="text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 text-indigo-600">
                      {testingRuleId === rule.id ? <LoadingSpinner className="w-2.5 h-2.5" /> : <PlayIcon className="w-2.5 h-2.5" />} Tester
                    </button>
                    <button onClick={() => removeRule(rule.id)} className="text-slate-300 hover:text-red-500 transition-colors"><TrashIcon size={14} /></button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-[2rem] border border-slate-100 p-8 shadow-xl">
            <h3 className="text-xs font-black text-slate-900 tracking-widest uppercase mb-6">Archive Audio</h3>
            <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
              {history.length === 0 && <p className="text-[10px] text-slate-400 text-center py-10 italic">Aucun master récent.</p>}
              {history.map(item => (
                <div key={item.id} className="p-4 hover:bg-indigo-50/50 rounded-2xl border border-slate-100 transition-all cursor-pointer group flex flex-col gap-2" onClick={() => restoreFromHistory(item)}>
                  <div className="flex justify-between items-center">
                    <span className="text-[9px] font-black text-slate-300 uppercase">{new Date(item.timestamp).toLocaleTimeString()}</span>
                    <span className="text-[8px] px-2 py-0.5 bg-indigo-600 text-white rounded-full font-bold">{item.voice}</span>
                  </div>
                  <p className="text-[11px] text-slate-600 font-medium line-clamp-2 leading-relaxed">{item.text}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeInDown { from { opacity: 0; transform: translateY(-20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes loadingProgress { from { width: 0%; } to { width: 100%; } }
        .animate-fadeInUp { animation: fadeInUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .animate-fadeInDown { animation: fadeInDown 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .animate-loadingProgress { animation: loadingProgress 2s ease-in-out infinite; }
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #eef2f6; border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { generateSpeech, analyzeContent } from './services/geminiService';
import { Language, VoiceName, AudioResult, HistoryItem, PronunciationRule } from './types';
import { convertPcmToMp3 } from './utils/mp3Converter';
import mammoth from 'mammoth';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js Worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.0.379/build/pdf.worker.mjs`;

// Constants
const MAX_CHARS = 30000;

// Icons
const AudioIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 5L6 9H2v6h4l5 4V5z"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>;
const DownloadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>;
const UploadIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>;
const DriveIcon = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M7.74 2L2 12L5.43 18L11.17 8L7.74 2Z" fill="#0066DA"/><path d="M16.26 2L11.17 11L14.6 17H22L18.83 11.5L16.26 2Z" fill="#00AC47"/><path d="M11.17 11L5.43 21H18.83L22 15.5L16.26 5.5L11.17 11Z" fill="#FFBA00"/><path d="M11.17 11L5.43 21H18.83L11.17 11Z" fill="#EA4335"/></svg>;
const TrashIcon = ({ size = 16 }) => <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>;
const PlayIcon = ({ className = "w-4 h-4" }) => <svg className={className} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>;
const LoadingSpinner = ({ className = "h-5 w-5 text-white" }) => <svg className={`animate-spin ${className}`} viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>;
const PlusIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>;
const ExportIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>;
const BrainIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9.5 2A2.5 2.5 0 0 1 12 4.5v15a2.5 2.5 0 0 1-4.96.44 2.5 2.5 0 0 1-2.04-2.44V10.5A2.5 2.5 0 0 1 7.5 8h2"/><path d="M14.5 2A2.5 2.5 0 0 0 12 4.5v15a2.5 2.5 0 0 0 4.96.44 2.5 2.5 0 0 0 2.04-2.44V10.5A2.5 2.5 0 0 0 16.5 8h-2"/></svg>;

const VOICES: { name: VoiceName; desc: string; type: 'M' | 'F' }[] = [
  { name: 'Charon', desc: 'Narrateur Documentaire', type: 'M' },
  { name: 'Kore', desc: 'Corporatif & Sérieux', type: 'M' },
  { name: 'Puck', desc: 'Énergique & Jeune', type: 'F' },
  { name: 'Fenrir', desc: 'Conteur Chaleureux', type: 'M' },
  { name: 'Zephyr', desc: 'Doux & Poétique', type: 'F' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [voice, setVoice] = useState<VoiceName>('Fenrir');
  const [speed, setSpeed] = useState<number>(1.0);
  const [pitch, setPitch] = useState<number>(1.0);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [genStage, setGenStage] = useState<string>('');
  const [isDownloading, setIsDownloading] = useState<boolean>(false);
  const [isDriveLoading, setIsDriveLoading] = useState<boolean>(false);
  const [previewingVoice, setPreviewingVoice] = useState<VoiceName | null>(null);
  const [testingRuleId, setTestingRuleId] = useState<string | null>(null);
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showUrlInput, setShowUrlInput] = useState<boolean>(false);
  const [remoteUrl, setRemoteUrl] = useState<string>('');
  const [isAutoVoice, setIsAutoVoice] = useState<boolean>(true);
  const [detectedStyle, setDetectedStyle] = useState<string>('');

  // Pro Features State
  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>(() => {
    const saved = localStorage.getItem('voxgen_rules');
    return saved ? JSON.parse(saved) : [];
  });
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    const saved = localStorage.getItem('voxgen_history');
    return saved ? JSON.parse(saved) : [];
  });
  const [currentCharIndex, setCurrentCharIndex] = useState<number>(-1);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dictImportRef = useRef<HTMLInputElement>(null);

  const charCount = text.length;
  const isOverLimit = charCount > MAX_CHARS;

  useEffect(() => {
    localStorage.setItem('voxgen_rules', JSON.stringify(pronunciationRules));
  }, [pronunciationRules]);

  useEffect(() => {
    const metadataOnly = history.map(({ pcmData, ...rest }) => rest);
    localStorage.setItem('voxgen_history', JSON.stringify(metadataOnly));
  }, [history]);

  const handleTimeUpdate = () => {
    if (!audioRef.current || !audioResult) return;
    const duration = audioRef.current.duration;
    const currentTime = audioRef.current.currentTime;
    if (duration > 0) {
      const progress = currentTime / duration;
      const targetIndex = Math.floor(progress * text.length);
      setCurrentCharIndex(targetIndex);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement> | { file: File }) => {
    let file: File | undefined = ('target' in e) ? e.target.files?.[0] : (e as any).file;
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      let importedText = "";
      if (fileName.endsWith(".txt") || file.type === "text/plain") {
        importedText = await file.text();
      } else if (fileName.endsWith(".docx") || file.type.includes("word")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        importedText = result.value;
      } else if (fileName.endsWith(".pdf") || file.type === "application/pdf") {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          importedText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
      }
      setText(importedText);
    } catch (err) { setError("Erreur de lecture."); }
  };

  const handleDriveUrlImport = async () => {
    if (!remoteUrl.trim()) return;
    setIsDriveLoading(true); setError(null);
    try {
      const docIdMatch = remoteUrl.match(/\/document\/d\/([a-zA-Z0-9-_]+)/);
      const fileIdMatch = remoteUrl.match(/id=([a-zA-Z0-9-_]+)/) || remoteUrl.match(/\/file\/d\/([a-zA-Z0-9-_]+)/);
      const fileId = docIdMatch ? docIdMatch[1] : (fileIdMatch ? fileIdMatch[1] : null);
      if (!fileId) throw new Error("URL invalide.");
      const exportUrl = docIdMatch ? `https://docs.google.com/document/d/${fileId}/export?format=txt` : `https://drive.google.com/uc?export=download&id=${fileId}`;
      const response = await fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(exportUrl)}`);
      if (docIdMatch) setText(await response.text());
      else handleFileUpload({ file: new File([await response.blob()], "drive_file", { type: "application/octet-stream" }) });
      setShowUrlInput(false);
    } catch (err: any) { setError(err.message); } finally { setIsDriveLoading(false); }
  };

  const applyPronunciation = (input: string) => {
    let result = input;
    const sortedRules = [...pronunciationRules].sort((a, b) => b.original.length - a.original.length);
    sortedRules.forEach(rule => {
      if (!rule.original.trim() || !rule.phonetic.trim()) return;
      const regex = new RegExp(`\\b${rule.original.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
      result = result.replace(regex, rule.phonetic);
    });
    return result;
  };

  const handleGenerate = async () => {
    if (!text.trim() || isOverLimit) return;
    setIsGenerating(true);
    setError(null);

    let targetVoice = voice;
    let targetLang = language;

    try {
      if (isAutoVoice) {
        setGenStage('Analyse sémantique du contenu...');
        const analysis = await analyzeContent(text);
        targetVoice = analysis.recommendedVoice;
        targetLang = analysis.language;
        setDetectedStyle(analysis.style);
        setVoice(targetVoice);
        setLanguage(targetLang);
        await new Promise(r => setTimeout(r, 800));
      } else {
        setGenStage('Analyse du script...');
        await new Promise(r => setTimeout(r, 600));
      }

      setGenStage('Synthèse de la voix neurale...');
      const processedText = applyPronunciation(text);
      const result = await generateSpeech(processedText, targetLang, targetVoice, speed, pitch);

      setGenStage('Optimisation acoustique (Mastering)...');
      await new Promise(r => setTimeout(r, 400));

      setAudioResult(result);
      const newHistoryItem: HistoryItem = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        text,
        language: targetLang,
        voice: targetVoice,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistoryItem, ...prev.slice(0, 19)]);
    } catch (err) {
      setError("Désolé, une erreur est survenue lors du rendu.");
    } finally {
      setIsGenerating(false);
      setGenStage('');
    }
  };

  const handlePreview = async (e: React.MouseEvent, vName: VoiceName) => {
    e.stopPropagation();
    if (previewingVoice) return;
    setPreviewingVoice(vName);
    try {
      const res = await generateSpeech("Bonjour, je suis votre voix VoxGen.", language, vName, 1, 1);
      const audio = new Audio(res.url);
      audio.onended = () => setPreviewingVoice(null);
      await audio.play();
    } catch { setPreviewingVoice(null); }
  };

  const handleTestRule = async (rule: PronunciationRule) => {
    if (testingRuleId || !rule.phonetic.trim()) return;
    setTestingRuleId(rule.id);
    try {
      const res = await generateSpeech(rule.phonetic, language, voice, 1, 1);
      const audio = new Audio(res.url);
      audio.onended = () => setTestingRuleId(null);
      await audio.play();
    } catch { setTestingRuleId(null); }
  };

  const addPronunciationRule = () => {
    setPronunciationRules([{ id: Date.now().toString(), original: '', phonetic: '' }, ...pronunciationRules]);
  };

  const updateRule = (id: string, field: 'original' | 'phonetic', value: string) => {
    setPronunciationRules(pronunciationRules.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const removeRule = (id: string) => {
    setPronunciationRules(pronunciationRules.filter(r => r.id !== id));
  };

  const exportDictionary = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(pronunciationRules));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "voxgen_dictionary.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const importDictionary = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
