      if (Array.isArray(rules)) {
        setPronunciationRules([...rules, ...pronunciationRules]);
      }
    } catch (err) {
      setError("Erreur lors de l'importation.");
    }
  };

  const restoreFromHistory = (item: HistoryItem) => {
    setText(item.text);
    setLanguage(item.language);
