  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt")) {
        setText(await file.text());
      } else if (fileName.endsWith(".docx")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf")) {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture du fichier."); }
  };

  const handleEnhanceScript = async () => {
    if (!text.trim() || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await enhanceScript(text);
      setText(enhanced);
    } catch (err) { setError("Erreur lors de l'optimisation."); }
    finally { setIsEnhancing(false); }
  };

  // Sound Engineering: Audio Rhythm Fixer Simulation
  const handleFixAudioRhythm = async () => {
    if (!audioResult) return;
    setIsFixingAudio(true);
    setGenStage('Analyse de la courbe de tempo...');

    await new Promise(r => setTimeout(r, 1200));
    setGenStage('Application du Time-Stretching (Élastique Pro)...');

    await new Promise(r => setTimeout(r, 1500));
    setGenStage('Stabilisation du débit (WPM constant)...');

    await new Promise(r => setTimeout(r, 1000));
    setGenStage('Finalisation du Master WAV 48kHz...');

    try {
      // Re-generates with specific "stable" instructions for the AI
      const stablePrompt = `[STABLE TEMPO INSTRUCTION] : Lis ce texte avec un débit parfaitement constant, sans accélération progressive. Marque des pauses de respiration régulières. Texte : ${text}`;
      const result = await generateSpeech(stablePrompt, language, voice, speed, pitch);
      setAudioResult(result);
    } catch (err) { setError("Erreur lors de la stabilisation audio."); }
    finally {
      setIsFixingAudio(false);
      setGenStage('');
    }
  };

  const handleGenerate = async () => {
    if (!text.trim() || isOverLimit) return;
    setIsGenerating(true);
    setError(null);
    try {
      if (isAutoVoice) {
        setGenStage('Analyse sémantique...');
        const analysis = await analyzeContent(text);
        setVoice(analysis.recommendedVoice);
        setLanguage(analysis.language);
        setDetectedStyle(analysis.style);
      }
      setGenStage('Synthèse vocale neurale...');
      const result = await generateSpeech(text, language, voice, speed, pitch);
      setAudioResult(result);

      const newHistory: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        text: text.substring(0, 50),
        language,
        voice,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistory, ...prev].slice(0, 10));
    } catch (err) { setError("Erreur lors de la génération."); }
    finally { setIsGenerating(false); setGenStage(''); }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] py-12 px-4 sm:px-6 lg:px-8 font-['Inter']">
