        <div className="text-center mb-10 animate-fadeIn">
          <h1 className="text-4xl font-black text-slate-900 tracking-tight">VoxGen <span className="text-indigo-600">STUDIO PRO</span></h1>
          <p className="text-slate-500 font-medium mt-2">Synthèse vocale et Post-production intelligente.</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Workspace */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 p-8 relative overflow-hidden">
              {/* Overlays */}
              {(isGenerating || isFixingAudio) && (
                <div className="absolute inset-0 z-50 bg-white/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <LoadingSpinner className="h-12 w-12 text-indigo-600 mb-4" />
                  <h3 className="text-xl font-bold text-slate-900">{genStage}</h3>
                  <div className="w-48 h-1.5 bg-slate-100 rounded-full mt-6 overflow-hidden">
                    <div className="h-full bg-indigo-600 animate-progress"></div>
                  </div>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-3">
                  <span className="text-xs font-black uppercase tracking-widest text-slate-400">Script Narratif</span>
                  <div className={`px-2 py-0.5 rounded text-[10px] font-bold ${isOverLimit ? 'bg-red-50 text-red-500' : 'bg-slate-50 text-slate-500'}`}>
                    {charCount} / {MAX_CHARS}
                  </div>
                </div>
                <div className="flex gap-2">
                  <button onClick={handleEnhanceScript} className="p-2 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-100 transition-all flex items-center gap-2 text-xs font-bold">
                    <MagicIcon /> Optimiser
                  </button>
                  <button onClick={() => fileInputRef.current?.click()} className="p-2 hover:bg-slate-50 rounded-xl text-slate-400 transition-all"><UploadIcon /></button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                </div>
              </div>

              <textarea 
                className="w-full h-64 bg-slate-50/50 rounded-3xl border border-slate-100 p-8 text-lg font-medium outline-none focus:ring-4 focus:ring-indigo-100 transition-all resize-none"
                placeholder="Entrez votre texte ici..."
                value={text}
                onChange={(e) => setText(e.target.value)}
              />

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-8">
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Voix & Langue</label>
                    <button onClick={() => setIsAutoVoice(!isAutoVoice)} className={`px-3 py-1 rounded-full text-[10px] font-bold transition-all ${isAutoVoice ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-500'}`}>
                      IA Auto {isAutoVoice ? 'ON' : 'OFF'}
                    </button>
                  </div>
                  <div className={`grid grid-cols-2 gap-2 ${isAutoVoice ? 'opacity-50 pointer-events-none' : ''}`}>
                    <select value={language} onChange={(e) => setLanguage(e.target.value as Language)} className="bg-white border border-slate-200 rounded-xl p-3 text-sm font-bold">
                      {LANGS.map(l => <option key={l.id} value={l.id}>{l.flag} {l.label}</option>)}
                    </select>
                    <select value={voice} onChange={(e) => setVoice(e.target.value as VoiceName)} className="bg-white border border-slate-200 rounded-xl p-3 text-sm font-bold">
                      {VOICES.map(v => <option key={v.name} value={v.name}>{v.name}</option>)}
                    </select>
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-xs font-black text-slate-400 uppercase tracking-widest block">Contrôle Acoustique</label>
                  <div className="space-y-4 bg-slate-50 p-4 rounded-2xl border border-slate-100">
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>Vitesse</span> <span>{speed}x</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={speed} onChange={(e) => setSpeed(parseFloat(e.target.value))} className="w-full accent-indigo-600" />
                    <div className="flex justify-between text-[10px] font-bold text-slate-500"><span>Tonalité</span> <span>{pitch}</span></div>
                    <input type="range" min="0.5" max="2.0" step="0.1" value={pitch} onChange={(e) => setPitch(parseFloat(e.target.value))} className="w-full accent-indigo-600" />
                  </div>
                </div>
              </div>

              <button 
                onClick={handleGenerate} 
                disabled={!text.trim() || isGenerating}
                className="w-full bg-indigo-600 text-white py-5 rounded-3xl mt-8 font-black text-xl shadow-lg hover:bg-indigo-700 hover:-translate-y-1 transition-all disabled:bg-slate-200"
              >
                GÉNÉRER LA NARRATION
              </button>
            </div>

            {audioResult && (
              <div className="bg-white rounded-[2.5rem] border-4 border-indigo-100 p-8 shadow-xl animate-slideUp">
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-4">
                    <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg"><AudioIcon /></div>
                    <div>
                      <h4 className="font-black text-slate-900 leading-none">Master Rendu</h4>
                      <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-widest">{voice} • {detectedStyle || 'Manuel'}</p>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button 
                      onClick={handleFixAudioRhythm}
