const WaveIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M2 10c.5 0 1 .5 1.5 1s1 .5 1.5.5 1-.5 1.5-1 1-.5 1.5-.5 1 .5 1.5 1 1 .5 1.5.5 1-.5 1.5-1 1-.5 1.5-.5 1 .5 1.5 1 1 .5 1.5.5 1-.5 1.5-1 1-.5 1.5-.5 1 .5 1.5 1 1 .5 1.5.5 1-.5 1.5-1 1-.5 1.5-.5 1 .5 1.5 1"/></svg>;
const SettingsIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>;

const VOICES_DB: VoiceMetadata[] = [
  { id: 'Charon', label: 'Léa - Narratrice Tech', tags: ['Documentaire', 'Tech', 'Sérieux'], description: 'Voix profonde et posée, idéale pour les narrations techniques.', previewText: 'Bienvenue dans ce module sur les infrastructures cloud.' },
  { id: 'Kore', label: 'Marc - Coach Corporate', tags: ['Formation', 'Business', 'News'], description: 'Direct et professionnel, parfait pour les messages d\'entreprise.', previewText: 'Nous allons voir ensemble les objectifs du trimestre.' },
  { id: 'Puck', label: 'Chloé - Voix Énergique', tags: ['E-learning', 'Jeune', 'Pub'], description: 'Dynamique et pétillante, capte l\'attention immédiatement.', previewText: 'Salut ! Prêt pour une nouvelle aventure d\'apprentissage ?' },
  { id: 'Fenrir', label: 'Paul - Conteur Chaleureux', tags: ['Formation', 'Narration', 'Podcast'], description: 'Chaleureux et rassurant, idéal pour les contenus longs.', previewText: 'Il était une fois une nouvelle méthode de management.' },
  { id: 'Zephyr', label: 'Sophie - Voix Zen', tags: ['Méditation', 'E-learning', 'Doux'], description: 'Poétique et calme, parfaite pour les sujets apaisants.', previewText: 'Prenez une grande inspiration et concentrez-vous.' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const App: React.FC = () => {
  // --- States ---
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [selectedVoiceId, setSelectedVoiceId] = useState<VoiceName>('Fenrir');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isEnhancing, setIsEnhancing] = useState<boolean>(false);
  const [isFixingAudio, setIsFixingAudio] = useState<boolean>(false);
  const [genStage, setGenStage] = useState<string>('');
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isAutoVoice, setIsAutoVoice] = useState<boolean>(true);
  const [detectedStyle, setDetectedStyle] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [activeFilter, setActiveFilter] = useState('All');

  // Acoustic Controls
  const [acousticConfig, setAcousticConfig] = useState<AcousticConfig>({
    speed: 1.0,
    pitch: 1.0,
    volume: 1.0,
    prosody: 'Neutral',
    pauseDuration: 1.0,
    diction: 0.5,
    roomReverb: 'None'
  });

  const [history, setHistory] = useState<HistoryItem[]>([]);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Filtering ---
  const filteredVoices = useMemo(() => {
    return VOICES_DB.filter(v => {
      const matchesSearch = v.label.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           v.tags.some(t => t.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesFilter = activeFilter === 'All' || v.tags.includes(activeFilter);
      return matchesSearch && matchesFilter;
    });
  }, [searchTerm, activeFilter]);

  const allTags = useMemo(() => {
    const tags = new Set<string>(['All']);
    VOICES_DB.forEach(v => v.tags.forEach(t => tags.add(t)));
    return Array.from(tags);
  }, []);

  // --- Handlers ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt")) setText(await file.text());
      else if (fileName.endsWith(".docx")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf")) {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture du fichier."); }
  };

  const handleEnhanceScript = async () => {
    if (!text.trim() || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await enhanceScript(text);
      setText(enhanced);
    } catch (err) { setError("Erreur lors de l'optimisation."); }
    finally { setIsEnhancing(false); }
  };

  const handleFixAudioRhythm = async () => {
    if (!audioResult) return;
    setIsFixingAudio(true);
    setGenStage('Analyse Post-Production...');
    await new Promise(r => setTimeout(r, 1000));
    setGenStage('Application du Time-Stretching Pro...');
    await new Promise(r => setTimeout(r, 1000));
    try {
      const stableConfig = { ...acousticConfig, speed: 1.0, diction: 1.0 };
      const result = await generateSpeech(text, language, selectedVoiceId, stableConfig);
      setAudioResult(result);
    } catch (err) { setError("Erreur de stabilisation."); }
    finally { setIsFixingAudio(false); setGenStage(''); }
  };

  const handleGenerate = async () => {
    if (!text.trim() || text.length > MAX_CHARS) return;
    setIsGenerating(true);
    setError(null);
    try {
      if (isAutoVoice) {
        setGenStage('Analyse de l\'IA...');
        const analysis = await analyzeContent(text);
        setSelectedVoiceId(analysis.recommendedVoice);
        setLanguage(analysis.language);
        setDetectedStyle(analysis.style);
      }
      setGenStage('Rendu Audio Haute Fidélité...');
      const result = await generateSpeech(text, language, selectedVoiceId, acousticConfig);
      setAudioResult(result);

      const newHistory: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        text: text.substring(0, 50),
        language,
        voice: selectedVoiceId,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistory, ...prev].slice(0, 10));
    } catch (err) { setError("Erreur de génération."); }
    finally { setIsGenerating(false); setGenStage(''); }
  };

  const handleVoicePreview = async (e: React.MouseEvent, voice: VoiceMetadata) => {
    e.stopPropagation();
    try {
      const res = await generateSpeech(voice.previewText, language, voice.id, acousticConfig);
      const audio = new Audio(res.url);
      audio.play();
    } catch (err) { console.error("Preview failed"); }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] text-slate-800 font-['Inter'] flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-100 py-6 px-10 flex justify-between items-center sticky top-0 z-30 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-2.5 rounded-2xl shadow-lg shadow-indigo-200">
            <WaveIcon />
          </div>
          <div>
            <h1 className="text-2xl font-black tracking-tight leading-none">VoxGen <span className="text-indigo-600">STUDIO PRO</span></h1>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Plateforme de Post-Production Vocale IA</p>
          </div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold hover:bg-slate-100 transition-all text-slate-600">
            <UploadIcon /> Importer Script
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl text-xs font-bold hover:bg-indigo-700 transition-all shadow-md">
            Sauvegarder Projet
          </button>
        </div>
      </header>

      {/* Main Layout */}
      <main className="flex-1 flex overflow-hidden">
        {/* Left Column: Script Editor */}
        <section className="w-1/3 flex flex-col border-r border-slate-100 bg-white">
          <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
            <h3 className="text-xs font-black uppercase tracking-widest text-slate-400">1. Éditeur de Script</h3>
            <button onClick={handleEnhanceScript} disabled={isEnhancing || !text.trim()} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${isEnhancing ? 'bg-indigo-100 text-indigo-600' : 'bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white'}`}>
              {isEnhancing ? <LoadingSpinner className="w-3 h-3 text-indigo-600" /> : <MagicIcon />} OPTIMISER IA
            </button>
          </div>
          <div className="flex-1 p-6 relative">
            <textarea 
              className="w-full h-full p-6 text-lg font-medium bg-slate-50/50 rounded-2xl border-none focus:ring-4 focus:ring-indigo-100 transition-all resize-none leading-relaxed placeholder:text-slate-300"
              placeholder="Collez votre contenu ici. Utilisez [pause] pour un silence ou [breath] pour une inspiration..."
              value={text}
              onChange={(e) => setText(e.target.value)}
            />
            <div className="absolute bottom-10 right-10 flex flex-col items-end">
              <span className={`text-[10px] font-black px-2 py-1 rounded-full ${text.length > MAX_CHARS ? 'bg-red-50 text-red-500 animate-pulse' : 'bg-indigo-50 text-indigo-400'}`}>
                {text.length.toLocaleString()} / {MAX_CHARS.toLocaleString()} CARACTÈRES
              </span>
            </div>
          </div>
        </section>

        {/* Center Column: Voice Catalog */}
        <section className="flex-1 flex flex-col bg-[#FDFDFF] border-r border-slate-100">
          <div className="p-6 border-b border-slate-50 bg-white flex flex-col gap-4">
            <div className="flex justify-between items-center">
              <h3 className="text-xs font-black uppercase tracking-widest text-slate-400">2. Catalogue de Voix</h3>
              <div className="flex gap-2">
                <button onClick={() => setIsAutoVoice(!isAutoVoice)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${isAutoVoice ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-500'}`}>
                  SÉLECTION IA {isAutoVoice ? 'ACTIVE' : 'OFF'}
                </button>
              </div>
            </div>

            <div className="flex gap-4">
              <div className="flex-1 relative">
                <div className="absolute inset-y-0 left-4 flex items-center text-slate-300"><SearchIcon /></div>
                <input 
                  type="text" 
                  placeholder="Rechercher une voix (ex: Formation, Tech...)" 
                  className="w-full pl-10 pr-4 py-2 bg-slate-50 rounded-xl border border-slate-100 text-sm font-medium focus:ring-2 focus:ring-indigo-100 outline-none transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
              <div className="flex-1 flex gap-2 overflow-x-auto pb-1 no-scrollbar">
                {allTags.map(tag => (
                  <button 
                    key={tag} 
                    onClick={() => setActiveFilter(tag)}
                    className={`px-3 py-1.5 rounded-lg text-[10px] font-black whitespace-nowrap transition-all ${activeFilter === tag ? 'bg-indigo-50 text-indigo-600 border border-indigo-100' : 'bg-white text-slate-400 border border-slate-100 hover:border-indigo-200'}`}
                  >
                    {tag.toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
            {filteredVoices.map(voice => (
              <div 
                key={voice.id} 
                onClick={() => { setSelectedVoiceId(voice.id); setIsAutoVoice(false); }}
                className={`p-5 rounded-2xl border-2 transition-all cursor-pointer group ${selectedVoiceId === voice.id ? 'bg-indigo-50 border-indigo-600 shadow-xl shadow-indigo-100/30' : 'bg-white border-slate-100 hover:border-indigo-200 shadow-sm'}`}
              >
                <div className="flex justify-between items-start mb-3">
                  <div className="flex items-center gap-3">
                    <div className={`p-3 rounded-xl transition-all ${selectedVoiceId === voice.id ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-indigo-50 group-hover:text-indigo-600'}`}>
                      <AudioIcon />
                    </div>
                    <div>
                      <h4 className={`font-black text-sm ${selectedVoiceId === voice.id ? 'text-indigo-900' : 'text-slate-900'}`}>{voice.label}</h4>
                      <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-tight">{voice.description}</p>
                    </div>
                  </div>
                  <button 
                    onClick={(e) => handleVoicePreview(e, voice)}
                    className="p-2 bg-slate-100 text-slate-500 rounded-lg hover:bg-indigo-600 hover:text-white transition-all transform hover:scale-110"
                  >
                    <PlayIcon className="w-3 h-3" />
                  </button>
                </div>
                <div className="flex flex-wrap gap-1.5 mt-2">
                  {voice.tags.map(tag => (
                    <span key={tag} className={`text-[8px] px-2 py-0.5 rounded-full font-black tracking-widest uppercase ${selectedVoiceId === voice.id ? 'bg-indigo-200 text-indigo-800' : 'bg-slate-50 text-slate-400'}`}>
                      {tag}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Right Column: Advanced Controls */}
        <section className="w-1/4 flex flex-col bg-white overflow-y-auto custom-scrollbar">
          <div className="p-6 border-b border-slate-50 bg-slate-50/30 flex justify-between items-center">
            <h3 className="text-xs font-black uppercase tracking-widest text-slate-400">3. Acoustique & Post-Prod</h3>
            <SettingsIcon />
          </div>

          <div className="p-8 space-y-8">
            {/* Tone & Style */}
            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Style de Prosodie</label>
              <div className="grid grid-cols-2 gap-2">
                {(['Neutral', 'Educational', 'Corporate', 'Narrative', 'Energetic'] as ProsodyStyle[]).map(style => (
                  <button 
                    key={style}
                    onClick={() => setAcousticConfig({...acousticConfig, prosody: style})}
                    className={`px-3 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${acousticConfig.prosody === style ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white border-slate-100 text-slate-600 hover:border-indigo-100'}`}
                  >
                    {style}
                  </button>
                ))}
              </div>
            </div>

            {/* Sliders */}
            <div className="space-y-6">
              {[
                { label: 'Vitesse de Lecture', key: 'speed', min: 0.5, max: 2.0, step: 0.1, unit: 'x' },
                { label: 'Hauteur de Voix (Pitch)', key: 'pitch', min: 0.5, max: 2.0, step: 0.1, unit: '' },
                { label: 'Volume Global', key: 'volume', min: 0.5, max: 2.0, step: 0.1, unit: '' },
                { label: 'Durée des Pauses', key: 'pauseDuration', min: 0.5, max: 2.5, step: 0.1, unit: 'x' },
                { label: 'Clarté de Diction', key: 'diction', min: 0, max: 1.0, step: 0.1, unit: '' }
              ].map(ctrl => (
                <div key={ctrl.key} className="space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">{ctrl.label}</span>
                    <span className="text-indigo-600 font-black text-[11px]">{(acousticConfig as any)[ctrl.key]}{ctrl.unit}</span>
                  </div>
                  <input 
                    type="range" 
                    min={ctrl.min} max={ctrl.max} step={ctrl.step} 
                    value={(acousticConfig as any)[ctrl.key]}
                    onChange={(e) => setAcousticConfig({...acousticConfig, [ctrl.key]: parseFloat(e.target.value)})}
                    className="w-full h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                  />
                </div>
              ))}
            </div>

            {/* Room Reverb */}
            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Acoustique de la Pièce</label>
              <select 
                value={acousticConfig.roomReverb}
                onChange={(e) => setAcousticConfig({...acousticConfig, roomReverb: e.target.value as any})}
                className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold focus:ring-2 focus:ring-indigo-100 outline-none"
              >
                <option value="None">Studio Sec (Aucun)</option>
                <option value="SmallRoom">Petite Pièce</option>
                <option value="Studio">Studio Professionnel</option>
                <option value="LargeHall">Grand Auditorium</option>
              </select>
            </div>

            {/* Language Selection */}
            <div className="space-y-4 pt-4 border-t border-slate-50">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Langue Source</label>
              <div className="grid grid-cols-3 gap-2">
                {LANGS.map(l => (
                  <button key={l.id} onClick={() => { setLanguage(l.id); setIsAutoVoice(false); }} className={`py-2 px-1 rounded-xl text-[10px] font-bold border-2 transition-all ${language === l.id ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-50 text-slate-400'}`}>
                    {l.flag} {l.id.substring(0, 3).toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </section>
      </main>

      {/* Footer / Master Controls */}
      <footer className="bg-white border-t border-slate-100 p-8 shadow-[0_-10px_30px_rgba(0,0,0,0.03)] z-30">
        <div className="max-w-7xl mx-auto flex items-center gap-10">
          <div className="flex-1">
            {audioResult ? (
              <div className="bg-slate-50 rounded-[2rem] p-6 border-2 border-indigo-100 flex items-center gap-6 animate-slideUp">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg"><AudioIcon /></div>
                <div className="flex-1">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-[10px] font-black text-indigo-600 tracking-widest uppercase">MASTER RENDU - {selectedVoiceId}</span>
                    <div className="flex gap-2">
                      <button onClick={handleFixAudioRhythm} className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 text-emerald-600 rounded-lg text-[9px] font-black hover:bg-emerald-600 hover:text-white transition-all uppercase tracking-tighter">
                        <WaveIcon /> Fixer Rythme
                      </button>
                      <button 
                        onClick={async () => {
                          const mp3 = convertPcmToMp3(audioResult.pcmData);
                          const a = document.createElement('a');
                          a.href = URL.createObjectURL(mp3);
                          a.download = `voxgen-${Date.now()}.mp3`;
                          a.click();
                        }}
                        className="flex items-center gap-1.5 px-3 py-1 bg-indigo-600 text-white rounded-lg text-[9px] font-black hover:bg-indigo-700 transition-all uppercase"
                      >
                        <DownloadIcon /> Export MP3
                      </button>
                      <button onClick={() => setAudioResult(null)} className="text-slate-300 hover:text-red-500"><TrashIcon size={18} /></button>
                    </div>
                  </div>
                  <audio ref={audioRef} controls src={audioResult.url} className="w-full h-10 rounded-full" />
                </div>
              </div>
            ) : (
              <div className="bg-slate-50/50 rounded-[2rem] p-8 border-2 border-dashed border-slate-100 flex items-center justify-center">
                <p className="text-slate-400 text-xs font-bold italic tracking-wide">Prêt pour le rendu final...</p>
              </div>
            )}
          </div>

          <div className="w-72 space-y-3">
             <button 
                onClick={handleGenerate} 
                disabled={!text.trim() || isGenerating || text.length > MAX_CHARS}
                className={`w-full py-5 rounded-3xl font-black text-lg shadow-2xl transition-all relative overflow-hidden group ${isGenerating ? 'bg-slate-200 text-slate-400' : 'bg-indigo-600 text-white hover:bg-indigo-700 hover:-translate-y-1'}`}
              >
                {isGenerating ? (
                  <div className="flex items-center justify-center gap-3">
                    <LoadingSpinner className="h-5 w-5 text-indigo-600" /> 
                    <span className="text-indigo-600">{genStage.toUpperCase()}</span>
                  </div>
                ) : (
                  <span className="relative z-10 flex items-center justify-center gap-2">
                    GÉNÉRER MASTER <PlayIcon className="w-5 h-5" />
                  </span>
                )}
                {!isGenerating && <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>}
              </button>
              {error && <p className="text-[10px] text-red-500 font-bold text-center">{error}</p>}
          </div>
        </div>
      </footer>

      {/* Overlays & Animations */}
      <style>{`
        @keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
