            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></span>
              <h3 className="text-[10px] font-black uppercase tracking-[0.15em] text-slate-400">01. SCRIPT NARRATIF</h3>
            </div>
            <div className="flex gap-2">
              <button 
                onClick={() => setText('')} 
                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                title="Tout effacer"
              >
                <EraserIcon />
              </button>
              <button 
                onClick={handleEnhanceScript} 
                disabled={isEnhancing || !text.trim()} 
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black transition-all shadow-sm ${isEnhancing ? 'bg-indigo-100 text-indigo-600' : 'bg-white border border-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white'}`}
              >
                {isEnhancing ? <LoadingSpinner className="w-3 h-3 text-indigo-600" /> : <MagicIcon />} OPTIMISATION IA
              </button>
            </div>
          </div>

          <div className="flex-1 flex overflow-hidden relative group">
            {/* Gutter for Line Numbers */}
            <div 
