              placeholder="Commencez à rédiger ou collez votre script ici...&#10;&#10;Astuce : utilisez [pause] pour un silence marqué."
              value={text}
              onChange={(e) => setText(e.target.value)}
              spellCheck={false}
            />

            {/* Floating Stats Indicator */}
            <div className="absolute bottom-6 right-6 flex items-center gap-3">
              <div className="flex flex-col items-end">
                 {detectedStyle && (
                  <span className="text-[8px] font-black text-indigo-400 bg-indigo-50 px-2 py-0.5 rounded-full mb-1 uppercase tracking-widest">
                    Style : {detectedStyle}
                  </span>
                )}
                <span className={`text-[10px] font-black px-3 py-1.5 rounded-xl shadow-lg border backdrop-blur-md transition-all ${text.length > MAX_CHARS ? 'bg-red-50 text-red-500 border-red-100 animate-shake' : 'bg-white/90 text-slate-500 border-slate-100'}`}>
                  {text.length.toLocaleString()} <span className="text-slate-300">/ {MAX_CHARS.toLocaleString()}</span>
                </span>
              </div>
            </div>
          </div>
        </section>

        {/* Center Column: Voice Catalog */}
        <section className="flex-1 flex flex-col bg-[#FDFDFF] border-r border-slate-100">
          <div className="p-6 border-b border-slate-50 bg-white flex flex-col gap-4">
            <div className="flex justify-between items-center">
              <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400">02. CATALOGUE DES VOIX</h3>
              <div className="flex gap-2">
                <button onClick={() => setIsAutoVoice(!isAutoVoice)} className={`px-3 py-1.5 rounded-lg text-[9px] font-black transition-all ${isAutoVoice ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                  IA AUTO {isAutoVoice ? 'ON' : 'OFF'}
                </button>
              </div>
            </div>

            <div className="flex gap-3">
              <div className="flex-1 relative">
                <div className="absolute inset-y-0 left-3.5 flex items-center text-slate-300"><SearchIcon /></div>
                <input 
                  type="text" 
                  placeholder="Recherche (ex: Formation, Tech...)" 
                  className="w-full pl-10 pr-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 text-[13px] font-medium focus:bg-white focus:ring-2 focus:ring-indigo-100 outline-none transition-all placeholder:text-slate-300"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>
            <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
              {allTags.map(tag => (
                <button 
