                  <button 
                    key={style}
                    onClick={() => setAcousticConfig({...acousticConfig, prosody: style})}
                    className={`px-3 py-2 rounded-lg text-[10px] font-bold border-2 text-left transition-all ${acousticConfig.prosody === style ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white border-slate-50 text-slate-500 hover:border-indigo-100'}`}
                  >
                    {style}
                  </button>
                ))}
