              </div>
            </div>
          </div>
        </section>
      </main>

      {/* Footer / Master Controls */}
      <footer className="bg-white border-t border-slate-100 p-6 shadow-[0_-10px_30px_rgba(0,0,0,0.03)] z-30">
        <div className="max-w-7xl mx-auto flex items-center gap-10">
          <div className="flex-1">
            {audioResult ? (
              <div className="bg-slate-50 rounded-2xl p-5 border-2 border-indigo-100 flex items-center gap-6 animate-slideUp">
                <div className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg"><AudioIcon /></div>
                <div className="flex-1">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-[9px] font-black text-indigo-600 tracking-widest uppercase">MASTER : {selectedVoiceId} • WAV 48KHZ</span>
                    <div className="flex gap-2">
                      <button onClick={handleFixAudioRhythm} className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 text-emerald-600 rounded-md text-[9px] font-black hover:bg-emerald-600 hover:text-white transition-all uppercase tracking-tighter">
                        <WaveIcon /> FIX RYTHME
                      </button>
                      <button 
                        onClick={async () => {
                          const mp3 = convertPcmToMp3(audioResult.pcmData);
                          const a = document.createElement('a');
                          a.href = URL.createObjectURL(mp3);
                          a.download = `voxgen-${Date.now()}.mp3`;
                          a.click();
                        }}
                        className="flex items-center gap-1.5 px-3 py-1 bg-indigo-600 text-white rounded-md text-[9px] font-black hover:bg-indigo-700 transition-all uppercase"
                      >
                        <DownloadIcon /> MP3
                      </button>
                      <button onClick={() => setAudioResult(null)} className="text-slate-300 hover:text-red-500"><TrashIcon size={18} /></button>
                    </div>
                  </div>
                  <audio ref={audioRef} controls src={audioResult.url} className="w-full h-8 rounded-full" />
                </div>
              </div>
            ) : (
              <div className="bg-slate-50/40 rounded-2xl p-6 border-2 border-dashed border-slate-100 flex items-center justify-center">
                <p className="text-slate-300 text-[11px] font-black italic tracking-widest uppercase">Prêt pour le rendu final du master studio</p>
              </div>
            )}
          </div>

          <div className="w-72 space-y-2">
             <button 
                onClick={handleGenerate} 
                disabled={!text.trim() || isGenerating || text.length > MAX_CHARS}
                className={`w-full py-4 rounded-2xl font-black text-sm shadow-xl transition-all relative overflow-hidden group ${isGenerating ? 'bg-slate-200 text-slate-400' : 'bg-indigo-600 text-white hover:bg-indigo-700 hover:-translate-y-1'}`}
              >
                {isGenerating ? (
                  <div className="flex items-center justify-center gap-3">
                    <LoadingSpinner className="h-4 w-4 text-indigo-600" /> 
                    <span className="text-indigo-600 font-bold uppercase text-[10px] tracking-widest">{genStage}</span>
                  </div>
                ) : (
                  <span className="relative z-10 flex items-center justify-center gap-2 tracking-widest">
                    GÉNÉRER MASTER <PlayIcon className="w-4 h-4" />
                  </span>
                )}
                {!isGenerating && <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>}
              </button>
              {error && <p className="text-[9px] text-red-500 font-bold text-center uppercase tracking-tighter">{error}</p>}
          </div>
        </div>
      </footer>

      {/* Overlays & Animations */}
      <style>{`
        @keyframes slideUp { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
        .animate-slideUp { animation: slideUp 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .animate-shake { animation: shake 0.3s ease-in-out; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #eef2f6; border-radius: 10px; }
        @keyframes progress { 0% { width: 0%; } 50% { width: 70%; } 100% { width: 100%; } }
        .animate-progress { animation: progress 3s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default App;

