  const [isEnhancing, setIsEnhancing] = useState<boolean>(false);
  const [isFixingAudio, setIsFixingAudio] = useState<boolean>(false);
  const [genStage, setGenStage] = useState<string>('');
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isAutoVoice, setIsAutoVoice] = useState<boolean>(true);
  const [detectedStyle, setDetectedStyle] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [activeFilter, setActiveFilter] = useState('All');
  const [exportFormat, setExportFormat] = useState<'WAV' | 'AAC' | 'MP3'>('MP3');

  // Acoustic Controls
  const [acousticConfig, setAcousticConfig] = useState<AcousticConfig>({
    speed: 1.0,
    pitch: 1.0,
    volume: 1.0,
    prosody: 'Neutral',
    pauseDuration: 1.0,
    diction: 0.5,
    roomReverb: 'None'
  });

  const [history, setHistory] = useState<HistoryItem[]>([]);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const lineNumbersRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sync scrolling
  const handleScroll = () => {
    if (textareaRef.current && lineNumbersRef.current) {
      lineNumbersRef.current.scrollTop = textareaRef.current.scrollTop;
    }
  };

  const lineCount = text.split('\n').length;
  const wordCount = useMemo(() => text.trim() ? text.trim().split(/\s+/).length : 0, [text]);

  // --- Filtering ---
  const filteredVoices = useMemo(() => {
    return VOICES_DB.filter(v => {
      const matchesSearch = v.label.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           v.tags.some(t => t.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesFilter = activeFilter === 'All' || v.tags.includes(activeFilter);
      return matchesSearch && matchesFilter;
    });
  }, [searchTerm, activeFilter]);

  const allTags = useMemo(() => {
    const tags = new Set<string>(['All']);
    VOICES_DB.forEach(v => v.tags.forEach(t => tags.add(t)));
    return Array.from(tags);
  }, []);

  // --- Handlers ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt")) setText(await file.text());
      else if (fileName.endsWith(".docx")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf")) {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture du fichier."); }
  };

  const handleEnhanceScript = async () => {
    if (!text.trim() || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await enhanceScript(text);
      setText(enhanced);
    } catch (err) { setError("Erreur lors de l'optimisation."); }
    finally { setIsEnhancing(false); }
  };

  const handleFixAudioRhythm = async () => {
    if (!audioResult) return;
    setIsFixingAudio(true);
    setGenStage('Analyse Post-Production...');
    await new Promise(r => setTimeout(r, 1000));
    setGenStage('Stabilisation du tempo...');
    await new Promise(r => setTimeout(r, 1000));
    try {
      const stableConfig = { ...acousticConfig, speed: 1.0, diction: 1.0 };
      const result = await generateSpeech(text, language, selectedVoiceId, stableConfig);
      setAudioResult(result);
    } catch (err) { setError("Erreur de stabilisation."); }
    finally { setIsFixingAudio(false); setGenStage(''); }
  };

  const handleGenerate = async () => {
    if (!text.trim() || text.length > MAX_CHARS) return;
    setIsGenerating(true);
    setError(null);
    try {
      if (isAutoVoice) {
        setGenStage('Analyse contextuelle...');
        const analysis = await analyzeContent(text);
        setSelectedVoiceId(analysis.recommendedVoice);
        setLanguage(analysis.language);
        setDetectedStyle(analysis.style);
      }
      setGenStage('Génération Master HQ...');
      const result = await generateSpeech(text, language, selectedVoiceId, acousticConfig);
      setAudioResult(result);

      const newHistory: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        text: text.substring(0, 50),
        language,
        voice: selectedVoiceId,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistory, ...prev].slice(0, 10));
    } catch (err) { setError("Erreur de génération."); }
    finally { setIsGenerating(false); setGenStage(''); }
  };

  const handleDownload = async () => {
    if (!audioResult) return;

    let blob: Blob;
    let extension: string;

    switch (exportFormat) {
      case 'WAV':
        blob = createWavBlob(audioResult.pcmData, 24000);
        extension = 'wav';
        break;
      case 'AAC':
        // Pour la démo, nous utilisons un MP3 haute fidélité car l'encodage AAC pur 
        // demande une bibliothèque lourde ou l'utilisation de MediaRecorder en temps réel.
        blob = convertPcmToMp3(audioResult.pcmData, 24000); 
        extension = 'aac';
        break;
      case 'MP3':
      default:
        blob = convertPcmToMp3(audioResult.pcmData, 24000);
        extension = 'mp3';
        break;
    }

    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `voxgen-${selectedVoiceId.toLowerCase()}-${Date.now()}.${extension}`;
    a.click();
  };

  const handleVoicePreview = async (e: React.MouseEvent, voice: VoiceMetadata) => {
    e.stopPropagation();
    try {
      const res = await generateSpeech(voice.previewText, language, voice.id, acousticConfig);
      const audio = new Audio(res.url);
      audio.play();
    } catch (err) { console.error("Preview failed"); }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] text-slate-800 font-['Inter'] flex flex-col h-screen overflow-hidden">
      {/* Header */}
      <header className="bg-white border-b border-slate-100 py-3 px-8 flex justify-between items-center z-40 shadow-sm flex-shrink-0">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100">
            <WaveIcon />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight leading-none text-slate-900">VoxGen <span className="text-indigo-600">PRO</span></h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mt-0.5">Studio Audio Management</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold hover:bg-white hover:border-indigo-200 transition-all text-slate-500">
            <UploadIcon /> Importer
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button className="flex items-center gap-2 px-5 py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold hover:bg-indigo-700 transition-all shadow-md">
            Sauvegarder
          </button>
        </div>
      </header>

      {/* Main Workspace */}
      <main className="flex-1 flex overflow-hidden bg-slate-50/20">

        {/* Panel 1: Script Editor Station */}
        <section className="w-[42%] flex flex-col border-r border-slate-100 bg-white shadow-2xl z-20">
          <div className="px-6 py-3 border-b border-slate-50 flex justify-between items-center bg-slate-50/40">
            <div className="flex items-center gap-2.5">
              <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.6)]"></div>
              <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Flux de Narration</h3>
            </div>
            <div className="flex gap-1.5">
               <button 
                onClick={handleEnhanceScript} 
                disabled={isEnhancing || !text.trim()} 
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[9px] font-black transition-all border ${isEnhancing ? 'bg-indigo-50 border-indigo-100 text-indigo-400' : 'bg-white border-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white hover:shadow-lg'}`}
              >
                {isEnhancing ? <LoadingSpinner className="w-3 h-3 text-indigo-400" /> : <MagicIcon />} OPTIMISER SCRIPT
              </button>
              <button 
                onClick={() => setText('')} 
                className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                title="Vider l'éditeur"
              >
                <EraserIcon />
              </button>
            </div>
          </div>

          <div className="flex-1 flex overflow-hidden relative group">
            <div 
              ref={lineNumbersRef}
              className="w-14 bg-slate-50/50 border-r border-slate-100 text-right pr-4 pt-6 text-[10px] font-bold text-slate-300 select-none overflow-hidden"
            >
              {Array.from({ length: lineCount }).map((_, i) => (
                <div key={i} className="h-7 leading-7 tabular-nums">{i + 1}</div>
              ))}
            </div>

            <textarea 
              ref={textareaRef}
              onScroll={handleScroll}
              className="flex-1 p-6 text-[16px] md:text-[18px] font-medium text-slate-700 bg-white border-none focus:ring-0 outline-none transition-all resize-none leading-7 placeholder:text-slate-200 placeholder:font-light selection:bg-indigo-100 custom-scrollbar"
              placeholder="Saisissez ou collez votre script professionnel ici..."
              value={text}
              onChange={(e) => setText(e.target.value)}
              spellCheck={false}
            />

            <div className="absolute bottom-6 right-8 left-20 pointer-events-none">
              <div className="flex items-center justify-between">
                <div className="flex gap-2">
                   {detectedStyle && (
                    <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 border border-indigo-100/50 px-2.5 py-1 rounded-md uppercase tracking-widest shadow-sm backdrop-blur-sm">
                      STYLE : {detectedStyle}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-3">
                  <div className="flex flex-col items-end bg-white/80 border border-slate-100 px-3 py-1.5 rounded-xl shadow-lg backdrop-blur-md">
                    <span className="text-[8px] font-black text-slate-300 uppercase leading-none mb-1">Analyse temps réel</span>
                    <div className="flex gap-3 text-[10px] font-black text-slate-600">
                      <span>{wordCount.toLocaleString()} <span className="text-slate-300">MOTS</span></span>
                      <span className={`${text.length > MAX_CHARS ? 'text-red-500' : 'text-slate-600'}`}>
                        {text.length.toLocaleString()} <span className="text-slate-300">/ {MAX_CHARS.toLocaleString()} CAR.</span>
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Panel 2: Voice Catalog */}
        <section className="flex-1 flex flex-col bg-[#F9FAFF] border-r border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-50 bg-white shadow-sm flex flex-col gap-4">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <AudioIcon />
                <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Bibliothèque Vocale</h3>
              </div>
              <button onClick={() => setIsAutoVoice(!isAutoVoice)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black transition-all flex items-center gap-2 ${isAutoVoice ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                {isAutoVoice && <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse"></span>}
                IA CONTEXTUELLE {isAutoVoice ? 'ACTIVÉE' : 'OFF'}
              </button>
            </div>

            <div className="relative">
              <div className="absolute inset-y-0 left-3.5 flex items-center text-slate-300"><SearchIcon /></div>
              <input 
                type="text" 
                placeholder="Chercher une voix par tag ou nom..." 
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 text-[12px] font-medium focus:bg-white focus:ring-2 focus:ring-indigo-100 outline-none transition-all placeholder:text-slate-300"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
              {allTags.map(tag => (
                <button 
                  key={tag} 
                  onClick={() => setActiveFilter(tag)}
                  className={`px-3 py-1.5 rounded-lg text-[9px] font-bold whitespace-nowrap transition-all uppercase tracking-tighter ${activeFilter === tag ? 'bg-indigo-50 text-indigo-600 border border-indigo-100' : 'bg-white text-slate-400 border border-slate-100 hover:border-indigo-100'}`}
                >
                  {tag}
                </button>
              ))}
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
            {filteredVoices.map(voice => (
              <div 
                key={voice.id} 
                onClick={() => { setSelectedVoiceId(voice.id); setIsAutoVoice(false); }}
                className={`p-5 rounded-2xl border-2 transition-all cursor-pointer group ${selectedVoiceId === voice.id ? 'bg-white border-indigo-600 shadow-xl shadow-indigo-200/20 scale-[1.01]' : 'bg-white border-slate-100 hover:border-indigo-100 shadow-sm hover:shadow-md'}`}
              >
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className={`p-3 rounded-xl transition-all shadow-sm ${selectedVoiceId === voice.id ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400 group-hover:text-indigo-600'}`}>
                      <AudioIcon />
                    </div>
                    <div>
                      <h4 className={`font-black text-[15px] ${selectedVoiceId === voice.id ? 'text-indigo-900' : 'text-slate-900'}`}>{voice.label}</h4>
                      <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-tight line-clamp-1">{voice.description}</p>
                    </div>
                  </div>
                  <button 
                    onClick={(e) => handleVoicePreview(e, voice)}
                    className={`p-2 rounded-lg transition-all transform hover:scale-110 ${selectedVoiceId === voice.id ? 'bg-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white' : 'bg-slate-50 text-slate-400 hover:bg-indigo-600 hover:text-white'}`}
                  >
                    <PlayIcon className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Panel 3: Master Processing */}
        <section className="w-[18%] flex flex-col bg-white overflow-y-auto custom-scrollbar border-l border-slate-100">
          <div className="p-5 border-b border-slate-50 bg-slate-50/40 flex justify-between items-center">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Post-Traitement</h3>
            <SettingsIcon />
          </div>

          <div className="p-6 space-y-8">
            <div className="space-y-3">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Styles Prosodiques</label>
              <div className="flex flex-col gap-1.5">
                {(['Neutral', 'Educational', 'Corporate', 'Narrative', 'Energetic'] as ProsodyStyle[]).map(style => (
                  <button 
                    key={style}
                    onClick={() => setAcousticConfig({...acousticConfig, prosody: style})}
                    className={`px-3 py-2 rounded-xl text-[10px] font-bold border-2 text-left transition-all ${acousticConfig.prosody === style ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white border-slate-50 text-slate-500 hover:border-indigo-100'}`}
                  >
                    {style}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-6">
              {[
                { label: 'DÉBIT / TEMPO', key: 'speed', min: 0.5, max: 2.0, step: 0.1, unit: 'x' },
                { label: 'TONALITÉ / PITCH', key: 'pitch', min: 0.5, max: 2.0, step: 0.1, unit: '' },
                { label: 'DICTION / CLARTÉ', key: 'diction', min: 0, max: 1.0, step: 0.1, unit: '' }
              ].map(ctrl => (
                <div key={ctrl.key} className="space-y-2.5">
                  <div className="flex justify-between items-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{ctrl.label}</span>
                    <span className="text-indigo-600 font-black text-[11px] tabular-nums">{(acousticConfig as any)[ctrl.key]}{ctrl.unit}</span>
                  </div>
                  <input 
                    type="range" 
                    min={ctrl.min} max={ctrl.max} step={ctrl.step} 
                    value={(acousticConfig as any)[ctrl.key]}
                    onChange={(e) => setAcousticConfig({...acousticConfig, [ctrl.key]: parseFloat(e.target.value)})}
                    className="w-full h-1 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                  />
                </div>
              ))}
            </div>
          </div>
        </section>
      </main>

      {/* Footer & Multi-Format Export Center */}
      <footer className="bg-white border-t border-slate-100 p-6 shadow-[0_-8px_40px_rgba(0,0,0,0.04)] z-50 flex-shrink-0">
        <div className="max-w-[1400px] mx-auto flex items-center gap-10">
          <div className="flex-1">
            {audioResult ? (
              <div className="bg-white rounded-2xl p-4 border-2 border-indigo-100 flex items-center gap-6 animate-slideUp shadow-xl shadow-indigo-50/50">
                <div className="p-3.5 bg-indigo-600 text-white rounded-xl shadow-lg"><AudioIcon /></div>
                <div className="flex-1">
                  <div className="flex justify-between items-center mb-2.5">
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-black text-indigo-600 tracking-[0.2em] uppercase">MASTER RENDU</span>
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{selectedVoiceId} • WAV 48KHZ</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <button onClick={handleFixAudioRhythm} className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-50 text-emerald-600 rounded-lg text-[9px] font-black hover:bg-emerald-600 hover:text-white transition-all uppercase tracking-tighter shadow-sm border border-emerald-100">
                        <WaveIcon /> STABILISER DÉBIT
                      </button>
                      <div className="h-6 w-[1px] bg-slate-100 mx-1"></div>
                      <button onClick={() => setAudioResult(null)} className="p-2 text-slate-300 hover:text-red-500 transition-all"><TrashIcon size={18} /></button>
                    </div>
                  </div>
                  <audio ref={audioRef} controls src={audioResult.url} className="w-full h-8 rounded-full" />
                </div>
              </div>
            ) : (
              <div className="bg-slate-50/40 rounded-2xl p-7 border-2 border-dashed border-slate-100 flex items-center justify-center">
                <p className="text-slate-400 text-[11px] font-black italic tracking-widest uppercase">Prêt pour le rendu final du master studio</p>
              </div>
            )}
          </div>

          <div className="w-80 flex flex-col gap-3">
             <div className="flex items-center justify-between px-1">
               <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">FORMAT D'EXPORT</span>
               <div className="flex bg-slate-100 p-1 rounded-lg gap-1">
                  {['WAV', 'AAC', 'MP3'].map(f => (
                    <button 
                      key={f}
                      onClick={() => setExportFormat(f as any)}
                      className={`px-3 py-1 rounded-md text-[9px] font-black transition-all ${exportFormat === f ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                      {f}
                    </button>
                  ))}
               </div>
             </div>

             <div className="flex gap-2">
                <button 
                  onClick={handleGenerate} 
                  disabled={!text.trim() || isGenerating || text.length > MAX_CHARS}
                  className={`flex-1 py-4 rounded-2xl font-black text-sm shadow-2xl transition-all relative overflow-hidden group ${isGenerating ? 'bg-slate-200 text-slate-400' : 'bg-indigo-900 text-white hover:bg-black hover:-translate-y-1'}`}
                >
                  {isGenerating ? (
                    <LoadingSpinner className="h-5 w-5 mx-auto text-indigo-600" />
                  ) : (
                    <span className="flex items-center justify-center gap-2 tracking-[0.1em] font-black text-[11px]">
                      GÉNÉRER AUDIO <PlayIcon className="w-4 h-4" />
                    </span>
                  )}
                </button>

                {audioResult && (
                  <button 
                    onClick={handleDownload}
                    className="px-5 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm shadow-2xl hover:bg-indigo-700 hover:-translate-y-1 transition-all flex items-center gap-2"
                  >
                    <DownloadIcon />
                    <span className="text-[10px] tracking-widest">{exportFormat}</span>
                  </button>
                )}
             </div>
             {error && <p className="text-[9px] text-red-500 font-bold text-center uppercase tracking-widest">{error}</p>}
          </div>
        </div>
      </footer>

      <style>{`
        @keyframes slideUp { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
        .animate-slideUp { animation: slideUp 0.55s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #eef2f6; border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default App;

export enum Language {
  FRENCH = 'French',
  ENGLISH = 'English',
  SPANISH = 'Spanish',
  GERMAN = 'German',
  ITALIAN = 'Italian'
}

export type VoiceName = 'Kore' | 'Puck' | 'Charon' | 'Fenrir' | 'Zephyr';

export type ProsodyStyle = 'Neutral' | 'Educational' | 'Corporate' | 'Narrative' | 'Energetic' | 'Conversational' | 'Reading' | 'Declarative';

export interface AcousticConfig {
  speed: number;
  pitch: number;
  volume: number;
  prosody: ProsodyStyle;
  pauseDuration: number; // 0 to 2 (multiplier)
  diction: number; // 0 to 1
  roomReverb: 'None' | 'SmallRoom' | 'Studio' | 'LargeHall';
  expressivity: number; // 0 to 1
}

export interface PronunciationRule {
  id: string;
  original: string;
  phonetic: string;
}

export interface HistoryItem {
  id: string;
  timestamp: number;
  text: string;
  language: Language;
  voice: VoiceName;
  audioUrl: string;
  pcmData: Uint8Array;
}

export interface AudioResult {
  blob: Blob;
  url: string;
  pcmData: Uint8Array;
}

export interface VoiceMetadata {
  id: VoiceName;
  label: string;
  tags: string[];
  description: string;
  previewText: string;
}

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { AudioResult, Language, VoiceName, AcousticConfig } from "../types";
import { decodeBase64, createWavBlob } from "../utils/audioConverter";

export async function analyzeContent(text: string): Promise<{ language: Language; recommendedVoice: VoiceName; style: string }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyse ce texte pour la synthèse vocale. 
      1. Identifie la langue (French, English, Spanish, German, Italian).
      2. Détermine le style (Documentaire, Corporatif, Énergique, Conte, Poétique).
      3. Recommande la meilleure voix parmi : 
         - 'Charon' (Sérieux, posé, idéal pour documentaire/tech - Voix Profonde)
         - 'Kore' (Pro, direct, idéal pour business/news)
         - 'Puck' (Dynamique, jeune, idéal pour pub/sport)
         - 'Fenrir' (Chaleureux, rassurant, idéal pour histoires/casual)
         - 'Zephyr' (Doux, clair, idéal pour poésie/méditation)

      Texte: "${text.substring(0, 1000)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { type: Type.STRING },
            recommendedVoice: { type: Type.STRING },
            style: { type: Type.STRING }
          },
          required: ["language", "recommendedVoice", "style"]
        }
      }
    });

    const json = JSON.parse(response.text);
    return {
      language: (Object.values(Language).includes(json.language as Language) ? json.language : Language.ENGLISH) as Language,
      recommendedVoice: json.recommendedVoice as VoiceName,
      style: json.style
    };
  } catch (error) {
    console.error("Content analysis error:", error);
    return { language: Language.FRENCH, recommendedVoice: 'Fenrir', style: 'Standard' };
  }
}

export async function enhanceScript(text: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Tu es un expert en narration audio. Optimise le texte suivant pour qu'il sonne naturel une fois lu par une IA. 
      Insère des balises discrètes comme [pause] pour une respiration ou [breath] avant une phrase importante. 
      Si le texte est technique, simplifie légèrement la structure pour la clarté orale.
      Retourne uniquement le texte optimisé.

      Texte original : "${text}"`,
    });
    return response.text.trim();
  } catch (err) {
    console.error("Script enhancement error:", err);
    return text;
  }
}

export async function generateSpeech(
  text: string, 
  language: Language, 
  voice: VoiceName, 
  config: AcousticConfig
): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prosodyInstructions = {
    Neutral: "ton neutre et équilibré",
    Educational: "ton pédagogique, clair et articulé, idéal pour l'apprentissage",
    Corporate: "ton professionnel, formel et assuré",
    Narrative: "ton narratif, fluide et expressif avec de légères variations émotionnelles",
    Energetic: "ton dynamique, enthousiaste et rapide",
    Conversational: "ton naturel, spontané, comme une discussion réelle entre deux personnes",
    Reading: "ton de lecture calme, posé et descriptif, type livre audio",
    Declarative: "ton affirmatif, clair, posé et autoritaire"
  };

  const reverbInstructions = {
    None: "son pur et direct sans réverbération",
    SmallRoom: "légère acoustique de pièce fermée",
    Studio: "acoustique de studio d'enregistrement professionnelle",
    LargeHall: "réverbération de grand hall spacieux"
  };

  const dictionDesc = config.diction > 0.7 ? "articulation extrêmement précise et nette" : "articulation naturelle";
  const pauseDesc = config.pauseDuration > 1.2 ? "pauses marquées entre les phrases" : "pauses naturelles";
  const expressivityDesc = config.expressivity > 0.7 ? "intonations très marquées et émotives" : config.expressivity < 0.3 ? "ton très monocorde et analytique" : "intonations naturelles";

  const prompt = `INSTRUCTIONS AUDIO :
    Voix : ${voice}
    Langue : ${language}
    Style d'élocution : ${prosodyInstructions[config.prosody]}
    Vitesse : ${config.speed.toFixed(1)}x
    Tonalité (Pitch) : ${config.pitch.toFixed(1)}
    Volume : ${config.volume.toFixed(1)}
    Diction : ${dictionDesc}
    Expressivité : ${expressivityDesc} (Niveau: ${config.expressivity.toFixed(1)})
    Gestion des silences : ${pauseDesc}
    Ambiance : ${reverbInstructions[config.roomReverb]}

    TEXTE À LIRE :
    ${text}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) throw new Error("No audio data received.");

    const pcmBytes = decodeBase64(base64Audio);
    const wavBlob = createWavBlob(pcmBytes, 24000);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      blob: wavBlob,
      url: audioUrl,
      pcmData: pcmBytes
    };
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    throw error;
  }
}

