  // Acoustic Controls
  const [acousticConfig, setAcousticConfig] = useState<AcousticConfig>({
    speed: 1.0,
    pitch: 1.0,
    volume: 1.0,
    prosody: 'Neutral',
    pauseDuration: 1.0,
    diction: 0.5,
    roomReverb: 'None',
    expressivity: 0.5
  });

  const [history, setHistory] = useState<HistoryItem[]>([]);
