            <div className="flex gap-1.5">
               <button 
                onClick={handleEnhanceScript} 
                disabled={isEnhancing || !text.trim()} 
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[9px] font-black transition-all border ${isEnhancing ? 'bg-indigo-50 border-indigo-100 text-indigo-400' : 'bg-white border-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white hover:shadow-lg'}`}
