import { GoogleGenAI, Modality, Type } from "@google/genai";
import { AudioResult, Language, VoiceName, AcousticConfig } from "../types";
import { decodeBase64, createWavBlob } from "../utils/audioConverter";

export async function analyzeContent(text: string): Promise<{ language: Language; recommendedVoice: VoiceName; style: string }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyse ce texte pour la synthèse vocale. 
      1. Identifie la langue (French, English, Spanish, German, Italian).
      2. Détermine le style (Documentaire, Corporatif, Énergique, Conte, Poétique).
      3. Recommande la meilleure voix parmi : 
         - 'Charon' (Sérieux, posé, idéal pour documentaire/tech - Voix Profonde)
         - 'Kore' (Pro, direct, idéal pour business/news)
         - 'Puck' (Dynamique, jeune, idéal pour pub/sport)
         - 'Fenrir' (Chaleureux, rassurant, idéal pour histoires/casual)
         - 'Zephyr' (Doux, clair, idéal pour poésie/méditation)

      Texte: "${text.substring(0, 1000)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { type: Type.STRING },
            recommendedVoice: { type: Type.STRING },
            style: { type: Type.STRING }
          },
          required: ["language", "recommendedVoice", "style"]
        }
      }
    });

    const json = JSON.parse(response.text);
    return {
      language: (Object.values(Language).includes(json.language as Language) ? json.language : Language.ENGLISH) as Language,
      recommendedVoice: json.recommendedVoice as VoiceName,
      style: json.style
    };
  } catch (error) {
    console.error("Content analysis error:", error);
    return { language: Language.FRENCH, recommendedVoice: 'Fenrir', style: 'Standard' };
  }
}

export async function enhanceScript(text: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Tu es un expert en narration audio. Optimise le texte suivant pour qu'il sonne naturel une fois lu par une IA. 
      Insère des balises discrètes comme [pause] pour une respiration ou [breath] avant une phrase importante. 
      Si le texte est technique, simplifie légèrement la structure pour la clarté orale.
      Retourne uniquement le texte optimisé.

      Texte original : "${text}"`,
    });
    return response.text.trim();
  } catch (err) {
    console.error("Script enhancement error:", err);
    return text;
  }
}

export async function generateSpeech(
  text: string, 
  language: Language, 
  voice: VoiceName, 
  config: AcousticConfig
): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prosodyInstructions = {
    Neutral: "ton neutre et équilibré",
    Educational: "ton pédagogique, clair et articulé, idéal pour l'apprentissage",
    Corporate: "ton professionnel, formel et assuré",
    Narrative: "ton narratif, fluide et expressif avec de légères variations émotionnelles",
    Energetic: "ton dynamique, enthousiaste et rapide",
    Conversational: "ton naturel, spontané, comme une discussion réelle entre deux personnes",
    Reading: "ton de lecture calme, posé et descriptif, type livre audio",
    Declarative: "ton affirmatif, clair, posé et autoritaire"
  };

  const reverbInstructions = {
    None: "son pur et direct sans réverbération",
    SmallRoom: "légère acoustique de pièce fermée",
    Studio: "acoustique de studio d'enregistrement professionnelle",
    LargeHall: "réverbération de grand hall spacieux"
  };

  const dictionDesc = config.diction > 0.7 ? "articulation extrêmement précise et nette" : "articulation naturelle";
  const pauseDesc = config.pauseDuration > 1.2 ? "pauses marquées entre les phrases" : "pauses naturelles";
  const expressivityDesc = config.expressivity > 0.7 ? "intonations très marquées et émotives" : config.expressivity < 0.3 ? "ton très monocorde et analytique" : "intonations naturelles";

  const prompt = `INSTRUCTIONS AUDIO :
    Voix : ${voice}
    Langue : ${language}
    Style d'élocution : ${prosodyInstructions[config.prosody]}
    Vitesse : ${config.speed.toFixed(1)}x
    Tonalité (Pitch) : ${config.pitch.toFixed(1)}
    Volume : ${config.volume.toFixed(1)}
    Diction : ${dictionDesc}
    Expressivité : ${expressivityDesc} (Niveau: ${config.expressivity.toFixed(1)})
    Gestion des silences : ${pauseDesc}
    Ambiance : ${reverbInstructions[config.roomReverb]}

    IMPORTANT : Respecte scrupuleusement les balises de pause insérées dans le texte :
    - [pause] : Silence court d'environ 0.5 seconde.
    - [pause:Xs] : Silence d'une durée précise de X secondes (ex: [pause:2s] pour 2 secondes).
    - [breath] : Une inspiration naturelle avant de reprendre la parole.

    TEXTE À LIRE :
    ${text}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) throw new Error("No audio data received.");

    const pcmBytes = decodeBase64(base64Audio);
    const wavBlob = createWavBlob(pcmBytes, 24000);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      blob: wavBlob,
      url: audioUrl,
      pcmData: pcmBytes
    };
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    throw error;
  }
}

