const SettingsIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>;
const EraserIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m7 21-4.3-4.3c-1-1-1-2.5 0-3.4l9.6-9.6c1-1 2.5-1 3.4 0l5.6 5.6c1 1 1 2.5 0 3.4L13 21"/><path d="M22 21H7"/><path d="m5 11 9 9"/></svg>;
const ClockIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>;

const VOICES_DB: VoiceMetadata[] = [
  { id: 'Charon', label: 'Léa - Narratrice Tech', tags: ['Documentaire', 'Tech', 'Sérieux'], description: 'Voix profonde et posée, idéale pour les narrations techniques.', previewText: 'Bienvenue dans ce module sur les infrastructures cloud.' },
  { id: 'Kore', label: 'Marc - Coach Corporate', tags: ['Formation', 'Business', 'News'], description: 'Direct et professionnel, parfait pour les messages d\'entreprise.', previewText: 'Nous allons voir ensemble les objectifs du trimestre.' },
  { id: 'Puck', label: 'Chloé - Voix Énergique', tags: ['E-learning', 'Jeune', 'Pub'], description: 'Dynamique et pétillante, capte l\'attention immédiatement.', previewText: 'Salut ! Prêt pour une nouvelle aventure d\'apprentissage ?' },
  { id: 'Fenrir', label: 'Paul - Conteur Chaleureux', tags: ['Formation', 'Narration', 'Podcast'], description: 'Chaleureux et rassurant, idéal pour les contenus longs.', previewText: 'Il était une fois une nouvelle méthode de management.' },
  { id: 'Zephyr', label: 'Sophie - Voix Zen', tags: ['Méditation', 'E-learning', 'Doux'], description: 'Poétique et calme, parfaite pour les sujets apaisants.', previewText: 'Prenez une grande inspiration et concentrez-vous.' }
];

const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const STYLE_LABELS: Record<ProsodyStyle, string> = {
  Neutral: 'Neutre',
  Educational: 'Éducatif',
  Corporate: 'Business',
  Narrative: 'Narratif',
  Energetic: 'Énergique',
  Conversational: 'Conversationnel',
  Reading: 'Lecture',
  Declarative: 'Déclaratif'
};

const App: React.FC = () => {
  // --- States ---
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [selectedVoiceId, setSelectedVoiceId] = useState<VoiceName>('Fenrir');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isEnhancing, setIsEnhancing] = useState<boolean>(false);
  const [isFixingAudio, setIsFixingAudio] = useState<boolean>(false);
  const [genStage, setGenStage] = useState<string>('');
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isAutoVoice, setIsAutoVoice] = useState<boolean>(true);
  const [detectedStyle, setDetectedStyle] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [activeFilter, setActiveFilter] = useState('All');
  const [exportFormat, setExportFormat] = useState<'WAV' | 'AAC' | 'MP3'>('MP3');

  // Acoustic Controls
  const [acousticConfig, setAcousticConfig] = useState<AcousticConfig>({
    speed: 1.0,
    pitch: 1.0,
    volume: 1.0,
    prosody: 'Neutral',
    pauseDuration: 1.0,
    diction: 0.5,
    roomReverb: 'None',
    expressivity: 0.5
  });

  const [history, setHistory] = useState<HistoryItem[]>([]);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const lineNumbersRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sync scrolling
  const handleScroll = () => {
    if (textareaRef.current && lineNumbersRef.current) {
      lineNumbersRef.current.scrollTop = textareaRef.current.scrollTop;
    }
  };

  const lineCount = text.split('\n').length;
  const wordCount = useMemo(() => text.trim() ? text.trim().split(/\s+/).length : 0, [text]);

  // --- Filtering ---
  const filteredVoices = useMemo(() => {
    return VOICES_DB.filter(v => {
      const matchesSearch = v.label.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           v.tags.some(t => t.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesFilter = activeFilter === 'All' || v.tags.includes(activeFilter);
      return matchesSearch && matchesFilter;
    });
  }, [searchTerm, activeFilter]);

  const allTags = useMemo(() => {
    const tags = new Set<string>(['All']);
    VOICES_DB.forEach(v => v.tags.forEach(t => tags.add(t)));
    return Array.from(tags);
  }, []);

  // --- Handlers ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt")) setText(await file.text());
      else if (fileName.endsWith(".docx")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf")) {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture du fichier."); }
  };

  const insertTextAtCursor = (insertion: string) => {
    if (!textareaRef.current) return;
    const { selectionStart, selectionEnd } = textareaRef.current;
    const newText = text.substring(0, selectionStart) + insertion + text.substring(selectionEnd);
    setText(newText);

    // Reposition cursor after insertion (async to allow state update)
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.selectionStart = textareaRef.current.selectionEnd = selectionStart + insertion.length;
      }
    }, 0);
  };

  const handleManualPause = () => {
    const duration = prompt("Durée de la pause en secondes (ex: 1, 2.5) ou laissez vide pour une pause courte :", "");
    if (duration === null) return;
    const tag = duration.trim() === "" ? "[pause]" : `[pause:${duration.trim()}s]`;
    insertTextAtCursor(tag);
  };

  const handleEnhanceScript = async () => {
    if (!text.trim() || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await enhanceScript(text);
      setText(enhanced);
    } catch (err) { setError("Erreur lors de l'optimisation."); }
    finally { setIsEnhancing(false); }
  };

  const handleFixAudioRhythm = async () => {
    if (!audioResult) return;
    setIsFixingAudio(true);
    setGenStage('Analyse Post-Production...');
    await new Promise(r => setTimeout(r, 1000));
    setGenStage('Stabilisation du tempo...');
    await new Promise(r => setTimeout(r, 1000));
    try {
      const stableConfig = { ...acousticConfig, speed: 1.0, diction: 1.0 };
      const result = await generateSpeech(text, language, selectedVoiceId, stableConfig);
      setAudioResult(result);
    } catch (err) { setError("Erreur de stabilisation."); }
    finally { setIsFixingAudio(false); setGenStage(''); }
  };

  const handleGenerate = async () => {
    if (!text.trim() || text.length > MAX_CHARS) return;
    setIsGenerating(true);
    setError(null);
    try {
      if (isAutoVoice) {
        setGenStage('Analyse contextuelle...');
        const analysis = await analyzeContent(text);
        setSelectedVoiceId(analysis.recommendedVoice);
        setLanguage(analysis.language);
        setDetectedStyle(analysis.style);
      }
      setGenStage('Génération Master HQ...');
      const result = await generateSpeech(text, language, selectedVoiceId, acousticConfig);
      setAudioResult(result);

      const newHistory: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        text: text.substring(0, 50),
        language,
        voice: selectedVoiceId,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistory, ...prev].slice(0, 10));
    } catch (err) { setError("Erreur de génération."); }
    finally { setIsGenerating(false); setGenStage(''); }
  };

  const handleDownload = async () => {
    if (!audioResult) return;

    let blob: Blob;
    let extension: string;

    switch (exportFormat) {
      case 'WAV':
        blob = createWavBlob(audioResult.pcmData, 24000);
        extension = 'wav';
        break;
      case 'AAC':
        blob = convertPcmToMp3(audioResult.pcmData, 24000); 
        extension = 'aac';
        break;
      case 'MP3':
      default:
        blob = convertPcmToMp3(audioResult.pcmData, 24000);
        extension = 'mp3';
        break;
    }

    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `voxgen-${selectedVoiceId.toLowerCase()}-${Date.now()}.${extension}`;
    a.click();
  };

  const handleVoicePreview = async (e: React.MouseEvent, voice: VoiceMetadata) => {
    e.stopPropagation();
    try {
      const res = await generateSpeech(voice.previewText, language, voice.id, acousticConfig);
      const audio = new Audio(res.url);
      audio.play();
    } catch (err) { console.error("Preview failed"); }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] text-slate-800 font-['Inter'] flex flex-col h-screen overflow-hidden">
      {/* Header */}
      <header className="bg-white border-b border-slate-100 py-3 px-8 flex justify-between items-center z-40 shadow-sm flex-shrink-0">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100">
            <WaveIcon />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight leading-none text-slate-900">VoxGen <span className="text-indigo-600">PRO</span></h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mt-0.5">Studio Audio Management</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold hover:bg-white hover:border-indigo-200 transition-all text-slate-500">
            <UploadIcon /> Importer
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button className="flex items-center gap-2 px-5 py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold hover:bg-indigo-700 transition-all shadow-md">
            Sauvegarder
          </button>
        </div>
      </header>

      {/* Main Workspace */}
      <main className="flex-1 flex overflow-hidden bg-slate-50/20">

        {/* Panel 1: Script Editor Station */}
        <section className="w-[42%] flex flex-col border-r border-slate-100 bg-white shadow-2xl z-20">
          <div className="px-6 py-3 border-b border-slate-50 flex justify-between items-center bg-slate-50/40">
            <div className="flex items-center gap-2.5">
              <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.6)]"></div>
              <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Flux de Narration</h3>
            </div>
            <div className="flex gap-1.5">
               <button 
                onClick={handleManualPause}
                className="flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-[9px] font-black text-slate-600 hover:border-indigo-400 hover:text-indigo-600 transition-all shadow-sm"
                title="Insérer une balise de pause"
              >
                <ClockIcon /> PAUSE
              </button>
               <button 
                onClick={handleEnhanceScript} 
                disabled={isEnhancing || !text.trim()} 
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[9px] font-black transition-all border ${isEnhancing ? 'bg-indigo-50 border-indigo-100 text-indigo-400' : 'bg-white border-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white hover:shadow-lg'}`}
              >
                {isEnhancing ? <LoadingSpinner className="w-3 h-3 text-indigo-400" /> : <MagicIcon />} OPTIMISER SCRIPT
              </button>
              <button 
                onClick={() => setText('')} 
                className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                title="Vider l'éditeur"
              >
                <EraserIcon />
              </button>
            </div>
          </div>

          <div className="flex-1 flex overflow-hidden relative group">
            <div 
              ref={lineNumbersRef}
              className="w-14 bg-slate-50/50 border-r border-slate-100 text-right pr-4 pt-6 text-[10px] font-bold text-slate-300 select-none overflow-hidden"
            >
              {Array.from({ length: lineCount }).map((_, i) => (
                <div key={i} className="h-7 leading-7 tabular-nums">{i + 1}</div>
              ))}
            </div>

            <textarea 
              ref={textareaRef}
              onScroll={handleScroll}
              className="flex-1 p-6 text-[16px] md:text-[18px] font-medium text-slate-700 bg-white border-none focus:ring-0 outline-none transition-all resize-none leading-7 placeholder:text-slate-200 placeholder:font-light selection:bg-indigo-100 custom-scrollbar"
              placeholder="Saisissez ou collez votre script professionnel ici..."
              value={text}
              onChange={(e) => setText(e.target.value)}
              spellCheck={false}
            />

            <div className="absolute bottom-6 right-8 left-20 pointer-events-none">
              <div className="flex items-center justify-between">
                <div className="flex gap-2">
                   {detectedStyle && (
                    <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 border border-indigo-100/50 px-2.5 py-1 rounded-md uppercase tracking-widest shadow-sm backdrop-blur-sm">
                      STYLE : {detectedStyle}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-3">
                  <div className="flex flex-col items-end bg-white/80 border border-slate-100 px-3 py-1.5 rounded-xl shadow-lg backdrop-blur-md">
                    <span className="text-[8px] font-black text-slate-300 uppercase leading-none mb-1">Analyse temps réel</span>
                    <div className="flex gap-3 text-[10px] font-black text-slate-600">
                      <span>{wordCount.toLocaleString()} <span className="text-slate-300">MOTS</span></span>
                      <span className={`${text.length > MAX_CHARS ? 'text-red-500' : 'text-slate-600'}`}>
                        {text.length.toLocaleString()} <span className="text-slate-300">/ {MAX_CHARS.toLocaleString()} CAR.</span>
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Panel 2: Voice Catalog */}
        <section className="flex-1 flex flex-col bg-[#F9FAFF] border-r border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-50 bg-white shadow-sm flex flex-col gap-4">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <AudioIcon />
                <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Bibliothèque Vocale</h3>
              </div>
              <button onClick={() => setIsAutoVoice(!isAutoVoice)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black transition-all flex items-center gap-2 ${isAutoVoice ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                {isAutoVoice && <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse"></span>}
                IA CONTEXTUELLE {isAutoVoice ? 'ACTIVÉE' : 'OFF'}
              </button>
            </div>

            <div className="relative">
              <div className="absolute inset-y-0 left-3.5 flex items-center text-slate-300"><SearchIcon /></div>
              <input 
                type="text" 
                placeholder="Chercher une voix par tag ou nom..." 
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 text-[12px] font-medium focus:bg-white focus:ring-2 focus:ring-indigo-100 outline-none transition-all placeholder:text-slate-300"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
              {allTags.map(tag => (
                <button 
                  key={tag} 
                  onClick={() => setActiveFilter(tag)}
                  className={`px-3 py-1.5 rounded-lg text-[9px] font-bold whitespace-nowrap transition-all uppercase tracking-tighter ${activeFilter === tag ? 'bg-indigo-50 text-indigo-600 border border-indigo-100' : 'bg-white text-slate-400 border border-slate-100 hover:border-indigo-100'}`}
                >
                  {tag}
                </button>
              ))}
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
            {filteredVoices.map(voice => (
              <div 
                key={voice.id} 
                onClick={() => { setSelectedVoiceId(voice.id); setIsAutoVoice(false); }}
                className={`p-5 rounded-2xl border-2 transition-all cursor-pointer group ${selectedVoiceId === voice.id ? 'bg-white border-indigo-600 shadow-xl shadow-indigo-200/20 scale-[1.01]' : 'bg-white border-slate-100 hover:border-indigo-100 shadow-sm hover:shadow-md'}`}
              >
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className={`p-3 rounded-xl transition-all shadow-sm ${selectedVoiceId === voice.id ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400 group-hover:text-indigo-600'}`}>
                      <AudioIcon />
                    </div>
                    <div>
                      <h4 className={`font-black text-[15px] ${selectedVoiceId === voice.id ? 'text-indigo-900' : 'text-slate-900'}`}>{voice.label}</h4>
                      <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-tight line-clamp-1">{voice.description}</p>
                    </div>
                  </div>
                  <button 
                    onClick={(e) => handleVoicePreview(e, voice)}
                    className={`p-2 rounded-lg transition-all transform hover:scale-110 ${selectedVoiceId === voice.id ? 'bg-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white' : 'bg-slate-50 text-slate-400 hover:bg-indigo-600 hover:text-white'}`}
                  >
                    <PlayIcon className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Panel 3: Master Processing */}
        <section className="w-[18%] flex flex-col bg-white overflow-y-auto custom-scrollbar border-l border-slate-100">
          <div className="p-5 border-b border-slate-50 bg-slate-50/40 flex justify-between items-center">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Post-Traitement</h3>
            <SettingsIcon />
          </div>

          <div className="p-6 space-y-8">
            <div className="space-y-3">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Styles de Prosodie</label>
              <div className="flex flex-col gap-1.5">
                {(['Neutral', 'Conversational', 'Reading', 'Declarative', 'Narrative', 'Educational', 'Corporate', 'Energetic'] as ProsodyStyle[]).map(style => (
                  <button 
                    key={style}
                    onClick={() => setAcousticConfig({...acousticConfig, prosody: style})}
                    className={`px-3 py-2 rounded-xl text-[10px] font-bold border-2 text-left transition-all ${acousticConfig.prosody === style ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white border-slate-50 text-slate-500 hover:border-indigo-100'}`}
                  >
                    {STYLE_LABELS[style]}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-6">
              {[
                { label: 'DÉBIT / TEMPO', key: 'speed', min: 0.5, max: 2.0, step: 0.1, unit: 'x' },
                { label: 'TONALITÉ / PITCH', key: 'pitch', min: 0.5, max: 2.0, step: 0.1, unit: '' },
                { label: 'DICTION / CLARTÉ', key: 'diction', min: 0, max: 1.0, step: 0.1, unit: '' },
                { label: 'EXPRESSIVITÉ', key: 'expressivity', min: 0, max: 1.0, step: 0.1, unit: '' }
              ].map(ctrl => (
                <div key={ctrl.key} className="space-y-2.5">
                  <div className="flex justify-between items-center">
