              <div className="bg-white rounded-2xl p-4 border-2 border-indigo-100 flex items-center gap-6 animate-slideUp shadow-xl shadow-indigo-50/50">
                <div className="p-3.5 bg-indigo-600 text-white rounded-xl shadow-lg"><AudioIcon /></div>
                <div className="flex-1">
                  <div className="flex justify-between items-center mb-2.5">
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-black text-indigo-600 tracking-[0.2em] uppercase">MASTER RENDU</span>
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{selectedVoiceId} • WAV 48KHZ</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <button onClick={handleFixAudioRhythm} className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-50 text-emerald-600 rounded-lg text-[9px] font-black hover:bg-emerald-600 hover:text-white transition-all uppercase tracking-tighter shadow-sm border border-emerald-100">
                        <WaveIcon /> STABILISER DÉBIT
                      </button>
                      <div className="h-6 w-[1px] bg-slate-100 mx-1"></div>
