                    </div>
                  </div>
                  <audio ref={audioRef} controls src={audioResult.url} className="w-full h-8 rounded-full" />
                </div>
              </div>
            ) : (
              <div className="bg-slate-50/40 rounded-2xl p-7 border-2 border-dashed border-slate-100 flex items-center justify-center">
                <p className="text-slate-400 text-[11px] font-black italic tracking-widest uppercase">Prêt pour le rendu final du master studio</p>
              </div>
            )}
          </div>

          <div className="w-80 flex flex-col gap-3">
             <div className="flex items-center justify-between px-1">
               <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">FORMAT D'EXPORT</span>
               <div className="flex bg-slate-100 p-1 rounded-lg gap-1">
                  {['WAV', 'AAC', 'MP3'].map(f => (
                    <button 
                      key={f}
                      onClick={() => setExportFormat(f as any)}
                      className={`px-3 py-1 rounded-md text-[9px] font-black transition-all ${exportFormat === f ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                      {f}
                    </button>
                  ))}
               </div>
             </div>

             <div className="flex gap-2">
                <button 
                  onClick={handleGenerate} 
                  disabled={!text.trim() || isGenerating || text.length > MAX_CHARS}
                  className={`flex-1 py-4 rounded-2xl font-black text-sm shadow-2xl transition-all relative overflow-hidden group ${isGenerating ? 'bg-slate-200 text-slate-400' : 'bg-indigo-900 text-white hover:bg-black hover:-translate-y-1'}`}
                >
                  {isGenerating ? (
                    <LoadingSpinner className="h-5 w-5 mx-auto text-indigo-600" />
                  ) : (
                    <span className="flex items-center justify-center gap-2 tracking-[0.1em] font-black text-[11px]">
                      GÉNÉRER AUDIO <PlayIcon className="w-4 h-4" />
                    </span>
                  )}
                </button>

                {audioResult && (
                  <button 
                    onClick={handleDownload}
                    className="px-5 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm shadow-2xl hover:bg-indigo-700 hover:-translate-y-1 transition-all flex items-center gap-2"
                  >
                    <DownloadIcon />
                    <span className="text-[10px] tracking-widest">{exportFormat}</span>
                  </button>
                )}
             </div>
             {error && <p className="text-[9px] text-red-500 font-bold text-center uppercase tracking-widest">{error}</p>}
          </div>
        </div>
      </footer>

      <style>{`
        @keyframes slideUp { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
        .animate-slideUp { animation: slideUp 0.55s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #eef2f6; border-radius: 10px; }
      `}</style>
    </div>
  );
};

