const LANGS = [
  { id: Language.FRENCH, label: 'Français', flag: '🇫🇷' },
  { id: Language.ENGLISH, label: 'English', flag: '🇺🇸' },
  { id: Language.SPANISH, label: 'Español', flag: '🇪🇸' },
  { id: Language.GERMAN, label: 'Deutsch', flag: '🇩🇪' },
  { id: Language.ITALIAN, label: 'Italiano', flag: '🇮🇹' },
];

const STYLE_LABELS: Record<ProsodyStyle, string> = {
  Neutral: 'Neutre',
  Educational: 'Éducatif',
  Corporate: 'Business',
  Narrative: 'Narratif',
  Energetic: 'Énergique',
  Conversational: 'Conversationnel',
  Reading: 'Lecture',
  Declarative: 'Déclaratif'
};

const App: React.FC = () => {
  // --- States ---
  const [text, setText] = useState<string>('');
  const [language, setLanguage] = useState<Language>(Language.FRENCH);
  const [selectedVoiceId, setSelectedVoiceId] = useState<VoiceName>('Fenrir');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [isEnhancing, setIsEnhancing] = useState<boolean>(false);
  const [isFixingAudio, setIsFixingAudio] = useState<boolean>(false);
  const [genStage, setGenStage] = useState<string>('');
  const [audioResult, setAudioResult] = useState<AudioResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isAutoVoice, setIsAutoVoice] = useState<boolean>(true);
  const [detectedStyle, setDetectedStyle] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [activeFilter, setActiveFilter] = useState('All');
  const [exportFormat, setExportFormat] = useState<'WAV' | 'AAC' | 'MP3'>('MP3');

  // Acoustic Controls
  const [acousticConfig, setAcousticConfig] = useState<AcousticConfig>({
    speed: 1.0,
    pitch: 1.0,
    volume: 1.0,
    prosody: 'Neutral',
    pauseDuration: 1.0,
    diction: 0.5,
    roomReverb: 'None',
    expressivity: 0.5
  });

  const [history, setHistory] = useState<HistoryItem[]>([]);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const lineNumbersRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sync scrolling
  const handleScroll = () => {
    if (textareaRef.current && lineNumbersRef.current) {
      lineNumbersRef.current.scrollTop = textareaRef.current.scrollTop;
    }
  };

  const lineCount = text.split('\n').length;
  const wordCount = useMemo(() => text.trim() ? text.trim().split(/\s+/).length : 0, [text]);

  // --- Filtering ---
  const filteredVoices = useMemo(() => {
    return VOICES_DB.filter(v => {
      const matchesSearch = v.label.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           v.tags.some(t => t.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesFilter = activeFilter === 'All' || v.tags.includes(activeFilter);
      return matchesSearch && matchesFilter;
    });
  }, [searchTerm, activeFilter]);

  const allTags = useMemo(() => {
    const tags = new Set<string>(['All']);
    VOICES_DB.forEach(v => v.tags.forEach(t => tags.add(t)));
    return Array.from(tags);
  }, []);

  // --- Handlers ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setError(null);
    try {
      const fileName = file.name.toLowerCase();
      if (fileName.endsWith(".txt")) setText(await file.text());
      else if (fileName.endsWith(".docx")) {
        const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
        setText(result.value);
      } else if (fileName.endsWith(".pdf")) {
        const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
        let fullText = "";
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          fullText += textContent.items.map((item: any) => item.str).join(" ") + "\n";
        }
        setText(fullText);
      }
    } catch (err) { setError("Erreur de lecture du fichier."); }
  };

  const insertTextAtCursor = (insertion: string) => {
    if (!textareaRef.current) return;
    const { selectionStart, selectionEnd } = textareaRef.current;
    const newText = text.substring(0, selectionStart) + insertion + text.substring(selectionEnd);
    setText(newText);

    // Reposition cursor after insertion (async to allow state update)
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.selectionStart = textareaRef.current.selectionEnd = selectionStart + insertion.length;
      }
    }, 0);
  };

  const handleManualPause = () => {
    const duration = prompt("Durée de la pause en secondes (ex: 1, 2.5) ou laissez vide pour une pause courte :", "");
    if (duration === null) return;
    const tag = duration.trim() === "" ? "[pause]" : `[pause:${duration.trim()}s]`;
    insertTextAtCursor(tag);
  };

  const handleEnhanceScript = async () => {
    if (!text.trim() || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await enhanceScript(text);
      setText(enhanced);
    } catch (err) { setError("Erreur lors de l'optimisation."); }
    finally { setIsEnhancing(false); }
  };

  const handleFixAudioRhythm = async () => {
    if (!audioResult) return;
    setIsFixingAudio(true);
    setGenStage('Analyse Post-Production...');
    await new Promise(r => setTimeout(r, 1000));
    setGenStage('Stabilisation du tempo...');
    await new Promise(r => setTimeout(r, 1000));
    try {
      const stableConfig = { ...acousticConfig, speed: 1.0, diction: 1.0 };
      const result = await generateSpeech(text, language, selectedVoiceId, stableConfig);
      setAudioResult(result);
    } catch (err) { setError("Erreur de stabilisation."); }
    finally { setIsFixingAudio(false); setGenStage(''); }
  };

  const handleGenerate = async () => {
    if (!text.trim() || text.length > MAX_CHARS) return;
    setIsGenerating(true);
    setError(null);
    try {
      if (isAutoVoice) {
        setGenStage('Analyse contextuelle...');
        const analysis = await analyzeContent(text);
        setSelectedVoiceId(analysis.recommendedVoice);
        setLanguage(analysis.language);
        setDetectedStyle(analysis.style);
      }
      setGenStage('Génération Master HQ...');
      const result = await generateSpeech(text, language, selectedVoiceId, acousticConfig);
      setAudioResult(result);

      const newHistory: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        text: text.substring(0, 50),
        language,
        voice: selectedVoiceId,
        audioUrl: result.url,
        pcmData: result.pcmData
      };
      setHistory(prev => [newHistory, ...prev].slice(0, 10));
    } catch (err) { setError("Erreur de génération."); }
    finally { setIsGenerating(false); setGenStage(''); }
  };

  const handleDownload = async () => {
    if (!audioResult) return;

    let blob: Blob;
    let extension: string;

    switch (exportFormat) {
      case 'WAV':
        blob = createWavBlob(audioResult.pcmData, 24000);
        extension = 'wav';
        break;
      case 'AAC':
        blob = convertPcmToMp3(audioResult.pcmData, 24000); 
        extension = 'aac';
        break;
      case 'MP3':
      default:
        blob = convertPcmToMp3(audioResult.pcmData, 24000);
        extension = 'mp3';
        break;
    }

    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `voxgen-${selectedVoiceId.toLowerCase()}-${Date.now()}.${extension}`;
    a.click();
  };

  const handleVoicePreview = async (e: React.MouseEvent, voice: VoiceMetadata) => {
    e.stopPropagation();
    try {
      const res = await generateSpeech(voice.previewText, language, voice.id, acousticConfig);
      const audio = new Audio(res.url);
      audio.play();
    } catch (err) { console.error("Preview failed"); }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] text-slate-800 font-['Inter'] flex flex-col h-screen overflow-hidden">
      {/* Header */}
      <header className="bg-white border-b border-slate-100 py-3 px-8 flex justify-between items-center z-40 shadow-sm flex-shrink-0">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100">
            <WaveIcon />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight leading-none text-slate-900">VoxGen <span className="text-indigo-600">PRO</span></h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mt-0.5">Studio Audio Management</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold hover:bg-white hover:border-indigo-200 transition-all text-slate-500">
            <UploadIcon /> Importer
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button className="flex items-center gap-2 px-5 py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold hover:bg-indigo-700 transition-all shadow-md">
            Sauvegarder
          </button>
        </div>
      </header>

      {/* Main Workspace */}
      <main className="flex-1 flex overflow-hidden bg-slate-50/20">

        {/* Panel 1: Script Editor Station */}
        <section className="w-[42%] flex flex-col border-r border-slate-100 bg-white shadow-2xl z-20">
