    SmallRoom: "légère acoustique de pièce fermée",
    Studio: "acoustique de studio d'enregistrement professionnelle",
    LargeHall: "réverbération de grand hall spacieux"
  };

  const dictionDesc = config.diction > 0.7 ? "articulation extrêmement précise et nette" : "articulation naturelle";
  const pauseDesc = config.pauseDuration > 1.2 ? "pauses marquées entre les phrases" : "pauses naturelles";
  const expressivityDesc = config.expressivity > 0.7 ? "intonations très marquées et émotives" : config.expressivity < 0.3 ? "ton très monocorde et analytique" : "intonations naturelles";

  // Nous fusionnons les instructions directement dans le prompt de contenu.
  // Cela évite l'erreur 400 "model returned non-audio response" car le modèle
  // a tendance à vouloir "répondre" aux systemInstructions textuellement.
  const prompt = `INSTRUCTIONS DE SYNTHÈSE VOCALE :
Tu es un moteur TTS haute fidélité. NE GÉNÈRE AUCUN TEXTE. Génère UNIQUEMENT le flux audio PCM.
