  text: string, 
  language: Language, 
  voice: VoiceName, 
  config: AcousticConfig
): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prosodyInstructions = {
    Neutral: "natural and balanced",
    Educational: "educational and clear",
    Corporate: "professional and formal",
    Narrative: "narrative and fluid",
    Energetic: "energetic and fast",
    Conversational: "conversational and spontaneous",
    Reading: "calm and descriptive",
    Declarative: "affirmative and clear"
  };

  /**
   * IMPORTANT: Le modèle TTS Gemini est extrêmement sensible. 
   * Toute instruction complexe ou "meta" dans le prompt peut forcer le modèle 
   * à répondre textuellement (Error 400: non-audio response).
   * 
   * On utilise ici une approche minimaliste : une seule phrase d'instruction 
   * suivie immédiatement du texte à lire.
   */
  const style = prosodyInstructions[config.prosody] || "natural";
  const speedText = config.speed !== 1.0 ? ` at ${config.speed}x speed` : "";

  // Prompt ultra-simplifié en anglais (mieux compris par les couches de contrôle du modèle)
  // pour s'assurer que le modèle reste en mode "Lecture" et non "Conversation".
  const prompt = `Read the following text in a ${style} tone${speedText}. 
Respect any [pause] or [breath] markers.

Text:
${text}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        // systemInstruction est omis car il cause souvent des conflits de modalité sur ce modèle spécifique
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });

    const candidate = response.candidates?.[0];
    if (!candidate || !candidate.content) {
      throw new Error("Invalid model response: No content received.");
    }

    // Recherche de la partie audio
    const audioPart = candidate.content.parts.find(p => p.inlineData);

    if (!audioPart || !audioPart.inlineData) {
      // Si on a du texte au lieu de l'audio, c'est que le prompt a déclenché une réponse textuelle
      const textPart = candidate.content.parts.find(p => p.text);
      if (textPart && textPart.text) {
        console.warn("Model returned text instead of audio:", textPart.text);
        throw new Error("Le modèle a tenté de répondre textuellement au lieu de générer l'audio. Essayez de simplifier le texte.");
      }
      throw new Error("No audio data received from model.");
    }

    const base64Audio = audioPart.inlineData.data;
    const pcmBytes = decodeBase64(base64Audio);
    const wavBlob = createWavBlob(pcmBytes, 24000);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      blob: wavBlob,
      url: audioUrl,
      pcmData: pcmBytes
    };
  } catch (error: any) {
    console.error("Gemini TTS Generate Error:", error);

    // Erreur 400 spécifique au TTS
    if (error.message?.includes("non-audio response")) {
      throw new Error("Le texte est trop complexe ou ressemble trop à une question, ce qui empêche la génération audio. Essayez de reformuler.");
    }

    // Erreur de limite ou de taille
    if (error.message?.includes("429") || error.message?.includes("limit")) {
      throw new Error("Limite de requêtes atteinte. Veuillez patienter un instant.");
    }

    throw new Error(error.message || "Une erreur est survenue lors de la synthèse vocale.");
  }
}

