import { GoogleGenAI, Modality, Type } from "@google/genai";
import { AudioResult, Language, VoiceName, AcousticConfig, PronunciationRule } from "../types";
import { decodeBase64, createWavBlob, concatPcmBuffers, generateSilence } from "../utils/audioConverter";

/**
 * Applique les règles de prononciation personnalisées (Lexique)
 */
function applyPronunciationRules(text: string, rules: PronunciationRule[]): string {
  let processedText = text;
  // On trie par longueur de mot décroissante pour éviter que les mots courts ne cassent les mots longs
  const sortedRules = [...rules].sort((a, b) => b.word.length - a.word.length);

  for (const rule of sortedRules) {
    if (!rule.word.trim() || !rule.phonetic.trim()) continue;

    // Utilisation de Regex avec word boundaries (\b) pour ne remplacer que les mots entiers
    // On échappe les caractères spéciaux pour la regex
    const escapedWord = rule.word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`\\b${escapedWord}\\b`, 'gi');
    processedText = processedText.replace(regex, rule.phonetic);
  }
  return processedText;
}

/**
 * Normalisation stricte du texte (nombres, abréviations)
 */
function normalizeText(text: string): string {
  let normalized = text;

  // Ponctuation finale automatique si absente
  if (!/[.!?]$/.test(normalized.trim())) {
    normalized = normalized.trim() + ".";
  }

  return normalized;
}

export async function analyzeContent(text: string): Promise<{ language: Language; recommendedVoice: VoiceName; style: string }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyse ce texte pour la synthèse vocale. 
      1. Identifie la langue (French, English, Spanish, German, Italian).
      2. Détermine le style (Documentaire, Corporatif, Énergique, Conte, Poétique).
      3. Recommande la meilleure voix parmi : 
         - 'Charon' (Sérieux, posé, idéal pour documentaire/tech - Voix Profonde)
         - 'Kore' (Pro, direct, idéal pour business/news)
         - 'Puck' (Dynamique, jeune, idéal pour pub/sport)
         - 'Fenrir' (Chaleureux, rassurant, idéal pour histoires/casual)
         - 'Zephyr' (Doux, clair, idéal pour poésie/méditation)

      Texte: "${text.substring(0, 1000)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { type: Type.STRING },
            recommendedVoice: { type: Type.STRING },
            style: { type: Type.STRING }
          },
          required: ["language", "recommendedVoice", "style"]
        }
      }
    });

    const json = JSON.parse(response.text);
    return {
      language: (Object.values(Language).includes(json.language as Language) ? json.language : Language.ENGLISH) as Language,
      recommendedVoice: json.recommendedVoice as VoiceName,
      style: json.style
    };
  } catch (error) {
    console.error("Content analysis error:", error);
    return { language: Language.FRENCH, recommendedVoice: 'Fenrir', style: 'Standard' };
  }
}

export async function enhanceScript(text: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Tu es un expert en optimisation de texte pour Text-to-Speech avancé.
Optimise uniquement la ponctuation et ajoute des pauses naturelles adaptées à une narration fluide.

Règles STRICTES :
- Ne change AUCUN mot.
- Ne reformule RIEN.
- Ne modifie pas le contenu.
- Tu peux uniquement ajuster la ponctuation et insérer des pauses naturelles comme [pause] ou [breath].
- Si nécessaire, ajoute des pauses courtes (.) ou (...) pour éviter l'accélération finale.
- Le texte de sortie doit être identique mot pour mot au texte d'entrée.

Texte à optimiser : 
"${text}"`,
    });
    return response.text.trim();
  } catch (err) {
    console.error("Script enhancement error:", err);
    return text;
  }
}

/**
 * Génération de parole avec gestion de la stabilité, de la segmentation et du lexique de prononciation
 */
export async function generateSpeech(
  text: string, 
  language: Language, 
  voice: VoiceName, 
  config: AcousticConfig
): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // 1. Application des règles de prononciation (Lexique)
  let processedText = applyPronunciationRules(text, config.pronunciationRules || []);

  // 2. Normalisation du texte
  if (config.normalizeText) {
    processedText = normalizeText(processedText);
  }

  // 3. Segmentation automatique pour éviter la dérive temporelle sur textes longs (> 500 car.)
  const segments = config.isSegmented && processedText.length > 500 
    ? processedText.split(/(?<=[.!?])\s+/) 
    : [processedText];

  const pcmBuffers: Uint8Array[] = [];

  for (const segment of segments) {
    if (!segment.trim()) continue;

    const prosodyPrefix = {
      Neutral: "Read clearly:",
      Educational: "Read in an educational tone:",
      Corporate: "Read in a professional tone:",
      Narrative: "Tell this story:",
      Energetic: "Say energetically:",
      Conversational: "Say naturally:",
      Reading: "Read this text:",
      Declarative: "State clearly:"
    };

    const prefix = prosodyPrefix[config.prosody] || "Read:";

    // Application stricte du speaking rate (0.9 - 1.05 recommandé)
    const rate = Math.min(Math.max(config.speakingRate, 0.9), 1.1);

    // Prompt optimisé pour la stabilité neurale
    const prompt = `${prefix} (Stability: ${config.stability}, Rate: ${rate}x) "${segment.replace(/"/g, "'")}"`;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voice },
            },
          },
        },
      });

      const audioPart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (audioPart?.inlineData) {
        pcmBuffers.push(decodeBase64(audioPart.inlineData.data));

        // Petit silence entre segments pour la respiration naturelle (300ms)
        if (segments.length > 1) {
          pcmBuffers.push(generateSilence(300, 24000));
        }
      }
    } catch (error) {
      console.error("Segment generation error:", error);
      if (segments.length === 1) throw error; // Si un seul segment échoue, on throw
    }
  }

  if (pcmBuffers.length === 0) {
    throw new Error("Échec de la génération des segments audio.");
  }

  // Final Padding (300-500ms de silence en fin de master)
  if (config.addFinalPadding) {
    pcmBuffers.push(generateSilence(450, 24000));
  }

  const finalPcm = concatPcmBuffers(pcmBuffers);
  const wavBlob = createWavBlob(finalPcm, 24000);

  return {
    blob: wavBlob,
    url: URL.createObjectURL(wavBlob),
    pcmData: finalPcm
  };
}

