import { GoogleGenAI, Modality, Type } from "@google/genai";
import { AudioResult, Language, VoiceName, AcousticConfig, PronunciationRule, WordTimestamp } from "../types";
import { decodeBase64, createWavBlob, concatPcmBuffers, generateSilence } from "../utils/audioConverter";

/**
 * Applique les règles de prononciation personnalisées (Lexique)
 */
function applyPronunciationRules(text: string, rules: PronunciationRule[]): string {
  let processedText = text;
  const sortedRules = [...rules].sort((a, b) => b.word.length - a.word.length);

  for (const rule of sortedRules) {
    if (!rule.word.trim() || !rule.phonetic.trim()) continue;
    const escapedWord = rule.word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`\\b${escapedWord}\\b`, 'gi');
    processedText = processedText.replace(regex, rule.phonetic);
  }
  return processedText;
}

/**
 * Normalisation stricte du texte
 */
function normalizeText(text: string): string {
  let normalized = text;
  if (!/[.!?]$/.test(normalized.trim())) {
    normalized = normalized.trim() + ".";
  }
  return normalized;
}

/**
 * Estime les timestamps des mots en se basant sur la durée totale et la complexité des mots.
 * Utilisé pour le surlignage dynamique en l'absence de métadonnées natives du modèle TTS.
 */
async function estimateWordTimestamps(text: string, totalDuration: number): Promise<WordTimestamp[]> {
  const words = text.trim().split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return [];

  // On calcule le poids de chaque mot basé sur sa longueur (les mots longs durent plus longtemps)
  const weights = words.map(w => w.length + 2); // +2 pour compenser les pauses naturelles inter-mots
  const totalWeight = weights.reduce((a, b) => a + b, 0);

  let currentTime = 0;
  return words.map((word, i) => {
    const duration = (weights[i] / totalWeight) * totalDuration;
    const timestamp = {
      word,
      startTime: currentTime,
      duration: duration
    };
    currentTime += duration;
    return timestamp;
  });
}

export async function analyzeContent(text: string): Promise<{ language: Language; recommendedVoice: VoiceName; style: string }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyse ce texte pour la synthèse vocale. 
      1. Identifie la langue (French, English, Spanish, German, Italian).
      2. Détermine le style.
      3. Recommande la meilleure voix parmi : 'Charon', 'Kore', 'Puck', 'Fenrir', 'Zephyr'.
      Texte: "${text.substring(0, 1000)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { type: Type.STRING },
            recommendedVoice: { type: Type.STRING },
            style: { type: Type.STRING }
          },
          required: ["language", "recommendedVoice", "style"]
        }
      }
    });
    const json = JSON.parse(response.text);
    return {
      language: (Object.values(Language).includes(json.language as Language) ? json.language : Language.ENGLISH) as Language,
      recommendedVoice: json.recommendedVoice as VoiceName,
      style: json.style
    };
  } catch (error) {
    return { language: Language.FRENCH, recommendedVoice: 'Fenrir', style: 'Standard' };
  }
}

export async function enhanceScript(text: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Optimise la ponctuation pour un TTS fluide sans changer les mots. Texte : "${text}"`,
    });
    return response.text.trim();
  } catch (err) {
    return text;
  }
}

/**
 * Génération de parole avec débit constant, stabilité et calcul de timestamps
 */
export async function generateSpeech(
  text: string, 
  language: Language, 
  voice: VoiceName, 
  config: AcousticConfig
): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Application du lexique et normalisation
  let processedText = applyPronunciationRules(text, config.pronunciationRules || []);
  if (config.normalizeText) processedText = normalizeText(processedText);

  // Segmentation pour la stabilité des longs textes
  const segments = config.isSegmented && processedText.length > 500 
    ? processedText.split(/(?<=[.!?])\s+/) 
    : [processedText];

  const pcmBuffers: Uint8Array[] = [];
  const sampleRate = 24000;

  for (const segment of segments) {
    if (!segment.trim()) continue;

    // LE DÉBIT EST FORCÉ À 1.0 POUR LA STABILITÉ MAXIMALE (consigne technique)
    const rate = 1.0; 
    const prompt = `Read clearly at constant rate 1.0 and high stability: "${segment.replace(/"/g, "'")}"`;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voice },
            },
          },
        },
      });

      const audioPart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (audioPart?.inlineData) {
        pcmBuffers.push(decodeBase64(audioPart.inlineData.data));
        // Pause respiratoire entre segments
        if (segments.length > 1) pcmBuffers.push(generateSilence(350, sampleRate));
      }
    } catch (error) {
      if (segments.length === 1) throw error;
    }
  }

  if (pcmBuffers.length === 0) throw new Error("Audio non généré.");

  // Padding final obligatoire (450ms)
  if (config.addFinalPadding) pcmBuffers.push(generateSilence(450, sampleRate));

  const finalPcm = concatPcmBuffers(pcmBuffers);
  const wavBlob = createWavBlob(finalPcm, sampleRate);

  // Calcul de la durée totale en secondes
  const totalDuration = (finalPcm.length / 2) / sampleRate;

  // Calcul des timestamps pour le surlignage dynamique
  const timestamps = await estimateWordTimestamps(text, totalDuration);

  return {
    blob: wavBlob,
    url: URL.createObjectURL(wavBlob),
    pcmData: finalPcm,
    timestamps
  };
}

