                {audioResult && (
                  <button onClick={handleDownload} className="px-5 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm shadow-2xl hover:bg-indigo-700 transition-all flex items-center justify-center">
                    <DownloadIcon />
                  </button>
                )}
             </div>
             {error && <p className="text-[9px] text-red-500 font-bold text-center uppercase tracking-tighter">{error}</p>}
          </div>
        </div>
      </footer>

      <style>{`
        @keyframes slideUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-slideUp { animation: slideUp 0.4s ease-out forwards; }
        .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #eef2f6; border-radius: 10px; }
        input[type=range].accent-indigo-600::-webkit-slider-thumb {
          -webkit-appearance: none;
          height: 12px;
          width: 12px;
          border-radius: 100%;
          background: #4f46e5;
          cursor: pointer;
          border: 2px solid white;
          box-shadow: 0 0 5px rgba(79, 70, 229, 0.3);
        }
      `}</style>
    </div>
  );
};

