/**
 * Decodes a base64 string to a Uint8Array
 */
export function decodeBase64(base64: string): Uint8Array {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Concatenates multiple Uint8Array PCM buffers
 */
export function concatPcmBuffers(buffers: Uint8Array[]): Uint8Array {
  const totalLength = buffers.reduce((acc, b) => acc + b.length, 0);
  const result = new Uint8Array(totalLength);
  let offset = 0;
  for (const b of buffers) {
    result.set(b, offset);
    offset += b.length;
  }
  return result;
}

/**
 * Normalise le gain des données PCM 16-bit pour atteindre un pic cible (Mastering)
 * Cible par défaut : -1dB (32768 * 0.89)
 */
export function normalizeAudioGain(pcmData: Uint8Array, targetPeak: number = 0.9): Uint8Array {
  const samples = new Int16Array(pcmData.buffer);
  let maxVal = 0;

  // 1. Trouver le pic absolu
  for (let i = 0; i < samples.length; i++) {
    const abs = Math.abs(samples[i]);
    if (abs > maxVal) maxVal = abs;
  }

  if (maxVal === 0) return pcmData;

  // 2. Calculer le facteur de gain
  const target = 32767 * targetPeak;
  const gainFactor = target / maxVal;

  // 3. Appliquer le gain (avec protection contre l'écrêtage)
  const normalized = new Int16Array(samples.length);
  for (let i = 0; i < samples.length; i++) {
    const val = samples[i] * gainFactor;
    normalized[i] = Math.max(-32768, Math.min(32767, Math.floor(val)));
  }

  return new Uint8Array(normalized.buffer);
}

/**
 * Generates silence PCM data (16-bit mono)
 */
export function generateSilence(durationMs: number, sampleRate: number = 24000): Uint8Array {
  const numSamples = Math.floor((durationMs / 1000) * sampleRate);
  return new Uint8Array(numSamples * 2);
}

/**
 * Encapsulates raw PCM data into a WAV container
 */
export function createWavBlob(pcmData: Uint8Array, sampleRate: number = 24000): Blob {
  const header = new ArrayBuffer(44);
  const view = new DataView(header);

  // RIFF chunk descriptor
  view.setUint32(0, 0x52494646, false); // "RIFF"
  view.setUint32(4, 36 + pcmData.length, true); 
  view.setUint32(8, 0x57415645, false); // "WAVE"

  // fmt sub-chunk
  view.setUint32(12, 0x666d7420, false); // "fmt "
  view.setUint32(16, 16, true); 
  view.setUint16(20, 1, true); 
  view.setUint16(22, 1, true); 
  view.setUint32(24, sampleRate, true); 
  view.setUint32(28, sampleRate * 2, true); 
  view.setUint16(32, 2, true); 
  view.setUint16(34, 16, true); 

  // data sub-chunk
  view.setUint32(36, 0x64617461, false); // "data"
  view.setUint32(40, pcmData.length, true); 

  return new Blob([header, pcmData], { type: 'audio/wav' });
}

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { AudioResult, Language, VoiceName, AcousticConfig, PronunciationRule, WordTimestamp } from "../types";
import { decodeBase64, createWavBlob, concatPcmBuffers, generateSilence, normalizeAudioGain } from "../utils/audioConverter";

/**
 * Applique les règles de prononciation personnalisées (Lexique)
 */
function applyPronunciationRules(text: string, rules: PronunciationRule[]): string {
  let processedText = text;
  const sortedRules = [...rules].sort((a, b) => b.word.length - a.word.length);

  for (const rule of sortedRules) {
    if (!rule.word.trim() || !rule.phonetic.trim()) continue;
    const escapedWord = rule.word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`\\b${escapedWord}\\b`, 'gi');
    processedText = processedText.replace(regex, rule.phonetic);
  }
  return processedText;
}

/**
 * Normalisation stricte du texte (Chiffres, Ponctuation)
 */
function normalizeText(text: string): string {
  let normalized = text;
  // Ajouter un point final si manquant pour assurer la clôture phonétique
  if (!/[.!?]$/.test(normalized.trim())) {
    normalized = normalized.trim() + ".";
  }
  return normalized;
}

/**
 * Estime les timestamps des mots en tenant compte de la complexité syllabique et de la ponctuation.
 */
async function estimateWordTimestamps(text: string, totalDuration: number): Promise<WordTimestamp[]> {
  const rawWords = text.trim().split(/\s+/).filter(w => w.length > 0);
  if (rawWords.length === 0) return [];

  // Poids basé sur la longueur + bonus pour ponctuation (simule une pause)
  const weights = rawWords.map(w => {
    let weight = w.length + 2; 
    if (w.endsWith('.') || w.endsWith('!') || w.endsWith('?')) weight += 5;
    if (w.endsWith(',')) weight += 3;
    return weight;
  });

  const totalWeight = weights.reduce((a, b) => a + b, 0);

  let currentTime = 0;
  return rawWords.map((word, i) => {
    const duration = (weights[i] / totalWeight) * totalDuration;
    const timestamp = {
      word,
      startTime: currentTime,
      duration: duration
    };
    currentTime += duration;
    return timestamp;
  });
}

export async function analyzeContent(text: string): Promise<{ language: Language; recommendedVoice: VoiceName; style: string }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyse ce texte pour la synthèse vocale. 
      1. Identifie la langue.
      2. Détermine le style narratif précis.
      3. Recommande la meilleure voix parmi : 'Charon', 'Kore', 'Puck', 'Fenrir', 'Zephyr'.
      Texte: "${text.substring(0, 1000)}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            language: { type: Type.STRING },
            recommendedVoice: { type: Type.STRING },
            style: { type: Type.STRING }
          },
          required: ["language", "recommendedVoice", "style"]
        }
      }
    });
    const json = JSON.parse(response.text);
    return {
      language: (Object.values(Language).includes(json.language as Language) ? json.language : Language.ENGLISH) as Language,
      recommendedVoice: json.recommendedVoice as VoiceName,
      style: json.style
    };
  } catch (error) {
    return { language: Language.FRENCH, recommendedVoice: 'Fenrir', style: 'Standard' };
  }
}

export async function enhanceScript(text: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Tu es un expert en script audio. Optimise uniquement la ponctuation du texte suivant pour une lecture fluide, sans changer un seul mot. Texte : "${text}"`,
    });
    return response.text.trim();
  } catch (err) {
    return text;
  }
}

/**
 * Génération de parole haute fidélité avec moteur stabilisé et traitement parallèle
 */
export async function generateSpeech(
  text: string, 
  language: Language, 
  voice: VoiceName, 
  config: AcousticConfig
): Promise<AudioResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let processedText = applyPronunciationRules(text, config.pronunciationRules || []);
  if (config.normalizeText) processedText = normalizeText(processedText);

  // Segmentation intelligente pour parallélisation (découpage par phrase complète)
  const segments = config.isSegmented 
    ? processedText.split(/(?<=[.!?])\s+/) 
    : [processedText];

  const sampleRate = 24000;

  // Génération parallèle pour réduire la latence
  const pcmPromises = segments.map(async (segment) => {
    if (!segment.trim()) return null;

    const stabilityPrompt = `[MODE: HIGH_STABILITY, RATE: 1.0x] Read with crystal clear diction and perfectly constant pace: "${segment.replace(/"/g, "'")}"`;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: stabilityPrompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voice },
            },
          },
        },
      });

      const audioPart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (audioPart?.inlineData) {
        return decodeBase64(audioPart.inlineData.data);
      }
      return null;
    } catch (error) {
      console.error("Segment failed:", error);
      return null;
    }
  });

  const results = await Promise.all(pcmPromises);
  const validPcms: Uint8Array[] = [];

  results.forEach((pcm, idx) => {
    if (pcm) {
      validPcms.push(pcm);
      // Ajout d'un micro-silence naturel entre phrases (350ms)
      if (idx < results.length - 1) {
        validPcms.push(generateSilence(350, sampleRate));
      }
    }
  });

  if (validPcms.length === 0) throw new Error("Le moteur n'a pas pu générer l'audio.");

  // Padding final de stabilisation (500ms)
  if (config.addFinalPadding) {
    validPcms.push(generateSilence(500, sampleRate));
  }

  let finalPcm = concatPcmBuffers(validPcms);

  // ÉTAPE DE MASTERING : Normalisation du Gain
  if (config.enableMastering) {
    finalPcm = normalizeAudioGain(finalPcm, 0.9);
  }

  const wavBlob = createWavBlob(finalPcm, sampleRate);
  const totalDuration = (finalPcm.length / 2) / sampleRate;
  const timestamps = await estimateWordTimestamps(text, totalDuration);

  return {
    blob: wavBlob,
    url: URL.createObjectURL(wavBlob),
    pcmData: finalPcm,
    timestamps
  };
}

