    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);
    const handleEnded = () => setIsPlaying(false);

    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);
    audio.addEventListener('play', handlePlay);
    audio.addEventListener('pause', handlePause);
    audio.addEventListener('ended', handleEnded);

    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
      audio.removeEventListener('play', handlePlay);
      audio.removeEventListener('pause', handlePause);
      audio.removeEventListener('ended', handleEnded);
    };
  }, [audioResult]);

  const activeWordIndex = useMemo(() => {
    if (!audioResult) return -1;
    return audioResult.timestamps.findIndex(t => 
      currentTime >= t.startTime && currentTime <= (t.startTime + t.duration)
    );
  }, [currentTime, audioResult]);

  const togglePlayback = () => {
    if (!audioRef.current) return;
    if (isPlaying) audioRef.current.pause();
    else audioRef.current.play();
  };

  const handleWaveformClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!waveformRef.current || !audioRef.current) return;
    const rect = waveformRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const percentage = x / rect.width;
    audioRef.current.currentTime = percentage * duration;
  };

  const waveformPeaks = useMemo(() => {
    if (!audioResult?.pcmData) return [];
    const samples = new Int16Array(audioResult.pcmData.buffer);
    const width = 300; 
    const bucketSize = Math.floor(samples.length / width);
    const peaks: number[] = [];
    for (let i = 0; i < width; i++) {
      let max = 0;
      for (let j = 0; j < bucketSize; j++) {
        const val = Math.abs(samples[i * bucketSize + j]);
        if (val > max) max = val;
      }
      peaks.push(Math.min(max / 18000, 1)); 
    }
    return peaks;
  }, [audioResult]);

  const formatTime = (time: number) => {
    const min = Math.floor(time / 60);
    const sec = Math.floor(time % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-[#FDFDFF] text-slate-800 font-['Inter'] flex flex-col h-screen overflow-hidden">
      {/* Header */}
      <header className="bg-white border-b border-slate-100 py-3 px-8 flex justify-between items-center z-40 shadow-sm flex-shrink-0">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100">
            <WaveIcon />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight leading-none text-slate-900">VoxGen <span className="text-indigo-600">ULTRA</span></h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mt-0.5">Engine v2.5 Stabilized</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold hover:bg-white hover:border-indigo-200 transition-all text-slate-500">
            <UploadIcon /> Importer
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <div className="h-8 w-[1px] bg-slate-100 mx-1"></div>
          <div className="flex items-center gap-2 px-3 bg-emerald-50 text-emerald-700 rounded-lg text-[10px] font-bold border border-emerald-100">
            <CheckIcon /> ENGINE CORE: STABLE
          </div>
        </div>
      </header>

      {/* Main Workspace */}
      <main className="flex-1 flex overflow-hidden bg-slate-50/20">
        <section className="w-[40%] flex flex-col border-r border-slate-100 bg-white shadow-2xl z-20 overflow-hidden">
          <div className="px-6 py-3 border-b border-slate-50 flex justify-between items-center bg-slate-50/40">
            <div className="flex items-center gap-2.5">
              <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.6)]"></div>
              <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Workspace</h3>
            </div>
            <div className="flex gap-1.5">
               <button onClick={handleManualPause} className="flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-[9px] font-black text-slate-600 hover:border-indigo-400 shadow-sm transition-all">
                <ClockIcon /> PAUSE
              </button>
               <button 
                onClick={handleEnhanceScript} 
                disabled={isEnhancing || !text.trim()} 
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[9px] font-black transition-all border ${isEnhancing ? 'bg-indigo-50 border-indigo-100 text-indigo-400' : 'bg-white border-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white'}`}
              >
                {isEnhancing ? <LoadingSpinner className="w-3 h-3 text-indigo-400" /> : <MagicIcon />} OPTIMISER
              </button>
              <button onClick={() => setText('')} className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all">
                <EraserIcon />
              </button>
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden relative group">
            <div className="flex-1 flex overflow-hidden">
                <div ref={lineNumbersRef} className="w-12 bg-slate-50/50 border-r border-slate-100 text-right pr-3 pt-6 text-[10px] font-bold text-slate-300 select-none overflow-hidden">
                  {Array.from({ length: lineCount }).map((_, i) => (
                    <div key={i} className="h-7 leading-7 tabular-nums">{i + 1}</div>
                  ))}
                </div>

                <textarea 
                  ref={textareaRef}
                  onScroll={handleScroll}
                  className="flex-1 p-6 text-[17px] font-medium text-slate-700 bg-white border-none focus:ring-0 outline-none transition-all resize-none leading-7 placeholder:text-slate-200 custom-scrollbar"
                  placeholder="Saisissez votre script professionnel..."
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                  spellCheck={false}
                />
            </div>
            <div className="absolute bottom-6 right-8 left-20 pointer-events-none">
              <div className="flex items-center justify-between">
                <div className="flex gap-2">
                   {detectedStyle && (
                    <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 border border-indigo-100/50 px-2.5 py-1 rounded-md uppercase tracking-widest shadow-sm">
                      STYLE: {detectedStyle}
                    </span>
                  )}
                </div>
                <div className="bg-white/90 border border-slate-100 px-3 py-1.5 rounded-xl shadow-lg flex gap-3 text-[10px] font-black text-slate-600">
                  <span>{wordCount} MOTS</span>
                  <span>{text.length} CAR.</span>
                </div>
              </div>
            </div>
          </div>
        </section>

        <section className="flex-1 flex flex-col bg-[#F9FAFF] border-r border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-50 bg-white shadow-sm flex flex-col gap-4">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <AudioIcon />
                <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Library</h3>
              </div>
              <button onClick={() => setIsAutoVoice(!isAutoVoice)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black transition-all flex items-center gap-2 ${isAutoVoice ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-slate-100 text-slate-500'}`}>
                {isAutoVoice && <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse"></span>}
                AUTO-VOICE {isAutoVoice ? 'ACTIVE' : 'OFF'}
              </button>
            </div>
            <div className="relative">
              <div className="absolute inset-y-0 left-3.5 flex items-center text-slate-300"><SearchIcon /></div>
              <input type="text" placeholder="Rechercher une voix..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 text-[12px] font-medium outline-none transition-all focus:bg-white" />
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
            {filteredVoices.map(voice => (
              <div key={voice.id} onClick={() => { setSelectedVoiceId(voice.id); setIsAutoVoice(false); }} className={`p-5 rounded-2xl border-2 transition-all cursor-pointer group ${selectedVoiceId === voice.id ? 'bg-white border-indigo-600 shadow-xl shadow-indigo-200/20' : 'bg-white border-slate-100 shadow-sm'}`}>
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className={`p-3 rounded-xl transition-colors ${selectedVoiceId === voice.id ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400 group-hover:text-indigo-600'}`}>
                      <AudioIcon />
                    </div>
                    <div>
                      <h4 className={`font-black text-[15px] ${selectedVoiceId === voice.id ? 'text-indigo-900' : 'text-slate-900'}`}>{voice.label}</h4>
                      <div className="flex gap-1.5 mt-1">
                        {voice.tags.slice(0, 2).map(t => <span key={t} className="text-[8px] font-bold px-1.5 py-0.5 bg-slate-50 text-slate-400 rounded-md border border-slate-100">{t}</span>)}
                      </div>
                    </div>
                  </div>
                  <button onClick={(e) => handleVoicePreview(e, voice)} className="p-2 rounded-lg bg-slate-50 text-slate-400 hover:bg-indigo-600 hover:text-white transition-all"><PlayIcon className="w-3.5 h-3.5" /></button>
                </div>
              </div>
            ))}
          </div>
        </section>

        <section className="w-[20%] flex flex-col bg-white overflow-y-auto custom-scrollbar border-l border-slate-100 shadow-sm z-30">
          <div className="flex border-b border-slate-100 bg-slate-50/30">
            <button onClick={() => setActiveTab('stability')} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'stability' ? 'text-indigo-600 bg-white border-b-2 border-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>Engine</button>
            <button onClick={() => setActiveTab('pronunciation')} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'pronunciation' ? 'text-indigo-600 bg-white border-b-2 border-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>Lexique</button>
            <button onClick={() => setActiveTab('synchro')} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'synchro' ? 'text-indigo-600 bg-white border-b-2 border-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>Sync</button>
          </div>

          {activeTab === 'stability' && (
            <div className="p-6 space-y-8 animate-fadeIn">
              <div className="space-y-4">
                 <label className="text-[9px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-indigo-600 animate-pulse"></div> PARAMÈTRES CRITIQUES</label>
                 <div className="space-y-4 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div className="flex items-center justify-between">
                      <span className="text-[10px] font-bold text-slate-600">STABILITÉ</span>
                      <span className="text-indigo-600 font-black text-[11px]">{Math.round(acousticConfig.stability * 100)}%</span>
                    </div>
                    <input type="range" min="0" max="1" step="0.1" value={acousticConfig.stability} onChange={(e) => setAcousticConfig({...acousticConfig, stability: parseFloat(e.target.value)})} className="w-full h-1 bg-white border border-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />

                    <label className="flex items-center gap-3 cursor-pointer group pt-2">
                       <input type="checkbox" checked={acousticConfig.enableMastering} onChange={(e) => setAcousticConfig({...acousticConfig, enableMastering: e.target.checked})} className="w-4 h-4 text-indigo-600 border-slate-200 rounded" />
                       <div className="flex-1">
                          <div className="text-[10px] font-black text-slate-700">MASTERING AUDIO</div>
                          <div className="text-[8px] text-slate-400">Normalisation automatique du gain</div>
                       </div>
                    </label>
                 </div>
              </div>

              <div className="space-y-4">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Options Avancées</label>
                <div className="space-y-2">
                  {[
                    { id: 'isSegmented', label: 'Rendu Parallèle', desc: 'Génération multi-threadée' },
                    { id: 'addFinalPadding', label: 'Anti-Compression Finale', desc: 'Padding de 500ms' },
                    { id: 'normalizeText', label: 'Normalisation Moteur', desc: 'Nettoyage des tokens' }
                  ].map(opt => (
                    <label key={opt.id} className="flex items-center p-3 bg-white border border-slate-100 rounded-xl cursor-pointer hover:border-indigo-200 transition-all group">
                      <div className="flex-1 text-[10px] font-black text-slate-700">{opt.label}</div>
                      <input type="checkbox" checked={(acousticConfig as any)[opt.id]} onChange={(e) => setAcousticConfig({...acousticConfig, [opt.id]: e.target.checked})} className="w-4 h-4 text-indigo-600" />
                    </label>
                  ))}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Langue de Rendu</label>
                <div className="grid grid-cols-2 gap-2">
                  {LANGS.map(l => (
                    <button key={l.id} onClick={() => { setLanguage(l.id); setIsAutoVoice(false); }} className={`py-2 px-1 rounded-lg text-[10px] font-bold border-2 transition-all ${language === l.id ? 'bg-indigo-50 border-indigo-600 text-indigo-700 shadow-sm' : 'bg-white border-slate-50 text-slate-400 hover:border-indigo-100'}`}>
                      {l.flag} {l.id.substring(0, 3).toUpperCase()}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'pronunciation' && (
            <div className="p-6 space-y-6 animate-fadeIn">
               <label className="text-[9px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-2"><BookIcon /> LEXIQUE</label>
               <div className="space-y-3 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <input type="text" placeholder="Mot original" value={newRuleWord} onChange={(e) => setNewRuleWord(e.target.value)} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-[12px] outline-none" />
                  <input type="text" placeholder="Phonétique" value={newRulePhonetic} onChange={(e) => setNewRulePhonetic(e.target.value)} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-[12px] outline-none" />
                  <button onClick={handleAddPronunciation} className="w-full py-2 bg-indigo-600 text-white rounded-lg text-[10px] font-black uppercase hover:bg-indigo-700 flex items-center justify-center gap-2"><PlusIcon /> AJOUTER</button>
               </div>
               <div className="space-y-2">
                  {pronunciationRules.map(rule => (
                    <div key={rule.id} className="p-3 bg-white border border-slate-100 rounded-xl flex justify-between items-center group">
                      <div className="min-w-0">
                        <div className="text-[11px] font-black text-slate-900 truncate">{rule.word}</div>
                        <div className="text-[10px] font-bold text-indigo-500 italic truncate">➜ {rule.phonetic}</div>
                      </div>
                      <button onClick={() => removePronunciation(rule.id)} className="p-1.5 text-slate-200 hover:text-red-500 transition-all opacity-0 group-hover:opacity-100"><TrashIcon size={14} /></button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {activeTab === 'synchro' && (
            <div className="p-6 space-y-6 animate-fadeIn h-full flex flex-col">
               <label className="text-[9px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-2"><SparklesIcon /> HIGHLIGHTER</label>
               {audioResult ? (
                 <div className="flex-1 bg-slate-50 border border-slate-100 rounded-2xl p-4 overflow-y-auto custom-scrollbar">
                    <div className="flex flex-wrap gap-1.5 leading-relaxed text-[13px]">
                        {audioResult.timestamps.map((t, i) => (
                            <span key={i} className={`px-1 rounded transition-all duration-150 ${activeWordIndex === i ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 scale-110' : 'text-slate-400'}`}>{t.word}</span>
                        ))}
                    </div>
                 </div>
               ) : (
                 <div className="flex-1 border-2 border-dashed border-slate-100 rounded-2xl flex flex-col items-center justify-center p-8 text-center"><div className="p-4 bg-slate-50 rounded-full mb-4 text-slate-300"><SparklesIcon /></div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Prêt pour synchronisation</p></div>
               )}
            </div>
          )}
        </section>
      </main>

      <footer className="bg-white border-t border-slate-100 p-6 shadow-2xl z-50 flex-shrink-0">
        <div className="max-w-[1400px] mx-auto flex items-center gap-10">
          <div className="flex-1">
            {audioResult ? (
              <div className="bg-white rounded-2xl p-5 border-2 border-indigo-100 flex flex-col gap-4 animate-slideUp shadow-xl">
                <div className="flex items-center gap-6">
                  <button onClick={togglePlayback} className="p-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 transition-all shadow-lg active:scale-95">{isPlaying ? <PauseIcon className="w-5 h-5" /> : <PlayIcon className="w-5 h-5" />}</button>
                  <div className="flex-1">
                    <div className="flex justify-between items-center mb-2">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">RENDERED MASTER</span>
                        {acousticConfig.enableMastering && <div className="px-2 py-0.5 bg-indigo-50 text-indigo-500 rounded text-[8px] font-bold">NORMALIZED</div>}
                      </div>
                      <div className="flex items-center gap-3">
                        <span className="text-[11px] font-black text-slate-400 tabular-nums">{formatTime(currentTime)} / {formatTime(duration)}</span>
                        <button onClick={() => setAudioResult(null)} className="p-1 text-slate-200 hover:text-red-500 transition-all"><TrashIcon size={16} /></button>
                      </div>
                    </div>
                    <div ref={waveformRef} onClick={handleWaveformClick} className="h-12 w-full flex items-center gap-[2px] cursor-pointer group">
                      {waveformPeaks.map((peak, idx) => {
                        const progress = (currentTime / duration) * 100;
                        const isPlayed = (idx / waveformPeaks.length) * 100 < progress;
                        return (
                          <div key={idx} className={`flex-1 rounded-full transition-all duration-300 ${isPlayed ? 'bg-indigo-600' : 'bg-slate-100 group-hover:bg-slate-200'}`} style={{ height: `${Math.max(peak * 100, 10)}%`, opacity: isPlayed ? 1 : 0.6 }} />
                        );
                      })}
                    </div>
                  </div>
                </div>
                <audio ref={audioRef} src={audioResult.url} className="hidden" />
              </div>
            ) : (
              <div className="bg-slate-50/40 rounded-2xl p-7 border-2 border-dashed border-slate-100 flex items-center justify-center"><p className="text-slate-400 text-[11px] font-black uppercase tracking-widest flex items-center gap-3"><div className="w-2 h-2 rounded-full bg-slate-200 animate-pulse"></div>Studio prêt</p></div>
            )}
          </div>

          <div className="w-80 flex flex-col gap-3">
             <div className="flex items-center justify-between px-1">
               <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">FORMAT</span>
               <div className="flex bg-slate-100 p-1 rounded-lg gap-1">
                  {['MP3', 'WAV'].map(f => (
                    <button key={f} onClick={() => setExportFormat(f as any)} className={`px-4 py-1 rounded-md text-[9px] font-black transition-all ${exportFormat === f ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>{f}</button>
                  ))}
               </div>
             </div>
             <div className="flex gap-2">
                <button onClick={handleGenerate} disabled={!text.trim() || isGenerating} className={`flex-1 py-4 rounded-2xl font-black text-sm shadow-2xl transition-all ${isGenerating ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-indigo-900 text-white hover:bg-black hover:-translate-y-1'}`}>
                  {isGenerating ? (
                    <div className="flex items-center justify-center gap-2"><LoadingSpinner className="h-4 w-4 text-indigo-600" /><span className="text-[10px] uppercase tracking-widest">{genStage}</span></div>
                  ) : (
                    <span className="flex items-center justify-center gap-2 tracking-[0.1em] font-black text-[11px]">RENDRE MASTER STABLE <PlayIcon className="w-4 h-4" /></span>
                  )}
                </button>
                {audioResult && (
                  <button onClick={handleDownload} className="px-5 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm shadow-2xl hover:bg-indigo-700 transition-all flex items-center justify-center"><DownloadIcon /></button>
                )}
             </div>
             {error && <p className="text-[9px] text-red-500 font-bold text-center uppercase tracking-tighter">{error}</p>}
          </div>
        </div>
      </footer>

      <style>{`
        @keyframes slideUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-slideUp { animation: slideUp 0.4s ease-out forwards; }
        .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #eef2f6; border-radius: 10px; }
        input[type=range].accent-indigo-600::-webkit-slider-thumb {
          -webkit-appearance: none; height: 12px; width: 12px; border-radius: 100%; background: #4f46e5; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(79, 70, 229, 0.3);
        }
      `}</style>
    </div>
  );
};

export default App;
